using Lite.Conformance.Wpt;
using Lite.Extensions;
using Lite.Layout;
using Lite.Models;
using SkiaSharp;

namespace Lite.Conformance.Css21;

/// <summary>A machine-checkable reading of a self-describing case's stated pass condition,
/// generated by <c>scripts/gen_css21_pass_conditions.py</c> from the sentence's template.
/// <list type="bullet">
/// <item><c>one-shape</c>: exactly one top-level rectangular shape below the instructions
/// (a <c>square</c> has equal sides; a named <c>color</c> must be its dominant color).</item>
/// <item><c>same-dimension</c>: two or more top-level rectangles (exactly <c>count</c> when
/// stated) whose <c>dimension</c> — width, height, or size — is equal.</item>
/// <item><c>bar-gap</c>: three bars; the middle one is as wide as the gap between the
/// outer two.</item>
/// <item><c>line-style</c>: one dashed or dotted line (<c>Shape</c>) — at least three
/// collinear segments in one row (horizontal) or column (vertical, when <c>Dimension</c>
/// says so), each dash longer than it is thick and each dot about as long as thick, in the
/// stated <c>color</c>.</item>
/// <item><c>look-same</c>: exactly two top-level shapes of the same dimensions whose pixels
/// match within antialiasing tolerance.</item>
/// <item><c>solid-line</c>: one line-shaped component in the stated <c>color</c> ("or shades
/// of" admits hue-preserving antialiasing shades; achromatic names admit any gray of the
/// right lightness).</item>
/// <item><c>border-ring</c>: every top-level shape lies on the perimeter of one rectangle,
/// each side covered, and the interior segments shaped per the stated dashed/dotted
/// <c>Shape</c> in the stated <c>color</c>.</item>
/// <item><c>border-sample</c>: the <c>#center</c> element's painted border ring reads as the
/// border-style word its own text states, and matches the <c>#table1</c> sample ring's
/// thickness and color when that sample exists.</item>
/// <item><c>text-color</c>: the "Filler Text" element's ink is the stated <c>color</c>.</item>
/// <item><c>text-decoration</c>: the "Filler Text" element has (or, when <c>under</c> is
/// false, has not) the stated over/under/through lines as render bands.</item>
/// <item><c>align-right</c>: the "Filler Text" ink's right edge sits on its container's
/// content-box right edge.</item>
/// <item><c>shape-relation</c>: the stated-color shapes satisfy <c>relation</c> —
/// larger/smaller (area), beneath (stacked with overlap), centered-right (inside, vertically
/// centered, flush right), height-similar (equal heights), no-vertical-gap (touching top to
/// bottom); an optional <c>lineColor</c> line must not touch either box.</item>
/// <item><c>space-between</c>: two or more boxes with the region between consecutive boxes
/// painted in the stated <c>color</c>.</item>
/// <item><c>stack-three</c>: three same-width rectangles stacked vertically.</item>
/// <item><c>two-size</c>: two rectangles, one at least 1.5× the other's area.</item>
/// </list></summary>
internal sealed record SideSpec(string? Style, string? Color);

/// <summary>A scroll protocol for a check whose stated condition involves the scrolled
/// state of an overflow box ("when the box is scrolled down…"). The harness renders once,
/// applies the scroll to the box's layout scroll state, renders again, and hands both
/// bitmaps to the judge. <c>Then</c> adds a second scroll applied to the intermediate
/// render (scroll down, then right) for conditions that name both axes.</summary>
internal sealed record ScrollSpec(string To, string? Then = null);

/// <summary>The renders a two-phase scroll protocol produces: the initial page, the
/// intermediate state after <see cref="ScrollSpec.To"/> (null without a scroll protocol),
/// and the final state after <see cref="ScrollSpec.Then"/> (null without it). <c>Paint</c>
/// carries the text the final render drew (the paint log) for glyph-order judges.</summary>
internal sealed record RenderSet(SKBitmap Final, SKBitmap? Mid, SKBitmap? Before,
    IReadOnlyList<Lite.Rendering.PaintLog.Entry>? Paint = null);

    internal sealed record VisualCheck(string Kind, string? Shape = null, string? Color = null,
    string? Dimension = null, int? Count = null, string? ColorA = null, string? ColorB = null,
    string? Relation = null, string? LineColor = null, bool? Over = null, bool? Under = null, bool? Through = null,
    string? Variant = null, string? FirstShape = null, string? FirstColor = null, string? SecondShape = null,
    string? SecondColor = null, string? Arrangement = null, bool Approx = false, string? Anchor = null,
    string? ColorC = null, string? BulletColor = null, string? Needle = null, string? Side = null,
    string? Edge = null, string? Span = null, string? Mode = null, string? Scope = null, bool Even = false,
    bool Shades = false, bool Marker = false, string? Bullet = null, int? Rows = null, int? Cols = null,
    List<string>? Colors = null, List<string>? Needles = null, Dictionary<string, SideSpec>? Sides = null,
    bool Ordered = false, string? BoxColor = null, string? Target = null, ScrollSpec? Scroll = null);

/// <summary>Evaluates a <see cref="VisualCheck"/> literally and strictly against the rendered
/// page: the region below the instruction paragraph is segmented into connected components
/// of ink (pixels that differ from the region's background). Antialiasing is the only slack —
/// faint fringes below <see cref="InkThreshold"/> are background, a rectangle's corner
/// pixels may be missing, and edges may differ by <see cref="EdgeTolerance"/> px. Whatever
/// the check cannot see (no instruction paragraph, ink clipped at the viewport edge) is
/// unsupported, never a pass.</summary>
internal static class VisualChecks
{
    internal const int InkThreshold = 16;
    internal const int EdgeTolerance = 1;
    internal const int JoinThreshold = 48;
    /// <summary>Slack for the pixel comparison of a "look the same" pair and for the
    /// hue-preserving shade tolerance of "or shades of &lt;color&gt;" lines.</summary>
    internal const int PixelTolerance = 16;
    internal const int ShadeTolerance = 112;

    internal readonly record struct Component(int Left, int Top, int Right, int Bottom, bool Rectangular, SKColor Color)
    {
        public int Width => Right - Left;
        public int Height => Bottom - Top;
        public bool Contains(Component other) => !Equals(other) &&
            other.Left >= Left && other.Top >= Top && other.Right <= Right && other.Bottom <= Bottom;
        public bool Intersects(Component other) =>
            Left < other.Right && other.Left < Right && Top < other.Bottom && other.Top < Bottom;
    }

    private static readonly Dictionary<string, SKColor> Named = new(StringComparer.Ordinal)
    {
        ["maroon"] = new(0x80, 0, 0), ["red"] = new(0xff, 0, 0), ["orange"] = new(0xff, 0xa5, 0),
        ["yellow"] = new(0xff, 0xff, 0), ["olive"] = new(0x80, 0x80, 0), ["purple"] = new(0x80, 0, 0x80),
        ["fuchsia"] = new(0xff, 0, 0xff), ["white"] = new(0xff, 0xff, 0xff), ["lime"] = new(0, 0xff, 0),
        ["green"] = new(0, 0x80, 0), ["navy"] = new(0, 0, 0x80), ["blue"] = new(0, 0, 0xff),
        ["aqua"] = new(0, 0xff, 0xff), ["teal"] = new(0, 0x80, 0x80), ["black"] = new(0, 0, 0),
        ["silver"] = new(0xc0, 0xc0, 0xc0), ["gray"] = new(0x80, 0x80, 0x80), ["grey"] = new(0x80, 0x80, 0x80),
    };

    private static readonly HashSet<string> Achromatic = ["white", "black", "silver", "gray", "grey"];
    private static readonly HashSet<string> SampleStyles = ["solid", "dashed", "dotted", "double", "none", "hidden"];

    internal static WptRunner.RunResult Evaluate(VisualCheck check, RenderSet renders, LayoutNode root, string sentence, string path)
    {
        // Scroll-protocol checks judge the scrolled render against the initial one; the
        // region is the scroll box itself, not the area below the instructions.
        if (check.Scroll is not null || check.Kind.StartsWith("scroll-", StringComparison.Ordinal))
            return ScrollCheck(check, renders, root, path);
        var bitmap = renders.Final;
        if (InstructionBottom(root, sentence) is not { } top)
            return new(WptRunner.Cat.Unsupported, "Visual check: instruction paragraph not found in the layout tree", 0, 0);
        // Fail-closed color names: every stated colour must be a CSS keyword the judges know.
        // A template extraction that captured prose ("black text") used to crash the render
        // worker on the Named lookup (user-stylesheet-005/006/010); an unreadable colour is an
        // honest unsupported — the sentence needs a stricter template, never a crash.
        var statedColors = (check.Color is { } c ? [c] : Array.Empty<string>())
            .Concat(check.Colors ?? []).Concat(check.ColorA is { } a ? [a] : Array.Empty<string>())
            .Concat(check.ColorB is { } b ? [b] : Array.Empty<string>());
        if (statedColors.FirstOrDefault(name => !Named.ContainsKey(name)) is { } unknown)
            return new(WptRunner.Cat.Unsupported, $"Visual check: stated colour '{unknown}' is not a keyword the judges read", 0, 0);
        // Glyph-order judges read the paint log (what the painter actually drew); the rest
        // read the render.
        WptRunner.RunResult result = check.Kind switch
        {
            "painted-text" => PaintedText(check, renders.Paint, top),
            "painted-order" => PaintedOrder(check, renders.Paint, top),
            "painted-font" => PaintedFont(check, renders.Paint, top),
            "painted-only" => PaintedOnly(check, renders.Paint, top),
            "painted-sequence" => PaintedSequence(check, renders.Paint, top),
            "first-line-wider" => FirstLineWider(check, bitmap, top),
            "text-in-corner" => TextInCorner(check, bitmap, root, top),
            "text-in-box" => TextInBox(check, bitmap, root, top),
            "box-beside-text" => BoxBesideText(check, bitmap, root, top),
            "hanging-indent" => HangingIndent(check, bitmap, top),
            "no-scrollbar" => NoScrollbar(check, bitmap),
            "scrollbar-visible" => ScrollbarVisible(check, bitmap, root),
            "same-width-corner" => SameWidthCorner(check, bitmap, top),
            "striped-fill" => StripedFill(check, bitmap, top),
            "same-alignment" => SameAlignment(check, bitmap, top),
            "page-background" => PageBackground(check, bitmap),
            "presence" => Presence(check, bitmap, top),
            "cats-on-bar" => CatsOnBar(check, bitmap, top),
            "middle-cell-color" => MiddleCellColor(check, bitmap, root, top),
            "gradient-lighter" => ComponentCheck(check, bitmap, top, path),
            "spans-stack" => ComponentCheck(check, bitmap, top, path),
            "border-sample" => BorderSample(check, bitmap, root, path),
            "text-color" => TextColor(check, bitmap, root, top, sentence),
            "text-color-pairs" => TextColorPairs(check, bitmap, root, top),
            "text-decoration" => TextDecoration(check, bitmap, root, top, path),
            "align-right" => AlignRight(check, bitmap, root, top, path),
            "letter-x" => LetterX(check, bitmap, root, top, path),
            "outline-text" => OutlineText(check, bitmap, root, top, path),
            "text-baseline" => TextBaseline(check, bitmap, root, top, path),
            "one-line" => OneLine(bitmap, root, top, path),
            "first-line-marker" => FirstLineMarker(check, bitmap, root, top, path),
            "line-marker" => LineMarker(check, bitmap, top, path),
            "bullet-beside" => BulletBeside(check, bitmap, top, path),
            "bar-stack" => BarStack(check, bitmap, top, path),
            "text-marker" => TextMarker(check, bitmap, root, top, path),
            "numbers-present" => NumbersPresent(check, root, top, path),
            "text-ink" => TextInk(check, bitmap, root, top, path),
            "words-and-box" => WordsAndBox(check, bitmap, root, top, path),
            "align-center" => AlignCenter(check, bitmap, root, top, sentence, path),
            "lines-spaced" => LinesSpaced(check, bitmap, top, path),
            "lines-same" => LinesSame(check, bitmap, top, path),
            "image-tiled" => ImageTiled(check, bitmap, root, top, path),
            "bars-match" => BarsMatch(check, bitmap, top, path),
            "bar-grid" => BarGrid(check, bitmap, top, path),
            "viewport-bottom" => ViewportBottom(check, bitmap),
            "cell-border" => CellBorder(check, bitmap, root, top, path),
            "corners" => Corners(check, bitmap, top, path),
            "box-count" => BoxCount(check, bitmap, top, path),
            "three-bars" => ThreeBars(check, bitmap, top, path),
            "first-letter-color" => FirstLetterColor(check, bitmap, root, top, sentence, path),
            "first-line-color" => FirstLineColor(check, bitmap, top, path),
            "justify" => Justify(bitmap, top, path),
            "text-band" => TextBand(check, bitmap, root, top, sentence, path),
            "edge-letter" => EdgeLetter(check, bitmap, root, top, path),
            "stack-order" => StackOrder(check, bitmap, top, path),
            "no-ring" => NoRing(check, bitmap, root, top, path),
            "text-below-box" => TextBelowBox(check, root, top, path),
            "text-marker-match" => TextMarkerMatch(bitmap, root, top, path),
            "border-sides" => BorderSides(check, bitmap, top, path),
            _ => ComponentCheck(check, bitmap, top, path),
        };
        // Same switch as the reftest survey's failure dumps: read the render, not the numbers.
        // "all" also dumps passes, for auditing the checks themselves.
        if (Environment.GetEnvironmentVariable("LITE_SURVEY_DUMP") is { } dump && (dump == "all" || dump == "1" && !result.Passed))
        {
            var name = Path.GetFileNameWithoutExtension(path);
            using var data = bitmap.Encode(SKEncodedImageFormat.Png, 100);
            File.WriteAllBytes(Path.Combine(Lite.Conformance.Harness.ConformancePaths.EnsureArtifacts(),
                $"visual-check-{(result.Passed ? "pass" : "fail")}-{name}-top{top}.png"), data.ToArray());
        }
        return result;
    }

    // ------------------------------------------------------------------
    // Scroll-protocol checks
    // ------------------------------------------------------------------

    /// <summary>The layout node of the box the scroll protocol scrolled — the first
    /// document-order box (outside html/body) whose layout scroll state has overflow on
    /// either axis. The corpus's scroll cases have exactly one.</summary>
    internal static LayoutNode? FindScrollBox(LayoutNode node)
    {
        if (node.TagName is not ("HTML" or "BODY") && node.ScrollState is { } ss &&
            (ss.NeedsScrollbar || ss.NeedsHorizontalScrollbar))
            return node;
        foreach (var child in node.Children)
            if (FindScrollBox(child) is { } hit) return hit;
        return null;
    }

    /// <summary>Applies the check's scroll protocol to the layout: the named axis (or both
    /// for "bottom-right") scrolls to its maximum, the way a tester drags the scrollbar to
    /// the end. Returns the scrolled box, or null when no scrollable box rendered.</summary>
    internal static LayoutNode? ApplyScroll(ScrollSpec scroll, LayoutNode root)
    {
        var box = FindScrollBox(root);
        if (box?.ScrollState is not { } ss) return null;
        if (scroll.To is "bottom" or "bottom-right") ss.ScrollTo(ss.MaxScroll);
        if (scroll.To is "right" or "bottom-right") ss.ScrollXTo(ss.MaxScrollX);
        return box;
    }

    /// <summary>Page-level scroll extent for the "page-*" targets: the document's full
    /// extent minus the viewport — the way a tester drags the page scrollbars to the end.</summary>
    internal static (float ScrollX, float ScrollY) PageScrollExtent(string to, LayoutNode root, int width, int height)
    {
        var maxX = MathF.Max(0f, root.Box.BorderBox.Right - width);
        var maxY = MathF.Max(0f, root.Box.BorderBox.Bottom - height);
        return (to.Contains("right") ? maxX : 0f, to.Contains("bottom") ? maxY : 0f);
    }

    /// <summary>Scroll-state judges. The crop is the scroll box's padding box; the corpus's
    /// scroll cases tile the Microsoft cat image (black line art on white) over or behind a
    /// colored box, so "cat ink" is the white-and-black two-tone coverage inside the crop.
    /// Page-level ("page-*" scroll targets) judges read the whole viewport instead.</summary>
    private static WptRunner.RunResult ScrollCheck(VisualCheck check, RenderSet renders, LayoutNode root, string path)
    {
        var (after, mid, before) = (renders.Final, renders.Mid, renders.Before);
        if (before is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: scroll protocol did not produce a before render", 0, 0);
        if (check.Kind.StartsWith("scroll-page-", StringComparison.Ordinal))
            return PageScrollCheck(check, after, before, root);
        var box = FindScrollBox(root);
        if (box?.ScrollState is not { } ss)
            return new(WptRunner.Cat.Unsupported, "Visual check: no scrollable box rendered", 0, 0);
        var pb = box.Box.PaddingBox;
        var crop = SKRectI.Intersect(new SKRectI((int)pb.Left, (int)pb.Top, (int)pb.Right, (int)pb.Bottom),
            new SKRectI(0, 0, after.Width, after.Height));
        if (crop.Width < 20 || crop.Height < 20)
            return new(WptRunner.Cat.Unsupported, "Visual check: scroll box crop is empty or off-viewport", 0, 0);
        return check.Kind switch
        {
            "scroll-cats-bottom" => CatsBottom(check, after, before, crop),
            "scroll-cats-moved" => CatsMoved(check, after, before, crop),
            "scroll-cats-bottom-moved" => CatsBottomMoved(check, after, mid, before, crop),
            "scroll-cats-top-moved" => CatsTopMoved(check, after, before, crop),
            "scroll-cats-still" => CatsStill(check, after, before, crop),
            "scroll-box-text" => ScrollBoxText(check, root),
            "scroll-box-edges-visible" => ScrollBoxEdgesVisible(check, after, crop),
            "scroll-no-red" => Pass("no failure red in the scrolled box"),
            _ => new(WptRunner.Cat.Unsupported, $"Visual check: unknown scroll check '{check.Kind}'", 0, 0),
        };
    }

    /// <summary>"The box can be scrolled to the green square in the bottom-right corner":
    /// after the scroll, the stated color's ink bounding box lies wholly inside the
    /// scrollport crop.</summary>
    private static WptRunner.RunResult ScrollBoxEdgesVisible(VisualCheck check, SKBitmap after, SKRectI crop)
    {
        if (!Named.TryGetValue(check.Color ?? "green", out var target))
            return new(WptRunner.Cat.Unsupported, "Visual check: stated color is not a named color", 0, 0);
        int minL = after.Width, minT = after.Height, maxR = 0, maxB = 0;
        long hits = 0;
        for (int y = crop.Top; y < crop.Bottom; y++)
            for (int x = crop.Left; x < crop.Right; x++)
            {
                if (ChannelDistance(after.GetPixel(x, y), target) > 48) continue;
                hits++;
                minL = Math.Min(minL, x); minT = Math.Min(minT, y);
                maxR = Math.Max(maxR, x); maxB = Math.Max(maxB, y);
            }
        if (hits < 200)
            return Fail($"no {check.Color} ink is visible inside the scrolled box");
        if (minL <= crop.Left + 1 || minT <= crop.Top + 1 || maxR >= crop.Right - 1 || maxB >= crop.Bottom - 1)
            return Fail($"the {check.Color} box is clipped by the scrollport (({minL},{minT})..({maxR},{maxB}) in ({crop.Left},{crop.Top})..({crop.Right},{crop.Bottom}))");
        return Pass($"the {check.Color} box is wholly visible in the scrolled box");
    }

    /// <summary>"The box can be scrolled to the words 'Filler Text'": after the scroll-box
    /// protocol scrolls the overflow box to its end, the named text sits inside the
    /// scrollport's visible band (the box's layout coordinates shifted by the scroll).</summary>
    private static WptRunner.RunResult ScrollBoxText(VisualCheck check, LayoutNode root)
    {
        var box = FindScrollBox(root);
        if (box?.ScrollState is not { } ss)
            return new(WptRunner.Cat.Unsupported, "Visual check: no scrollable box rendered", 0, 0);
        if (check.Needle is not { } needle || FindTextBelow(box, needle) is not { } textNode)
            return new(WptRunner.Cat.Unsupported, "Visual check: the named text is not in the scroll box's subtree", 0, 0);
        var pb = box.Box.PaddingBox;
        var text = textNode.Box.BorderBox;
        var visible = text.Top - ss.ScrollY >= pb.Top - EdgeTolerance && text.Bottom - ss.ScrollY <= pb.Bottom + EdgeTolerance;
        return visible ? Pass($"the named text '{needle}' is inside the scrolled box")
            : Fail($"the named text '{needle}' is not inside the scrolled box (text {text.Top}..{text.Bottom}, scroll {ss.ScrollY})");
    }

    /// <summary>Whole-viewport judges for the page-scroll protocol: a stated-color box that
    /// must be fully visible after the scroll (once, always, or stuck at the top), or a named
    /// text the page must be scrollable to.</summary>
    private static WptRunner.RunResult PageScrollCheck(VisualCheck check, SKBitmap after, SKBitmap? before, LayoutNode root)
    {
        switch (check.Kind)
        {
            case "scroll-page-text":
                if (check.Needle is not { } needle || needle.Length == 0)
                    return new(WptRunner.Cat.Unsupported, "Visual check: scroll-to-text check names no needle", 0, 0);
                if (FindTextBelow(root, needle) is not { } textNode)
                    return new(WptRunner.Cat.Unsupported, "Visual check: the named text is not in the layout tree", 0, 0);
                // The layout boxes keep document coordinates; the page scroll brings the band
                // [ScrollY, ScrollY+height] x [ScrollX, ScrollX+width] into the viewport.
                var box = textNode.Box.BorderBox;
                var (sx, sy) = PageScrollExtent("page-bottom-right", root, after.Width, after.Height);
                var visible = box.Top >= sy - EdgeTolerance && box.Bottom <= sy + after.Height + EdgeTolerance &&
                              box.Left >= sx - EdgeTolerance && box.Right <= sx + after.Width + EdgeTolerance;
                return visible ? Pass($"the named text '{needle}' is inside the scrolled viewport")
                    : Fail($"the named text '{needle}' is not inside the scrolled viewport (box {box.Top}..{box.Bottom})");
            case "scroll-page-edges-visible":
            {
                if (ColorBounds(after, check.Color ?? "blue") is not { } bounds)
                    return Fail($"no {check.Color} ink is visible after scrolling");
                if (bounds.Left < 2 || bounds.Top < 2 || bounds.Right > after.Width - 2 || bounds.Bottom > after.Height - 2)
                    return Fail($"the {check.Color} box's edges reach the viewport edge ({bounds.Left},{bounds.Top})..({bounds.Right},{bounds.Bottom})");
                return Pass("all four edges of the box are inside the scrolled viewport");
            }
            case "scroll-page-always-visible":
            {
                if (ColorBounds(after, check.Color ?? "purple") is not { } afterBounds)
                    return Fail($"no {check.Color} ink is visible after scrolling");
                if (before is null) return new(WptRunner.Cat.Unsupported, "Visual check: no before render", 0, 0);
                if (ColorBounds(before, check.Color ?? "purple") is not { } beforeBounds)
                    return Fail($"no {check.Color} ink is visible before scrolling");
                foreach (var b in new[] { afterBounds, beforeBounds })
                    if (b.Left < 2 || b.Top < 2 || b.Right > after.Width - 2 || b.Bottom > after.Height - 2)
                        return Fail($"the {check.Color} box is clipped by the viewport ({b.Left},{b.Top})..({b.Right},{b.Bottom})");
                return Pass("the box is completely visible before and after scrolling");
            }
            case "scroll-page-stuck-top":
            {
                if (ColorBounds(before, check.Color ?? "blue", bandHeight: 80) is not { } beforeTop)
                    return Fail($"no {check.Color} band at the top of the viewport before scrolling");
                if (ColorBounds(after, check.Color ?? "blue", bandHeight: 80) is not { } afterTop)
                    return Fail($"no {check.Color} band at the top of the viewport after scrolling");
                if (Math.Abs(beforeTop.Top - afterTop.Top) > EdgeTolerance || Math.Abs(beforeTop.Bottom - afterTop.Bottom) > EdgeTolerance)
                    return Fail($"the top band moved with the page (before {beforeTop.Top}..{beforeTop.Bottom}, after {afterTop.Top}..{afterTop.Bottom})");
                return Pass("the top band holds the same position before and after scrolling");
            }
            case "scroll-page-no-red":
                // The red scan already ran on the final (scrolled) render — reaching here
                // means it found none, which is the whole stated condition.
                return Pass("no failure red in the scrolled viewport");
            default:
                return new(WptRunner.Cat.Unsupported, $"Visual check: unknown page-scroll check '{check.Kind}'", 0, 0);
        }
    }

    /// <summary>Bounding rows/columns of the named color's ink, optionally restricted to the
    /// viewport's top band. Null when the coverage is negligible.</summary>
    private static SKRectI? ColorBounds(SKBitmap bitmap, string colorName, int bandHeight = 0)
    {
        if (!Named.TryGetValue(colorName, out var target)) return null;
        int minL = bitmap.Width, minT = bitmap.Height, maxR = 0, maxB = 0;
        long hits = 0;
        int bottom = bandHeight > 0 ? Math.Min(bandHeight, bitmap.Height) : bitmap.Height;
        for (int y = 0; y < bottom; y++)
            for (int x = 0; x < bitmap.Width; x++)
            {
                var c = bitmap.GetPixel(x, y);
                if (ChannelDistance(c, target) <= 48)
                {
                    hits++;
                    minL = Math.Min(minL, x); minT = Math.Min(minT, y);
                    maxR = Math.Max(maxR, x); maxB = Math.Max(maxB, y);
                }
            }
        return hits >= 200 ? new SKRectI(minL, minT, maxR, maxB) : null;
    }

    /// <summary>The first layout node whose text contains the needle (whitespace-normalized),
    /// walking document order — the anchor of a scroll-to-text judge.</summary>
    private static LayoutNode? FindTextBelow(LayoutNode node, string needle)
    {
        var normalized = string.Join(' ', needle.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
        if (node.DisplayText is { } text && text.Replace('\u00A0', ' ').Contains(normalized, StringComparison.Ordinal) &&
            text.Length >= needle.Length)
            return node;
        foreach (var child in node.Children)
            if (FindTextBelow(child, needle) is { } hit) return hit;
        return null;
    }

    // ------------------------------------------------------------------
    // Paint-log judges (glyph-order evidence)
    // ------------------------------------------------------------------

    /// <summary>The paint log's lines in visual order: entries grouped by baseline band,
    /// each band's fragments ordered by x (the painter draws each fragment's text as one
    /// string), bands top to bottom.</summary>
    internal static List<string> PaintedLines(IReadOnlyList<Lite.Rendering.PaintLog.Entry>? paint)
    {
        var lines = new List<string>();
        if (paint is null || paint.Count == 0) return lines;
        foreach (var band in paint.OrderBy(e => e.BaselineY)
                     .GroupBy(e => MathF.Round(e.BaselineY / 4f)))
        {
            var text = string.Concat(band.OrderBy(e => e.X).Select(e => e.Text));
            if (text.Trim().Length > 0) lines.Add(text);
        }
        return lines;
    }

    private static string NormalizeLine(string text) =>
        string.Join(' ', text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));

    /// <summary>"There is a lowercase letter 'a.' below" and friends: the stated text is
    /// among the glyphs the painter drew below the instructions — the route for content a
    /// bitmap cannot read (list markers are painted, not layout text).</summary>
    private static WptRunner.RunResult PaintedText(VisualCheck check, IReadOnlyList<Lite.Rendering.PaintLog.Entry>? paint, int top)
    {
        // Entries at or above the instruction bottom are the instructions themselves.
        var below = paint?.Where(e => e.BaselineY > top).ToList() ?? new List<Lite.Rendering.PaintLog.Entry>();
        var painted = string.Join("\n", PaintedLines(below).Select(NormalizeLine));
        var needle = NormalizeLine(check.Needle ?? "");
        if (needle.Length == 0)
            return new(WptRunner.Cat.Unsupported, "Visual check: painted-text check names no needle", 0, 0);
        var assertion = Describe(check);
        // The needle is the sentence's quoted literal, lowercased by the generator ("AZ" -> "az");
        // the paint log carries the glyphs in their authored case. Case-word sentences ("a lowercase
        // letter 'a.'") state the requirement in prose, not in the needle, so the fold is safe.
        return painted.Contains(needle, StringComparison.OrdinalIgnoreCase)
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: the painted text does not contain '{needle}'", 1, 1,
                [new(assertion, 1, $"painted: {Truncate(painted)}")], 0);
    }

    private static string Truncate(string text) => text.Length <= 160 ? text : text[..157] + "...";

    /// <summary>The bidi char-order family: the stated condition names the visual order the
    /// glyphs must paint in (read off the case's reference image by the reviewed expectation).
    /// The judge reconstructs the painted visual order of the line and compares sequences.</summary>
    private static WptRunner.RunResult PaintedOrder(VisualCheck check, IReadOnlyList<Lite.Rendering.PaintLog.Entry>? paint, int top)
    {
        var expected = NormalizeLine(check.Needle ?? "");
        if (expected.Length == 0)
            return new(WptRunner.Cat.Unsupported, "Visual check: painted-order check carries no reviewed expectation", 0, 0);
        var below = paint?.Where(e => e.BaselineY > top).ToList() ?? new List<Lite.Rendering.PaintLog.Entry>();
        var lines = PaintedLines(below).Select(NormalizeLine).ToList();
        // The bidi line is the one with non-ASCII script content; plain-ASCII lines are
        // surrounding text.
        var candidate = lines.FirstOrDefault(l => l.Any(c => c > 0x7F));
        var assertion = Describe(check);
        if (candidate is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no painted line carries the bidi text", 0, 0);
        return candidate == expected
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: painted order does not match the reviewed glyph order", 1, 1,
                [new(assertion, 1, $"painted: {Truncate(candidate)} expected: {Truncate(expected)}")], 0);
    }

    /// <summary>The c527 font sentences state the size, the style, the family, and the
    /// baseline pitch together. The paint log reads all four from what the painter drew:
    /// <c>Count</c> size, <c>Mode</c> bold/italic/smallcaps, <c>Edge</c> baseline pitch,
    /// <c>Shape</c> a concrete family name (generic families stay unjudged — the resolved
    /// concrete name is a UA choice).</summary>
    private static WptRunner.RunResult PaintedFont(VisualCheck check, IReadOnlyList<Lite.Rendering.PaintLog.Entry>? paint, int top)
    {
        var below = paint?.Where(e => e.BaselineY > top).ToList() ?? new List<Lite.Rendering.PaintLog.Entry>();
        if (below.Count == 0)
            return new(WptRunner.Cat.Unsupported, "Visual check: the paint log is empty below the instructions", 0, 0);
        var assertion = Describe(check);
        if (check.Count is { } size)
        {
            var wrong = below.Where(e => Math.Abs(e.Size - size) > 0.6f).ToList();
            if (wrong.Count == below.Count)
                return Fail2(assertion, $"every painted run is {below[0].Size}px, the sentence states {size}px");
        }
        if (check.Mode is { } mode)
        {
            var mismatch = mode switch
            {
                "bold" => below.All(e => !e.Bold),
                "italic" => below.All(e => !e.Italic),
                "normal" => below.All(e => e.Bold || e.Italic),
                _ => false,
            };
            if (mismatch)
                return Fail2(assertion, $"no painted run resolved the stated {mode} face (families: {below[0].Typeface})");
        }
        if (check.Edge is { } pitchText && float.TryParse(pitchText, System.Globalization.CultureInfo.InvariantCulture, out var pitch))
        {
            var baselines = below.Select(e => e.BaselineY).Distinct().OrderBy(v => v).ToList();
            if (baselines.Count < 2)
                return new(WptRunner.Cat.Unsupported, "Visual check: only one painted line; no baseline pitch to read", 0, 0);
            var gaps = baselines.Zip(baselines.Skip(1), (a, b) => b - a).ToList();
            if (gaps.Any(g => Math.Abs(g - pitch) > 1.5f))
                return Fail2(assertion, $"baseline gaps [{string.Join(", ", gaps.Select(g => $"{g:F1}"))}] do not state {pitch}px");
        }
        if (check.Shape is { } family && family is not ("serif" or "sans-serif" or "cursive" or "monospace" or "fantasy"))
        {
            if (!below.Any(e => e.Typeface.Contains(family, StringComparison.OrdinalIgnoreCase)))
                return Fail2(assertion, $"no painted run uses '{family}' (families: {below[0].Typeface})");
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    private static WptRunner.RunResult Fail2(string assertion, string detail) =>
        new(WptRunner.Cat.Fail, $"{assertion}: {detail}", 1, 1, [new(assertion, 1, detail)], 0);

    /// <summary>"There are only quotes below" / "only the words 'PASS PASS' appear": every
    /// glyph the painter drew below the instructions belongs to the allowed set — quote
    /// punctuation only, or exactly the stated words.</summary>
    private static WptRunner.RunResult PaintedOnly(VisualCheck check, IReadOnlyList<Lite.Rendering.PaintLog.Entry>? paint, int top)
    {
        var below = paint?.Where(e => e.BaselineY > top).ToList() ?? new List<Lite.Rendering.PaintLog.Entry>();
        var painted = string.Concat(PaintedLines(below));
        var allowed = check.Needles is { Count: > 0 } needles
            ? string.Join(" ", needles)
            : "\"'\u2018\u2019\u201C\u201D\u00AB\u00BB\u2039\u203A\u00A0\u200E\u200F";
        var allowedTokens = allowed.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries)
            .Select(t => t.Trim(',')).Where(t => t.Length > 0).ToHashSet(StringComparer.Ordinal);
        var tokens = painted.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries)
            .Select(t => t.Trim(',')).Where(t => t.Length > 0).ToList();
        var stray = tokens.Where(t => !allowedTokens.Contains(t)).ToList();
        return stray.Count == 0
            ? new(WptRunner.Cat.Pass, Describe(check), 1, 0, [new(Describe(check), 0, null)], 0)
            : Fail2(Describe(check), $"painted text holds non-allowed tokens: {Truncate(string.Join(' ', stray.Take(6)))}");
    }

    /// <summary>"There is a cat sitting on a green bar below": a green bar with the cat's
    /// black line-art strokes in the band directly above it.</summary>
    private static WptRunner.RunResult CatsOnBar(VisualCheck check, SKBitmap bitmap, int top)
    {
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var bars = TopLevel(components).Where(s => s.Width >= 40 && s.Height >= 8 && Matches(check.Color ?? "green", s.Color)).ToList();
        var assertion = Describe(check);
        if (bars.Count == 0)
            return Fail2(assertion, $"no {check.Color} bar below the instructions");
        foreach (var bar in bars)
        {
            var above = SKRectI.Intersect(new SKRectI(bar.Left, Math.Max(0, bar.Top - 60), bar.Right, bar.Top),
                new SKRectI(0, 0, bitmap.Width, bitmap.Height));
            var strokes = BlackCoverage(bitmap, above);
            if (strokes >= 0.02)
                return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
        }
        return Fail2(assertion, "no cat strokes in the band above the bar");
    }

    /// <summary>"From top-to-bottom, the boxes are labeled one through six": the paint log's
    /// number tokens appear below the instructions in ascending stated order.</summary>
    private static WptRunner.RunResult PaintedSequence(VisualCheck check, IReadOnlyList<Lite.Rendering.PaintLog.Entry>? paint, int top)
    {
        var needles = check.Needles ?? [];
        if (needles.Count == 0)
            return new(WptRunner.Cat.Unsupported, "Visual check: painted-sequence check names no sequence", 0, 0);
        var below = paint?.Where(e => e.BaselineY > top).ToList() ?? new List<Lite.Rendering.PaintLog.Entry>();
        // Tokens in visual order (bands top to bottom, fragments left to right).
        var tokens = new List<string>();
        foreach (var band in below.OrderBy(e => e.BaselineY).GroupBy(e => MathF.Round(e.BaselineY / 4f)))
            foreach (var entry in band.OrderBy(e => e.X))
                tokens.AddRange(NormalizeLine(entry.Text).Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
        var assertion = Describe(check);
        var positions = new List<int>();
        foreach (var needle in needles)
        {
            var found = -1;
            for (var i = (positions.Count > 0 ? positions[^1] + 1 : 0); i < tokens.Count; i++)
                if (string.Equals(tokens[i], needle, StringComparison.OrdinalIgnoreCase)) { found = i; break; }
            if (found < 0)
                return Fail2(assertion, $"the painted sequence does not contain '{needle}' in order (painted: {Truncate(string.Join(' ', tokens))})");
            positions.Add(found);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"The width of … the first line of 'Filler Text' is larger than the second
    /// line": the first ink band below the instructions is wider than the next one.</summary>
    private static WptRunner.RunResult FirstLineWider(VisualCheck check, SKBitmap bitmap, int top)
    {
        var bands = InkBands(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var assertion = Describe(check);
        if (bands.Count < 2)
            return Fail2(assertion, $"{bands.Count} text band(s) below the instructions (needs 2)");
        int Width((int Top, int Bottom, List<Component> Members) band) =>
            band.Members.Count == 0 ? 0 : band.Members.Max(m => m.Right) - band.Members.Min(m => m.Left);
        if (Width(bands[0]) <= Width(bands[1]))
            return Fail2(assertion, $"first line ({Width(bands[0])}px) is not wider than the second ({Width(bands[1])}px)");
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"The 'Filler Text' appears in the top left corner of the green box": the
    /// filler ink sits inside the stated box, its offsets from the box's top-left at most a
    /// quarter of the box's dimensions, and it does not touch the box's own edges (padding).</summary>
    private static WptRunner.RunResult TextInCorner(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top)
    {
        var filler = FindFiller(root, top);
        var components = Components(bitmap, top, out _);
        var boxColor = check.Color ?? "green";
        var boxes = TopLevel(components).Where(s => s.Width >= 40 && s.Height >= 40 && Matches(boxColor, s.Color)).ToList();
        var assertion = Describe(check);
        if (boxes.Count == 0)
            return Fail2(assertion, $"no {boxColor} box below the instructions");
        foreach (var box in boxes)
        {
            // The filler's ink bounding box.
            SKRectI ink;
            if (filler is { } f)
            {
                var b = f.Box.BorderBox;
                ink = SKRectI.Round(new SKRect(b.Left, b.Top, b.Right, b.Bottom));
            }
            else
            {
                var region = Components(bitmap, new SKRectI(box.Left, box.Top, box.Right, box.Bottom), out _)
                    .Where(c => !Matches(boxColor, c.Color) && c.Width < box.Width / 2 && c.Height < box.Height / 2).ToList();
                if (region.Count == 0) continue;
                ink = new SKRectI(region.Min(c => c.Left), region.Min(c => c.Top), region.Max(c => c.Right), region.Max(c => c.Bottom));
            }
            if (ink.Left < box.Left || ink.Top < box.Top || ink.Right > box.Right || ink.Bottom > box.Bottom)
                continue;
            if (ink.Left - box.Left > box.Width / 3 || ink.Top - box.Top > box.Height / 3)
                continue;
            return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
        }
        return Fail2(assertion, $"the filler text is not in the {boxColor} box's top-left corner");
    }

    /// <summary>"This text is within the green box": the instruction text's ink lies inside
    /// a box of the stated color.</summary>
    private static WptRunner.RunResult TextInBox(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top)
    {
        var components = Components(bitmap, top, out _);
        var boxColor = check.Color ?? "green";
        var boxes = TopLevel(components).Where(s => s.Width >= 40 && s.Height >= 20 && Matches(boxColor, s.Color)).ToList();
        var assertion = Describe(check);
        foreach (var box in boxes)
        {
            var textInk = Components(bitmap, new SKRectI(box.Left + 2, box.Top + 2, box.Right - 2, box.Bottom - 2), out _)
                .Where(c => !Matches(boxColor, c.Color)).ToList();
            if (textInk.Count > 0 && textInk.Max(c => (long)c.Width * c.Height) >= 8)
                return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
        }
        return Fail2(assertion, $"no text ink inside a {boxColor} box");
    }

    /// <summary>"There is a blue box on the left side of the words 'Filler Text'": a box of
    /// the stated color whose right edge is at or left of the filler's left edge, on the
    /// same line.</summary>
    private static WptRunner.RunResult BoxBesideText(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top)
    {
        var filler = FindFiller(root, top);
        if (filler is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no filler-text element below the instructions", 0, 0);
        var components = Components(bitmap, top, out _);
        var assertion = Describe(check);
        var b = filler.Box.BorderBox;
        var boxes = TopLevel(components).Where(s => Matches(check.Color ?? "blue", s.Color) &&
            s.Right <= b.Left + EdgeTolerance && s.Top < b.Bottom && s.Bottom > b.Top).ToList();
        return boxes.Count >= 1
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : Fail2(assertion, $"no {check.Color} box to the left of the filler text");
    }

    /// <summary>"The second line of text in the blue box is shifted to the left and is
    /// underneath the bullet": the box's second text band starts left of the first band.</summary>
    private static WptRunner.RunResult HangingIndent(VisualCheck check, SKBitmap bitmap, int top)
    {
        var bands = InkBands(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var assertion = Describe(check);
        if (bands.Count < 2)
            return Fail2(assertion, $"{bands.Count} text band(s) (needs 2)");
        int Left((int Top, int Bottom, List<Component> Members) band) =>
            band.Members.Count == 0 ? int.MaxValue : band.Members.Min(m => m.Left);
        if (Left(bands[1]) >= Left(bands[0]) - 4)
            return Fail2(assertion, $"the second line ({Left(bands[1])}) is not left of the first ({Left(bands[0])})");
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"The horizontal and vertical scrolling mechanism is not available on the
    /// page": the document fits the viewport and no page scrollbar painted at the right edge.</summary>
    private static WptRunner.RunResult NoScrollbar(VisualCheck check, SKBitmap bitmap)
    {
        var assertion = Describe(check);
        // The page scrollbar paints as a translucent dark rounded bar at the right edge.
        long dark = 0;
        for (int y = 0; y < bitmap.Height; y++)
        {
            var c = bitmap.GetPixel(bitmap.Width - 4, y);
            if (c.Red < 0xB0 && c.Green < 0xB0 && c.Blue < 0xB0 && ChannelSpread(c) < 24) dark++;
        }
        if (dark > bitmap.Height / 4)
            return Fail2(assertion, "a page scrollbar is visible at the right edge");
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"…should have active horizontal and vertical scrollbars": the box paints
    /// the harness's scrollbar bars (thin dark bars at its right and bottom edges).</summary>
    private static WptRunner.RunResult ScrollbarVisible(VisualCheck check, SKBitmap bitmap, LayoutNode root)
    {
        var assertion = Describe(check);
        var box = FindScrollBox(root);
        if (box is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no scrollable box rendered", 0, 0);
        var pb = box.Box.PaddingBox;
        int right = Math.Min((int)pb.Right - 4, bitmap.Width - 1);
        int bottom = Math.Min((int)pb.Bottom - 4, bitmap.Height - 1);
        long vBar = 0, hBar = 0;
        for (int y = (int)pb.Top; y < bottom; y++)
        {
            var c = bitmap.GetPixel(right, y);
            if (c.Red < 0xE0 && ChannelSpread(c) < 24) vBar++;
        }
        for (int x = (int)pb.Left; x < right; x++)
        {
            var c = bitmap.GetPixel(x, bottom);
            if (c.Red < 0xE0 && ChannelSpread(c) < 24) hBar++;
        }
        var height = bottom - (int)pb.Top;
        var width = right - (int)pb.Left;
        if (vBar < height / 4)
            return Fail2(assertion, $"no vertical scrollbar bar at the box's right edge ({vBar}/{height} dark rows)");
        if (hBar < width / 4)
            return Fail2(assertion, $"no horizontal scrollbar bar at the box's bottom edge ({hBar}/{width} dark columns)");
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"The blue and orange boxes below are the same width, and the blue box is in
    /// the upper-left corner of the black box": both clauses, read from the components.</summary>
    private static WptRunner.RunResult SameWidthCorner(VisualCheck check, SKBitmap bitmap, int top)
    {
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var assertion = Describe(check);
        var colorA = check.ColorA ?? "blue";
        var colorB = check.ColorB ?? "orange";
        var aShapes = shapes.Where(s => Matches(colorA, s.Color)).ToList();
        var bShapes = shapes.Where(s => Matches(colorB, s.Color)).ToList();
        if (aShapes.Count != 1 || bShapes.Count != 1)
            return Fail2(assertion, $"{aShapes.Count} {colorA} and {bShapes.Count} {colorB} box(es)");
        if (Math.Abs(aShapes[0].Width - bShapes[0].Width) > EdgeTolerance)
            return Fail2(assertion, $"widths differ: {colorA} {aShapes[0].Width}px vs {colorB} {bShapes[0].Width}px");
        // The corner clause: the {colorA} box sits inside the (larger) black container's
        // upper-left region.
        var container = shapes.Where(s => s.Width > aShapes[0].Width + 20 && s.Height > aShapes[0].Height + 20 &&
            s.Contains(aShapes[0])).ToList();
        if (container.Count == 0)
            return Fail2(assertion, $"no container box around the {colorA} box");
        var host = container[0];
        if (aShapes[0].Left - host.Left > host.Width / 3 || aShapes[0].Top - host.Top > host.Height / 3)
            return Fail2(assertion, $"the {colorA} box is not in the container's upper-left corner");
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"There are two boxes on the page and they are the same height. One box
    /// needs to be slanted to one side": two shapes with equal bounding-box heights, at
    /// least one non-rectangular (a slanted parallelogram's bounding box is not filled).</summary>
    private static string? SlantPair(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 2) return $"{shapes.Count} shapes below (needs exactly 2)";
        if (Math.Abs(shapes[0].Height - shapes[1].Height) > EdgeTolerance)
            return $"heights differ: {shapes[0].Height}px vs {shapes[1].Height}px";
        if (shapes.All(s => s.Rectangular)) return "neither box is slanted (both are exact rectangles)";
        return null;
    }

    /// <summary>"There should be a bright green line below the orange square": a square of
    /// the stated color with a line of the line color directly beneath it.</summary>
    private static string? LineBelow(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        var squares = shapes.Where(s => Matches(check.ColorA!, s.Color) && s.Width >= 8).ToList();
        var lines = shapes.Where(s => Matches(check.ColorB!, s.Color) && s.Width > s.Height * 3).ToList();
        if (squares.Count == 0) return $"no {check.ColorA} square below the instructions";
        if (lines.Count == 0) return $"no {check.ColorB} line below the instructions";
        foreach (var square in squares)
            foreach (var line in lines)
                if (line.Top >= square.Bottom - EdgeTolerance && line.Top <= square.Bottom + 6 &&
                    line.Left >= square.Left - EdgeTolerance && line.Right <= square.Right + EdgeTolerance)
                    return null;
        return "the line does not sit directly below the square";
    }

    /// <summary>"The middle column of the three-by-three table below is blue" (and the row
    /// variant): the stated color fills the middle cell(s)' interiors, the others do not.</summary>
    private static WptRunner.RunResult MiddleCellColor(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top)
    {
        var assertion = Describe(check);
        var table = FindTable(root, top);
        if (table is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no table below the instructions", 0, 0);
        var cells = TableCells(table);
        if (cells.Count < 9)
            return new(WptRunner.Cat.Unsupported, $"Visual check: the table has {cells.Count} cells, not nine", 0, 0);
        var targets = check.Dimension switch
        {
            "row" => new List<LayoutNode> { cells[3], cells[4], cells[5] },
            _ => new List<LayoutNode> { cells[1], cells[4], cells[7] },
        };
        if (!Named.TryGetValue(check.Color ?? "", out var want))
            return new(WptRunner.Cat.Unsupported, "Visual check: stated color is not a named color", 0, 0);
        foreach (var cell in targets)
        {
            var box = cell.Box.BorderBox;
            var crop = SKRectI.Round(new SKRect(box.Left + 3, box.Top + 3, box.Right - 3, box.Bottom - 3));
            if (crop.Width <= 4 || crop.Height <= 4)
                return new(WptRunner.Cat.Unsupported, "Visual check: the middle cell's interior is empty", 0, 0);
            var color = Dominant(bitmap, crop);
            if (ChannelDistance(color, want) > 48)
                return Fail2(assertion, $"the middle cell reads #{color.Red:X2}{color.Green:X2}{color.Blue:X2}, not {check.Color}");
        }
        // The stated color must not flood the other cells either (a whole-table fill would
        // satisfy the middle cells vacuously).
        foreach (var cell in cells.Where(c => !targets.Contains(c)))
        {
            var box = cell.Box.BorderBox;
            var crop = SKRectI.Round(new SKRect(box.Left + 3, box.Top + 3, box.Right - 3, box.Bottom - 3));
            if (crop.Width > 4 && crop.Height > 4)
            {
                var color = Dominant(bitmap, crop);
                if (ChannelDistance(color, want) <= 24)
                    return Fail2(assertion, $"a non-middle cell also reads {check.Color}");
            }
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>Dominant color of a crop (small helper over the same mode read the
    /// embedded-reference route uses).</summary>
    private static SKColor Dominant(SKBitmap bitmap, SKRectI crop)
    {
        var counts = new Dictionary<int, int>();
        for (int y = crop.Top; y < crop.Bottom; y++)
            for (int x = crop.Left; x < crop.Right; x++)
            {
                var c = bitmap.GetPixel(x, y);
                var key = (c.Red << 16) | (c.Green << 8) | c.Blue;
                counts[key] = counts.GetValueOrDefault(key) + 1;
            }
        var best = counts.OrderByDescending(kv => kv.Value).First();
        return new SKColor((byte)(best.Key >> 16), (byte)(best.Key >> 8), (byte)best.Key);
    }

    /// <summary>"There is a bullet (◦) below": one small ring — a single top-level component
    /// whose bounding box is about square, whose bounding box is small, and roundish.</summary>
    private static string? HollowCircle(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 1) return $"{shapes.Count} shape(s) below (needs exactly 1)";
        var s = shapes[0];
        if (s.Width > 24 || s.Height > 24) return $"the shape is {s.Width}x{s.Height}px — not a bullet";
        if (Math.Abs(s.Width - s.Height) > 3) return $"the shape is {s.Width}x{s.Height}px — not round";
        return null;
    }

    /// <summary>"There is a bullet (■) below": one small filled square (the square list
    /// marker paints as a rect, not a glyph).</summary>
    private static string? TinySquare(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 1) return $"{shapes.Count} shape(s) below (needs exactly 1)";
        var s = shapes[0];
        if (s.Width > 16 || s.Height > 16) return $"the shape is {s.Width}x{s.Height}px — not a small square bullet";
        if (Math.Abs(s.Width - s.Height) > 3) return $"the shape is {s.Width}x{s.Height}px — not square";
        if (!s.Rectangular) return "the shape is not rectangular";
        return null;
    }

    /// <summary>"From left-to-right, each square is a lighter blue than the previous one":
    /// components of the stated hue family ordered along the axis with strictly increasing
    /// lightness (at least three of them).</summary>
    private static string? GradientLighter(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        if (!Named.TryGetValue(check.Color ?? "blue", out var hue)) return "the stated color is not a named color";
        var family = shapes.Where(s => SameHue(s.Color, hue)).OrderBy(s => s.Left).ToList();
        if (family.Count < 3) return $"{family.Count} square(s) in the {check.Color} family (needs 3+)";
        for (var i = 1; i < family.Count; i++)
            if (Lightness(family[i].Color) <= Lightness(family[i - 1].Color))
                return $"square {i + 1} is not lighter than its predecessor";
        return null;
    }

    private static bool SameHue(SKColor a, SKColor b)
    {
        var (ha, _, sa) = Hsl(a);
        var (hb, _, sb) = Hsl(b);
        return Math.Abs(ha - hb) < 30 && sa > 0.1 && sb > 0.1;
    }

    private static (double H, double L, double S) Hsl(SKColor c)
    {
        double r = c.Red / 255.0, g = c.Green / 255.0, b = c.Blue / 255.0;
        double max = Math.Max(r, Math.Max(g, b)), min = Math.Min(r, Math.Min(g, b));
        double l = (max + min) / 2;
        double h = 0;
        if (max != min)
        {
            double d = max - min;
            double s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
            if (max == r) h = (g - b) / d + (g < b ? 6 : 0);
            else if (max == g) h = (b - r) / d + 2;
            else h = (r - g) / d + 4;
            h *= 60;
            return (h, l, s);
        }
        return (h, l, 0);
    }

    private static double Lightness(SKColor c) => Hsl(c).L;

    /// <summary>"The blue box below spans the height of the three orange squares": one box
    /// of the stated color covers the vertical band from the first to the last stacked
    /// square of the other stated color.</summary>
    private static string? SpansStack(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        var spans = shapes.Where(s => Matches(check.ColorA!, s.Color)).ToList();
        var squares = shapes.Where(s => Matches(check.ColorB!, s.Color)).OrderBy(s => s.Top).ToList();
        if (spans.Count != 1) return $"{spans.Count} {check.ColorA} box(es) (needs exactly 1)";
        if (squares.Count < 3) return $"{squares.Count} {check.ColorB} square(s) (needs 3)";
        var top = squares.First().Top;
        var bottom = squares.Last().Bottom;
        var span = spans[0];
        if (span.Top > top + EdgeTolerance) return $"the box's top ({span.Top}) starts below the first square's ({top})";
        if (span.Bottom < bottom - EdgeTolerance) return $"the box's bottom ({span.Bottom}) ends above the last square's ({bottom})";
        return null;
    }

    // ------------------------------------------------------------------
    // Static long-tail judges
    // ------------------------------------------------------------------

    /// <summary>"The box below has blue horizontal lines running through it (no vertical
    /// lines)": inside the ink's bounding box, several distinct row bands hold the stated
    /// color (horizontal) or column bands (vertical), separated by unstated rows.</summary>
    private static WptRunner.RunResult StripedFill(VisualCheck check, SKBitmap bitmap, int top)
    {
        if (!Named.TryGetValue(check.Color ?? "", out var target))
            return new(WptRunner.Cat.Unsupported, "Visual check: stripe color is not a named color", 0, 0);
        var horizontal = check.Dimension != "vertical";
        int minLine = horizontal ? bitmap.Height : bitmap.Width;
        int maxLine = 0;
        var lineInk = new Dictionary<int, int>();
        for (int y = top; y < bitmap.Height; y++)
            for (int x = 0; x < bitmap.Width; x++)
            {
                if (ChannelDistance(bitmap.GetPixel(x, y), target) > 48) continue;
                int line = horizontal ? y : x;
                lineInk[line] = lineInk.GetValueOrDefault(line) + 1;
                minLine = Math.Min(minLine, line);
                maxLine = Math.Max(maxLine, line);
            }
        if (maxLine <= minLine)
            return Fail2(Describe(check), $"no {check.Color} ink below the instructions");
        // Bands of consecutive inked lines with substantial coverage; the average inked line
        // coverage sets the bar (stripes alternate with gaps, so coverage < 50% overall).
        var bands = new List<(int Start, int End)>();
        int? start = null;
        for (int line = minLine; line <= maxLine + 1; line++)
        {
            bool inked = line <= maxLine && lineInk.GetValueOrDefault(line) >= 8;
            if (inked && start is null) start = line;
            if (!inked && start is { } s) { bands.Add((s, line - 1)); start = null; }
        }
        var assertion = Describe(check);
        if (bands.Count < 3)
            return Fail2(assertion, $"{bands.Count} {check.Color} band(s) inside the box (a striped fill needs 3+)");
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>"Two separate boxes below and the 'Filler Text' inside the boxes has the
    /// same alignment": each box's text ink sits at the same relative offsets (left-aligned
    /// text hugs both boxes' left edges; right-aligned the right edges).</summary>
    private static WptRunner.RunResult SameAlignment(VisualCheck check, SKBitmap bitmap, int top)
    {
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var boxes = TopLevel(components).Where(s => s.Width >= 40 && s.Height >= 14).ToList();
        if (boxes.Count < 2)
            return Fail2(Describe(check), $"{boxes.Count} box(es) below the instructions");
        var gaps = new List<(double Left, double Right)>();
        foreach (var box in boxes)
        {
            var textInk = Components(bitmap, new SKRectI(box.Left + 2, box.Top + 2, box.Right - 2, box.Bottom - 2), out _)
                .Where(c => c.Height <= box.Height / 2).ToList();
            if (textInk.Count == 0) return Fail2(Describe(check), "a box holds no text ink");
            int left = textInk.Min(c => c.Left), right = textInk.Max(c => c.Right);
            gaps.Add((left - box.Left, box.Right - right));
        }
        var (gl, gr) = gaps[0];
        var (gl2, gr2) = gaps[1];
        bool same = Math.Abs(gl - gl2) <= 3 && Math.Abs(gr - gr2) <= 3;
        return same
            ? new(WptRunner.Cat.Pass, Describe(check), 1, 0, [new(Describe(check), 0, null)], 0)
            : Fail2(Describe(check), $"text offsets differ: ({gl:F0},{gr:F0}) vs ({gl2:F0},{gr2:F0})");
    }

    /// <summary>"The background of this page is green": the dominant color of the whole
    /// render is the stated color.</summary>
    private static WptRunner.RunResult PageBackground(VisualCheck check, SKBitmap bitmap)
    {
        if (!Named.TryGetValue(check.Color ?? "green", out var target))
            return new(WptRunner.Cat.Unsupported, "Visual check: page background color is not a named color", 0, 0);
        long hits = 0;
        long total = 0;
        for (int y = 0; y < bitmap.Height; y += 2)
            for (int x = 0; x < bitmap.Width; x += 2)
            {
                total++;
                if (ChannelDistance(bitmap.GetPixel(x, y), target) <= 24) hits++;
            }
        var fraction = (double)hits / total;
        return fraction >= 0.85
            ? new(WptRunner.Cat.Pass, Describe(check), 1, 0, [new(Describe(check), 0, null)], 0)
            : Fail2(Describe(check), $"{Pct(fraction)} of the page is {check.Color} (needs 85%+)");
    }

    /// <summary>"There is anything displayed below" / "there is at least one box below":
    /// some ink exists below the instructions (a box optionally of the stated color).</summary>
    private static WptRunner.RunResult Presence(VisualCheck check, SKBitmap bitmap, int top)
    {
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var present = TopLevel(components).Where(s => (long)s.Width * s.Height >= 8).ToList();
        return present.Count >= 1
            ? new(WptRunner.Cat.Pass, Describe(check), 1, 0, [new(Describe(check), 0, null)], 0)
            : Fail2(Describe(check), "no ink below the instructions");
    }

    /// <summary>Distinct, clearly non-background colors with spread — a line-art tile or a
    /// photograph's ink. Called "cat ink" for the corpus's tile; the same detector reads any
    /// image content a scrolled background brings into view.</summary>
    private static double TwoToneCoverage(SKBitmap bitmap, SKRectI crop) => Coverage(bitmap, crop,
        static c => (c.Red >= 0xE0 && c.Green >= 0xE0 && c.Blue >= 0xE0) || (c.Red <= 0x30 && c.Green <= 0x30 && c.Blue <= 0x30));

    /// <summary>Colorful (saturated) non-background ink — the ink of a photographic image
    /// such as the cat photograph variants.</summary>
    private static double ColorfulCoverage(SKBitmap bitmap, SKRectI crop, SKColor background) => Coverage(bitmap, crop,
        c => ChannelSpread(c) >= 48 && ChannelDistance(c, background) >= 48 && !IsFailureRed(c));

    private static int ChannelSpread(SKColor c) =>
        Math.Max(c.Red, Math.Max(c.Green, c.Blue)) - Math.Min(c.Red, Math.Min(c.Green, c.Blue));

    private static int ChannelDistance(SKColor a, SKColor b) =>
        Math.Max(Math.Abs(a.Red - b.Red), Math.Max(Math.Abs(a.Green - b.Green), Math.Abs(a.Blue - b.Blue)));

    private static bool IsFailureRed(SKColor c) => c.Red == 255 && c.Green == 0 && c.Blue == 0;

    private static double Coverage(SKBitmap bitmap, SKRectI crop, Func<SKColor, bool> predicate)
    {
        long hits = 0;
        long total = 0;
        for (int y = crop.Top; y < crop.Bottom; y++)
            for (int x = crop.Left; x < crop.Right; x++)
            {
                total++;
                if (predicate(bitmap.GetPixel(x, y))) hits++;
            }
        return total == 0 ? 0 : (double)hits / total;
    }

    /// <summary>Fraction of pixels that differ beyond antialiasing slack between two crops.</summary>
    private static double DiffFraction(SKBitmap a, SKBitmap b, SKRectI crop)
    {
        long diff = 0;
        long total = 0;
        for (int y = crop.Top; y < crop.Bottom; y++)
            for (int x = crop.Left; x < crop.Right; x++)
            {
                total++;
                if (ChannelDistance(a.GetPixel(x, y), b.GetPixel(x, y)) > PixelTolerance) diff++;
            }
        return total == 0 ? 0 : (double)diff / total;
    }

    private static string Pct(double fraction) => $"{fraction:P1}";

    /// <summary>"…when the box is scrolled down, there is a line of cat images at the bottom
    /// of the box": the initial render's bottom band holds the box's own background only;
    /// the scrolled render brings the tiled image row into that band.</summary>
    private static WptRunner.RunResult CatsBottom(VisualCheck check, SKBitmap after, SKBitmap before, SKRectI crop)
    {
        var band = SKRectI.Intersect(new SKRectI(crop.Left, crop.Bottom - crop.Height / 4, crop.Right, crop.Bottom),
            new SKRectI(0, 0, after.Width, after.Height));
        var ink = TwoToneCoverage(after, band);
        if (ink < 0.25)
            return Fail($"after scrolling, the bottom band shows {Pct(ink)} image ink (needs 25%+)");
        var initial = TwoToneCoverage(before, band);
        if (initial > 0.05)
            return Fail($"the bottom band already showed {Pct(initial)} image ink before scrolling");
        return Pass();
    }

    /// <summary>"…the cat images move when the box is scrolled": image ink is visible both
    /// before and after, and the scrolled render differs from the initial one. The
    /// "not cut off" variants (<c>Variant</c> "center"/"left") additionally read the named
    /// bottom tile as complete: a cat drawing sits inside the bottom band and the tile
    /// window's outermost columns and rows hold no cut strokes.</summary>
    private static WptRunner.RunResult CatsMoved(VisualCheck check, SKBitmap after, SKBitmap before, SKRectI crop)
    {
        var initial = TwoToneCoverage(before, crop);
        var after_ink = TwoToneCoverage(after, crop);
        if (initial < 0.15)
            return Fail($"the box shows {Pct(initial)} image ink before scrolling (needs 15%+)");
        if (after_ink < 0.15)
            return Fail($"the box shows {Pct(after_ink)} image ink after scrolling (needs 15%+)");
        var diff = DiffFraction(before, after, crop);
        if (diff < 0.05)
            return Fail($"scrolling changed only {Pct(diff)} of the box's pixels (the images did not move)");
        if (check.Variant is "center" or "left")
        {
            var cx = check.Variant == "center" ? crop.Left + crop.Width / 2 : crop.Left + TileW / 2;
            if (CompleteCatTile(after, cx, crop.Bottom) is { } problem) return Fail(problem);
        }
        return Pass();
    }

    /// <summary>The cat tile's rendered size (the image's intrinsic 98x99 pixels).</summary>
    private const int TileW = 98;
    private const int TileH = 99;

    /// <summary>Reads a bottom tile window centered at <paramref name="cx"/> as a complete
    /// cat: black strokes inside, and the window's two outermost columns and rows free of
    /// strokes (a cut tile's strokes would reach its edges).</summary>
    private static string? CompleteCatTile(SKBitmap bitmap, int cx, int bottom)
    {
        int left = Math.Max(0, cx - TileW / 2);
        int top = Math.Max(0, bottom - TileH);
        int right = Math.Min(bitmap.Width, left + TileW);
        if (right - left < TileW - 2 || bottom - top < TileH - 2)
            return "the bottom tile window is clipped";
        var ink = BlackCoverage(bitmap, new SKRectI(left + 4, top + 4, right - 4, bottom - 4));
        if (ink < 0.02)
            return "the bottom tile window holds no cat drawing";
        foreach (var band in new[]
                 {
                     new SKRectI(left, top, left + 2, bottom),          // left columns
                     new SKRectI(right - 2, top, right, bottom),       // right columns
                     new SKRectI(left, bottom - 2, right, bottom),     // bottom rows
                 })
            if (BlackCoverage(bitmap, band) > 0.02)
                return "the cat drawing is cut at the tile boundary";
        return null;
    }

    private static double BlackCoverage(SKBitmap bitmap, SKRectI crop) => Coverage(bitmap, crop,
        static c => c.Red <= 0x30 && c.Green <= 0x30 && c.Blue <= 0x30);

    /// <summary>"…a picture of a cat repeated across the bottom of the box that moves with
    /// the scrollbar when the box is scrolled to the right": scrolling down brings the
    /// bottom tile row into view (the intermediate render), scrolling right then moves it.</summary>
    private static WptRunner.RunResult CatsBottomMoved(VisualCheck check, SKBitmap after, SKBitmap? mid, SKBitmap before, SKRectI crop)
    {
        if (mid is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: scroll protocol did not produce the intermediate render", 0, 0);
        var band = SKRectI.Intersect(new SKRectI(crop.Left, crop.Bottom - crop.Height / 4, crop.Right, crop.Bottom),
            new SKRectI(0, 0, after.Width, after.Height));
        var ink = TwoToneCoverage(mid, band);
        if (ink < 0.25)
            return Fail($"after scrolling down, the bottom band shows {Pct(ink)} image ink (needs 25%+)");
        var move = DiffFraction(mid, after, band);
        if (move < 0.05)
            return Fail($"scrolling right changed only {Pct(move)} of the bottom band (the row did not move)");
        return Pass();
    }

    /// <summary>"…cat images across the top. Also, the cat images move when the box is
    /// scrolled": the initial render's top band holds the tile row, and scrolling moves it.</summary>
    private static WptRunner.RunResult CatsTopMoved(VisualCheck check, SKBitmap after, SKBitmap before, SKRectI crop)
    {
        var band = SKRectI.Intersect(new SKRectI(crop.Left, crop.Top, crop.Right, crop.Top + crop.Height / 4),
            new SKRectI(0, 0, before.Width, before.Height));
        var ink = TwoToneCoverage(before, band);
        if (ink < 0.25)
            return Fail($"the top band shows {Pct(ink)} image ink (needs 25%+)");
        var diff = DiffFraction(before, after, crop);
        if (diff < 0.05)
            return Fail($"scrolling changed only {Pct(diff)} of the box's pixels (the images did not move)");
        return Pass();
    }

    /// <summary>"…scrolling on the box does not cause the cat image to move": image ink is
    /// visible, and the scrolled render matches the initial one.</summary>
    private static WptRunner.RunResult CatsStill(VisualCheck check, SKBitmap after, SKBitmap before, SKRectI crop)
    {
        var ink = TwoToneCoverage(before, crop);
        if (ink < 0.15)
            return Fail($"the box shows {Pct(ink)} image ink (needs 15%+)");
        var diff = DiffFraction(before, after, crop);
        if (diff > 0.01)
            return Fail($"scrolling changed {Pct(diff)} of the box's pixels (the image moved)");
        return Pass();
    }

    private static WptRunner.RunResult Pass(string? detail = null) =>
        new(WptRunner.Cat.Pass, detail ?? "stated scroll condition holds", 1, 0, [new("Stated scroll condition holds", 0, null)], 0);
    private static WptRunner.RunResult Fail(string detail) =>
        new(WptRunner.Cat.Fail, $"Stated scroll condition fails: {detail}", 1, 1, [new("Stated scroll condition holds", 1, detail)], 0);

    private static WptRunner.RunResult ComponentCheck(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var components = Components(bitmap, top, out var clipped);
        if (clipped)
            return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        return Judge(check, TopLevel(components), bitmap, top, components);
    }

    internal static WptRunner.RunResult Judge(VisualCheck check, IReadOnlyList<Component> shapes,
        SKBitmap? bitmap = null, int top = 0, IReadOnlyList<Component>? nested = null)
    {
        var assertion = $"Stated pass condition holds ({Describe(check)})";
        string? failure;
        try
        {
            failure = check.Kind switch
            {
                "one-shape" => OneShape(check, shapes),
                "same-dimension" => SameDimension(check, shapes),
                "bar-gap" => BarGap(shapes),
                "line-style" => LineStyle(check, shapes),
                "look-same" => bitmap is null ? "no render" : LookSame(shapes, bitmap, check.Approx ? 3 * PixelTolerance : PixelTolerance),
                "solid-line" => SolidLine(check, shapes),
                "border-ring" => BorderRing(check, shapes, bitmap),
                "shape-relation" => ShapeRelation(check, shapes, nested, bitmap),
                "space-between" => bitmap is null ? "no render" : SpaceBetween(check, shapes, bitmap),
                "stack-three" => StackThree(check, shapes),
                "two-size" => TwoSize(shapes),
                "line-pair" => LinePair(check, shapes),
                "marker-bullet" => MarkerBullet(check, shapes),
                "round-dot" => RoundDot(shapes),
                "double-line" => DoubleLine(shapes),
                "slanted-box" => SlantedBox(shapes),
                "line-marker" => FromResult(bitmap is null ? null : LineMarker(check, bitmap, top, "")),
                "bullet-beside" => FromResult(bitmap is null ? null : BulletBeside(check, bitmap, top, "")),
                "bar-stack" => FromResult(bitmap is null ? null : BarStack(check, bitmap, top, "")),
                "bars-match" => FromResult(bitmap is null ? null : BarsMatch(check, bitmap, top, "")),
                "bar-grid" => FromResult(bitmap is null ? null : BarGrid(check, bitmap, top, "")),
                "viewport-bottom" => FromResult(bitmap is null ? null : ViewportBottom(check, bitmap)),
                "corners" => FromResult(bitmap is null ? null : Corners(check, bitmap, top, "")),
                "box-count" => FromResult(bitmap is null ? null : BoxCount(check, bitmap, top, "")),
                "three-bars" => FromResult(bitmap is null ? null : ThreeBars(check, bitmap, top, "")),
                "lines-same" => FromResult(bitmap is null ? null : LinesSame(check, bitmap, top, "")),
                "first-line-color" => FromResult(bitmap is null ? null : FirstLineColor(check, bitmap, top, "")),
                "justify" => FromResult(bitmap is null ? null : Justify(bitmap, top, "")),
                "stack-order" => FromResult(bitmap is null ? null : StackOrder(check, bitmap, top, "")),
                "border-sides" => FromResult(bitmap is null ? null : BorderSides(check, bitmap, top, "")),
                "lines-spaced" => FromResult(bitmap is null ? null : LinesSpaced(check, bitmap, top, "")),
                "gradient-lighter" => GradientLighter(check, shapes),
                "spans-stack" => SpansStack(check, shapes),
                "slant-pair" => SlantPair(check, shapes),
                "line-below" => LineBelow(check, shapes),
                "hollow-circle" => HollowCircle(shapes),
                "tiny-square" => TinySquare(shapes),
                _ => throw new InvalidDataException($"Unknown visual check kind: {check.Kind}"),
            };
        }
        catch (InvalidDataException) { throw; }
        catch (Exception ex)
        {
            return new(WptRunner.Cat.Unsupported, $"Visual check: {ex.Message}", 0, 0);
        }
        return failure is null
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: {failure}", 1, 1, [new(assertion, 1, failure)], 0);
    }

    /// <summary>Adapter for the render-only judges inside <see cref="Judge"/>'s failure
    /// switch: a null result means "no render", a passing result is a null failure.</summary>
    private static string? FromResult(WptRunner.RunResult? result) =>
        result is not { } run ? "no render" : run.Passed ? null : run.Detail;

    private static string Describe(VisualCheck check) => check.Kind switch
    {
        "one-shape" => $"one {(check.Color is null ? "" : check.Color + " ")}{check.Shape ?? "box"}",
        "same-dimension" => $"{(check.Count is { } n ? n.ToString() : "all")} shapes share {check.Dimension}",
        "line-style" => $"one {check.Dimension ?? ""} {(check.Color is null ? "" : check.Color + " ")}{check.Shape} line".Replace("  ", " "),
        "look-same" => "the two shapes render identically",
        "solid-line" => $"one {(check.Color is null ? "" : check.Color + " ")}solid line",
        "border-ring" => $"one box with a {(check.Color is null ? "" : check.Color + " ")}{check.Shape} border",
        "border-sample" => "the center box's border matches the stated style and the sample",
        "text-color" => $"the filler text is {check.Color}",
        "text-decoration" => check.Under is false ? "the filler text has no line under it" : "the filler text has the stated lines",
        "align-right" => "the filler text is flush with the container's right edge",
        "shape-relation" => $"the stated-color shapes: {check.Relation}",
        "space-between" => $"the space between the boxes is {check.Color}",
        "stack-three" => "three same-width rectangles are stacked",
        "two-size" => "one box is much larger than the other",
        "line-pair" => $"a {check.FirstShape} line and a {check.SecondShape} line ({check.Arrangement})",
        "marker-bullet" => "a marker bullet sits to the left of the box",
        "round-dot" => "one small round dot",
        "double-line" => "one double line",
        "slanted-box" => "one slanted box",
        "letter-x" => check.Variant == "box-above" ? "a box above the letter x" : "the letter x is rendered",
        "outline-text" => $"a {check.Shape} outline around the named text",
        "text-baseline" => $"the filler texts' {check.Edge ?? "bottom"}s align",
        "one-line" => "all the filler text sits on one line",
        "first-line-marker" => $"a {(check.Color is null ? "" : check.Color + " ")}square bullet on the first line",
        "line-marker" => $"a marker bullet to the left of the {(check.Color is null ? "" : check.Color + " ")}line".Replace("  ", " "),
        "bullet-beside" => $"a bullet to the {check.Side} of the square",
        "bar-stack" => $"a {check.ColorA} bar stacked on a {check.ColorB} bar",
        "text-marker" => $"the number {check.Needle} with a marker bullet on its left",
        "numbers-present" => $"the numbers {string.Join(", ", check.Needles ?? [])} are rendered",
        "text-ink" => $"the text {check.Needle} is rendered",
        "words-and-box" => $"the words {check.Needle} render as glyphs and a {check.Color} box sits below",
        "align-center" => "the text is centered horizontally",
        "lines-spaced" => $"space between the {check.ColorA} and {check.ColorB} lines",
        "lines-same" => $"the {(check.Count == 3 ? "three" : "two")} lines render identically",
        "image-tiled" => "the tiled image repeats as stated",
        "bars-match" => "each coloured bar matches a same-coloured box",
        "bar-grid" => $"a bar on top of a {check.Rows}-by-{check.Cols} grid",
        "viewport-bottom" => $"the {check.Color} box is at the bottom of the viewport",
        "cell-border" => $"the middle {check.Target}'s {(check.Edge == "top" ? "top edge is" : "border is")} {check.Color}",
        "corners" => $"a {check.Color} square at each corner of the stated box",
        "box-count" => $"{(check.Count is { } bc ? bc.ToString() : "the stated number of")} boxes below",
        "three-bars" => $"{check.ColorA} bars with a {check.ColorB} one between",
        "first-letter-color" => $"the first letter is {check.Color} and the rest is not",
        "first-line-color" => $"the first line is {check.Color} and the others are not",
        "justify" => "the justified lines share both edges",
        "text-band" => $"{(check.Needle is null ? "the paragraph" : $"each \"{check.Needle}\"")} has the stated {check.Color} line(s) {check.Side}",
        "edge-letter" => $"the {check.Side} ink is {check.Color}",
        "stack-order" => $"the boxes stack bottom-to-top {string.Join(", ", check.Colors ?? [])}",
        "no-ring" => "no border paints around the text",
        "text-below-box" => $"the filler text paints {check.Side} the box",
        "text-marker-match" => "the filler-text lines match and the bottom one has a marker",
        "border-sides" => check.Mode == "distinct" ? "each edge reads different" : "the borders read as stated per side",
        _ => check.Kind,
    };

    private static string? OneShape(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 1) return $"{shapes.Count} top-level shapes below the instructions";
        var shape = shapes[0];
        if (!shape.Rectangular) return $"the shape at ({shape.Left},{shape.Top}) {shape.Width}x{shape.Height} is not rectangular";
        if (check.Shape == "square" && Math.Abs(shape.Width - shape.Height) > EdgeTolerance)
            return $"not a square: {shape.Width}x{shape.Height}";
        if (check.Color is { } name && !Matches(name, shape.Color) &&
            !(check.Shades && HueDistance(shape.Color, Named[name]) <= 30))
            return $"dominant color {shape.Color}, not {name}";
        // "a green or yellow box below": either stated colour satisfies (the suite states
        // the fallback pair where two declarations exercise the same recovery path).
        if (check.Colors is { Count: > 0 } allowed && check.Color is null &&
            !allowed.Any(name2 => Matches(name2, shape.Color)))
            return $"dominant color {shape.Color}, none of [{string.Join(", ", allowed)}]";
        if (check.Variant == "tiny" && (shape.Width > 12 || shape.Height > 12))
            return $"the shape is {shape.Width}x{shape.Height}px — not tiny";
        return null;
    }

    /// <summary>A stated color names the CSS keyword, except that the suite's prose calls
    /// both <c>green</c> (#008000) and <c>lime</c> (#00ff00) "green" (the character-encoding
    /// support sheets paint #00FF00 under "there is a green rectangle"). Unknown names never
    /// match — the dispatcher has already routed them to unsupported.</summary>
    private static bool Matches(string name, SKColor color) =>
        Named.TryGetValue(name, out var want) && (want == color || name == "green" && Named["lime"] == color);

    private static string? SameDimension(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        var pool = shapes;
        if (check.ColorA is { } || check.ColorB is { })
            pool = pool.Where(s => (check.ColorA is { } ca && Matches(ca, s.Color)) ||
                                    (check.ColorB is { } cb && Matches(cb, s.Color))).ToList();
        if (check.Count is { } count ? pool.Count != count : pool.Count < 2)
            return $"{pool.Count} top-level shapes below the instructions";
        if (pool.FirstOrDefault(s => !s.Rectangular) is { Width: > 0 } odd)
            return $"the shape at ({odd.Left},{odd.Top}) {odd.Width}x{odd.Height} is not rectangular";
        var width = check.Dimension is "width" or "size";
        var height = check.Dimension is "height" or "size";
        if (width && pool.Max(s => s.Width) - pool.Min(s => s.Width) > EdgeTolerance)
            return "widths " + string.Join(", ", pool.Select(s => s.Width));
        if (height && pool.Max(s => s.Height) - pool.Min(s => s.Height) > EdgeTolerance)
            return "heights " + string.Join(", ", pool.Select(s => s.Height));
        return null;
    }

    private static string? LineStyle(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        if (shapes.Count < 3) return $"{shapes.Count} segments below the instructions (a {check.Shape} line has at least 3)";
        int top = shapes.Min(s => s.Top), bottom = shapes.Max(s => s.Bottom);
        int left = shapes.Min(s => s.Left), right = shapes.Max(s => s.Right);
        // One row of segments sharing the line's thickness, or one column of them.
        var horizontal = shapes.All(s => Math.Abs(s.Top - top) <= EdgeTolerance && Math.Abs(s.Bottom - bottom) <= EdgeTolerance);
        var vertical = shapes.All(s => Math.Abs(s.Left - left) <= EdgeTolerance && Math.Abs(s.Right - right) <= EdgeTolerance);
        if (check.Dimension == "vertical" ? !vertical : check.Dimension == "horizontal" ? !horizontal : !(horizontal || vertical))
            return $"the {shapes.Count} shapes do not form one {check.Dimension ?? "straight"} line";
        var along = horizontal && check.Dimension != "vertical";
        // The pattern is clipped where the line ends, so the first and last segments may be
        // shorter than a full dash; only the interior ones show the pattern's shape.
        var ordered = shapes.OrderBy(s => along ? s.Left : s.Top).ToList();
        for (var k = 0; k < ordered.Count; k++)
        {
            var s = ordered[k];
            var interior = k > 0 && k < ordered.Count - 1;
            if (check.Color is { } want && !Matches(want, s.Color)) return $"segment color {s.Color}, not {want}";
            if (!interior) continue;
            var length = along ? s.Width : s.Height;
            var thickness = along ? s.Height : s.Width;
            if (check.Shape == "dashed" && length < 1.5 * thickness)
                return $"segment at ({s.Left},{s.Top}) {s.Width}x{s.Height} is a dot, not a dash";
            if (check.Shape == "dotted" && length > 1.5 * thickness + EdgeTolerance)
                return $"segment at ({s.Left},{s.Top}) {s.Width}x{s.Height} is a dash, not a dot";
        }
        return null;
    }

    private static string? BarGap(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 3) return $"{shapes.Count} top-level shapes below the instructions";
        var bars = shapes.OrderBy(s => s.Left + s.Right).ToArray();
        var gap = bars[2].Left - bars[0].Right;
        return Math.Abs(bars[1].Width - gap) > EdgeTolerance ? $"middle bar {bars[1].Width}px, gap {gap}px" : null;
    }

    /// <summary>Two top-level shapes, same dimensions, pixel-identical within tolerance
    /// (antialiasing by default; "approximately the same" admits three times that).</summary>
    private static string? LookSame(IReadOnlyList<Component> shapes, SKBitmap bitmap, int tolerance)
    {
        if (shapes.Count == 2) return LookSamePair([shapes[0]], [shapes[1]], bitmap, tolerance);
        // "The following two lines should look the same" over TEXT lines: the ink fragments
        // into glyph-level components (the counters family renders 60+), so the two lines are
        // re-grouped by vertical clustering — a vertical gap between consecutive components'
        // extents splits the bands (within a line every glyph shares the baseline, so the
        // extents overlap) — and the two bands' ink strips compare pixel-wise.
        var ordered = shapes.OrderBy(s => s.Top).ThenBy(s => s.Left).ToList();
        var bands = new List<List<Component>>();
        foreach (var s in ordered)
        {
            if (bands.Count == 0) { bands.Add([s]); continue; }
            var band = bands[^1];
            if (s.Top - band.Max(x => x.Bottom) > 3) bands.Add([s]);
            else band.Add(s);
        }
        if (bands.Count == 1 && ordered.Count > 1)
        {
            // Tight leading: the two lines' extents overlap, so no positive gap splits them.
            // Split at the LARGEST vertical gap between consecutive components — within a
            // line the glyphs share the baseline (no gap at all), so the inter-line gap wins
            // however small it is.
            var bestSplit = -1;
            var bestGap = 0f;
            for (var k = 1; k < ordered.Count; k++)
            {
                var gap = ordered[k].Top - ordered[k - 1].Bottom;
                if (gap > bestGap) { bestGap = gap; bestSplit = k; }
            }
            if (bestSplit > 0)
            {
                bands = [ordered.Take(bestSplit).ToList(), ordered.Skip(bestSplit).ToList()];
            }
        }
        if (bands.Count != 2)
            return $"{bands.Count} ink lines below the instructions (the stated condition compares 2)";
        return LookSamePair(bands[0], bands[1], bitmap, tolerance);
    }

    private static string? LookSamePair(IReadOnlyList<Component> a, IReadOnlyList<Component> b, SKBitmap bitmap, int tolerance)
    {
        SKRect BoxOf(IReadOnlyList<Component> band) => new(
            band.Min(s => s.Left), band.Min(s => s.Top), band.Max(s => s.Right), band.Max(s => s.Bottom));
        var (ba, bb) = (BoxOf(a), BoxOf(b));
        if (Math.Abs(ba.Width - bb.Width) > EdgeTolerance || Math.Abs(ba.Height - bb.Height) > EdgeTolerance)
            return $"different dimensions: {ba.Width}x{ba.Height} vs {bb.Width}x{bb.Height}";
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        for (var y = 0; y < Math.Min(ba.Height, bb.Height); y++)
        for (var x = 0; x < Math.Min(ba.Width, bb.Width); x++)
        {
            var pa = pixels[((int)ba.Top + y) * width + (int)ba.Left + x];
            var pb = pixels[((int)bb.Top + y) * width + (int)bb.Left + x];
            if (Distance(pa, pb) > tolerance)
                return $"pixels differ at (+{x},+{y}): {pa} vs {pb}";
        }
        return null;
    }

    /// <summary>One line-shaped component; a stated color must match through antialiasing
    /// shades ("or shades of &lt;color&gt;" — hue-preserving for chromatic names, any gray of
    /// the right lightness for achromatic ones).</summary>
    private static string? SolidLine(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 1) return $"{shapes.Count} top-level shapes below the instructions";
        var line = shapes[0];
        var thin = Math.Min(line.Width, line.Height);
        var along = Math.Max(line.Width, line.Height);
        if (thin > 30 || along < 8 * thin) return $"the shape {line.Width}x{line.Height} is not a line";
        if (check.Color is { } name)
        {
            var want = Named[name];
            if (Achromatic.Contains(name))
            {
                var spread = Math.Max(Math.Max(line.Color.Red, line.Color.Green), line.Color.Blue) -
                             Math.Min(Math.Min(line.Color.Red, line.Color.Green), line.Color.Blue);
                if (spread > 24) return $"line color {line.Color} is not a shade of {name}";
                var value = Math.Max(Math.Max(line.Color.Red, line.Color.Green), line.Color.Blue);
                var wantValue = Math.Max(Math.Max(want.Red, want.Green), want.Blue);
                if (Math.Abs(value - wantValue) > ShadeTolerance) return $"line color {line.Color} is not a shade of {name}";
            }
            else if (!Matches(name, line.Color) && HueDistance(line.Color, want) > 30)
                return $"line color {line.Color} is not a shade of {name}";
        }
        return null;
    }

    /// <summary>Hue distance in degrees, ignoring the achromatic axis where hue is
    /// undefined (a fully desaturated color has no hue to mismatch).</summary>
    private static double HueDistance(SKColor a, SKColor b)
    {
        var (ha, sa) = HueSaturation(a);
        var (hb, sb) = HueSaturation(b);
        if (sa < 0.08 || sb < 0.08) return 0;
        var d = Math.Abs(ha - hb);
        return Math.Min(d, 360 - d);
    }

    private static (double Hue, double Sat) HueSaturation(SKColor c)
    {
        var max = Math.Max(c.Red, Math.Max(c.Green, c.Blue)) / 255.0;
        var min = Math.Min(c.Red, Math.Min(c.Green, c.Blue)) / 255.0;
        if (max - min == 0) return (0, 0);
        double hue;
        if (max == c.Red / 255.0) hue = ((c.Green - c.Blue) / 255.0 / (max - min)) % 6;
        else if (max == c.Green / 255.0) hue = (c.Blue - c.Red) / 255.0 / (max - min) + 2;
        else hue = (c.Red - c.Green) / 255.0 / (max - min) + 4;
        hue *= 60;
        if (hue < 0) hue += 360;
        return (hue, (max - min) / max);
    }

    /// <summary>Every top-level shape lies on the perimeter of one rectangle; all four sides
    /// covered; interior segments shaped per the stated style. A stated <c>Count</c> of two
    /// splits the segments into two vertically stacked rings and checks each.</summary>
    private static string? BorderRing(VisualCheck check, IReadOnlyList<Component> shapes, SKBitmap? bitmap = null)
    {
        if (check.Count == 2)
        {
            var ordered = shapes.OrderBy(s => s.Top).ToList();
            var split = 0;
            var widest = -1;
            for (var k = 0; k < ordered.Count - 1; k++)
            {
                var gap = ordered[k + 1].Top - ordered[k].Bottom;
                if (gap > widest) { widest = gap; split = k + 1; }
            }
            if (widest < 4 || split == 0 || split == ordered.Count)
                return "the two boxes' segments do not split into two rings";
            var first = RingFailures(check, ordered.Take(split).ToList(), bitmap);
            if (first is not null) return $"first box: {first}";
            var second = RingFailures(check, ordered.Skip(split).ToList(), bitmap);
            return second is null ? null : $"second box: {second}";
        }
        return RingFailures(check, shapes.ToList(), bitmap);
    }

    private static string? RingFailures(VisualCheck check, List<Component> shapes, SKBitmap? bitmap = null)
    {
        if (shapes.Count < 4)
        {
            // A SOLID uniform-color ring connects at its corners into ONE ink component —
            // the segmentation is correct, not the render: demanding 4+ segments rejected
            // every honestly-painted solid ring (border-width-applies-to-001..014's "a box
            // with four sides that are the same width"). Dashed/dotted rings DO fragment,
            // so they keep the segment rule. With the bitmap, the connected ring is read
            // by scanline: the components' union extent is the ring's own outer extent
            // (the same "ring's own extent" principle as the sample judge), and each
            // side's thickness is the ink run inward from that edge at the midpoint —
            // midpoints avoid the corner joins.
            if (bitmap is null || check.Shape is "dashed" or "dotted")
                return $"only {shapes.Count} segments below the instructions (a boxed border has at least 4)";
            return ConnectedRingFailures(check, shapes, bitmap);
        }
        int top = shapes.Min(s => s.Top), bottom = shapes.Max(s => s.Bottom);
        int left = shapes.Min(s => s.Left), right = shapes.Max(s => s.Right);
        foreach (var s in shapes)
        {
            var onVerticalSide = Math.Abs(s.Left - left) <= 2 * EdgeTolerance || Math.Abs(s.Right - right) <= 2 * EdgeTolerance;
            var onHorizontalSide = Math.Abs(s.Top - top) <= 2 * EdgeTolerance || Math.Abs(s.Bottom - bottom) <= 2 * EdgeTolerance;
            if (!onVerticalSide && !onHorizontalSide)
                return $"the shape at ({s.Left},{s.Top}) {s.Width}x{s.Height} is not on the box perimeter";
        }
        foreach (var (side, selector) in new[] {
            ("top", new Func<Component, bool>(s => Math.Abs(s.Top - top) <= 2 * EdgeTolerance)),
            ("bottom", (Func<Component, bool>)(s => Math.Abs(s.Bottom - bottom) <= 2 * EdgeTolerance)),
            ("left", (Func<Component, bool>)(s => Math.Abs(s.Left - left) <= 2 * EdgeTolerance)),
            ("right", (Func<Component, bool>)(s => Math.Abs(s.Right - right) <= 2 * EdgeTolerance)),
        })
        {
            var segments = shapes.Where(selector).ToList();
            if (segments.Count == 0) return $"the {side} side of the box has no border";
            if (check.Shape is "dashed" or "dotted" && segments.Count < 3)
                return $"the {side} side is one unbroken segment, not {check.Shape}";
            var failure = SideStyle(check, segments, alongHorizontal: side is "top" or "bottom");
            if (failure is not null) return $"{side} side: {failure}";
        }
        return null;
    }

    /// <summary>The connected-ring read: a solid uniform ring paints as one (or few) ink
    /// components whose union is the ring's outer extent. Each side's thickness is the ink
    /// run inward from that edge scanned at the extent's midpoint (corners join, midpoints
    /// do not), against the crop's own background. The sentence "four sides that are the
    /// same width" reads as four PRESENT sides of equal thickness; the stated color must
    /// dominate every component as the segmented path requires.</summary>
    private static string? ConnectedRingFailures(VisualCheck check, List<Component> shapes, SKBitmap bitmap)
    {
        int left = shapes.Min(s => s.Left), right = shapes.Max(s => s.Right);
        int top = shapes.Min(s => s.Top), bottom = shapes.Max(s => s.Bottom);
        if (right - left < 8 || bottom - top < 8) return "the ring is too small to scan";
        var crop = new SKRectI(left, top, right + 1, bottom + 1);
        crop.Intersect(new SKRectI(1, 1, bitmap.Width - 2, bitmap.Height - 2));
        // The ink/background reference is the ring's HOLE, not a crop majority: a thick
        // ring's own ink dominates its bounding box, so a majority read inverts (the ring
        // reads as background, its interior as ink — every side then scans as zero). The
        // extent's center sits in the hole for any ring; for a wrongly filled box it sits
        // on ink and every side honestly reads zero.
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        var midX = Math.Min((left + right) / 2, bitmap.Width - 1);
        var midY = Math.Min((top + bottom) / 2, bitmap.Height - 1);
        var hole = pixels[midY * width + midX];
        bool Inked(int x, int y) => Distance(pixels[y * width + x], hole) > InkThreshold;
        int RunIn(int from, int to, int at, bool vertical)
        {
            var step = to >= from ? 1 : -1;
            var count = 0;
            for (var p = from; step > 0 ? p <= to : p >= to; p += step)
            {
                if (!vertical && !Inked(p, at)) break;
                if (vertical && !Inked(at, p)) break;
                count++;
            }
            return count;
        }
        var thicknesses = new (string Side, int Thickness)[]
        {
            ("top", RunIn(Math.Max(top, 1), bottom, midX, vertical: true)),
            // Right/Bottom are EXCLUSIVE bounds (the ink's last row/column is one inside),
            // so the bottom/right scans start there; the segmented path's bboxes match.
            ("bottom", RunIn(Math.Min(bottom - 1, bitmap.Height - 2), top, midX, vertical: true)),
            ("left", RunIn(Math.Max(left, 1), right, midY, vertical: false)),
            ("right", RunIn(Math.Min(right - 1, bitmap.Width - 2), left, midY, vertical: false)),
        };
        foreach (var (side, thickness) in thicknesses)
            if (thickness == 0) return $"the {side} side of the box has no border";
        foreach (var shape in shapes)
            if (check.Color is { } want && !Matches(want, shape.Color))
                return $"segment color {shape.Color}, not {want}";
        var max = thicknesses.Max(t => t.Thickness);
        var min = thicknesses.Min(t => t.Thickness);
        if (max - min > EdgeTolerance)
            return "side widths " + string.Join(", ", thicknesses.Select(t => $"{t.Side}={t.Thickness}"));
        return null;
    }

    /// <summary>The dash/dot shape rules of <see cref="LineStyle"/> applied to one ring
    /// side; the end segments may be clipped by the corners.</summary>
    private static string? SideStyle(VisualCheck check, List<Component> segments, bool alongHorizontal)
    {
        if (check.Color is { } want)
            foreach (var s in segments)
                if (!Matches(want, s.Color)) return $"segment color {s.Color}, not {want}";
        if (check.Shape is not ("dashed" or "dotted")) return null;
        var ordered = alongHorizontal ? segments.OrderBy(s => s.Left).ToList() : segments.OrderBy(s => s.Top).ToList();
        for (var k = 0; k < ordered.Count; k++)
        {
            if (k == 0 || k == ordered.Count - 1) continue;
            var s = ordered[k];
            var length = alongHorizontal ? s.Width : s.Height;
            var thickness = alongHorizontal ? s.Height : s.Width;
            if (check.Shape == "dashed" && length < 1.5 * thickness)
                return $"segment at ({s.Left},{s.Top}) {s.Width}x{s.Height} is a dot, not a dash";
            if (check.Shape == "dotted" && length > 1.5 * thickness + EdgeTolerance)
                return $"segment at ({s.Left},{s.Top}) {s.Width}x{s.Height} is a dash, not a dot";
        }
        return null;
    }

    /// <summary>The stated-color shapes satisfy the relation. Each stated color must match
    /// exactly one top-level shape unless the relation says otherwise.</summary>
    /// <summary>"The teal blocks must be just inside the top and sides of the blue
    /// rectangle": N blocks inside one container, the topmost touching the container's top
    /// band, and the side extremes hugging the container's sides.</summary>
    private static string? InsetTopSides(VisualCheck check, List<Component> blocks, List<Component> containers)
    {
        if (containers.Count != 1) return $"{containers.Count} {check.ColorB} rectangles (needs exactly 1)";
        var host = containers[0];
        if (blocks.Count == 0) return $"no {check.ColorA} blocks below the instructions";
        foreach (var block in blocks)
        {
            if (block.Left < host.Left - EdgeTolerance || block.Right > host.Right + EdgeTolerance)
                return $"a {check.ColorA} block crosses the container's sides ({block.Left}..{block.Right} in {host.Left}..{host.Right})";
            if (block.Top < host.Top - EdgeTolerance || block.Bottom > host.Bottom + EdgeTolerance)
                return $"a {check.ColorA} block crosses the container's top/bottom ({block.Top}..{block.Bottom} in {host.Top}..{host.Bottom})";
        }
        var topmost = blocks.Min(s => s.Top);
        if (topmost > host.Top + 8)
            return $"the topmost {check.ColorA} block starts {topmost - host.Top}px below the container's top";
        return null;
    }

    private static string? ShapeRelation(VisualCheck check, IReadOnlyList<Component> shapes,
        IReadOnlyList<Component>? nested = null, SKBitmap? bitmap = null)
    {
        // Containment relations (centered-right, corners) read shapes nested inside another
        // shape, which the top-level list alone does not carry.
        var pool = nested is { Count: > 0 } ? shapes.Concat(nested).Distinct().ToList() : shapes.ToList();
        var a = OfColor(pool, check.ColorA);
        var b = OfColor(pool, check.ColorB);
        if (check.Relation == "inset-top-sides")
        {
            // Read directly: N blocks inside one container (the general single-shape gate below
            // does not apply).
            return InsetTopSides(check, a, b);
        }
        if (check.Relation == "gaps-equal")
        {
            if (a.Count != 2 || b.Count != 2)
                return $"{a.Count} {check.ColorA} and {b.Count} {check.ColorB} shapes below the instructions";
            var orderedA = a.OrderBy(s => check.Dimension == "horizontal" ? s.Left : s.Top).ToList();
            var orderedB = b.OrderBy(s => check.Dimension == "horizontal" ? s.Left : s.Top).ToList();
            var gapA = check.Dimension == "horizontal"
                ? orderedA[1].Left - orderedA[0].Right
                : orderedA[1].Top - orderedA[0].Bottom;
            var gapB = check.Dimension == "horizontal"
                ? orderedB[1].Left - orderedB[0].Right
                : orderedB[1].Top - orderedB[0].Bottom;
            return Math.Abs(gapA - gapB) > 2 * EdgeTolerance ? $"gaps differ: {gapA}px vs {gapB}px" : null;
        }
        // "The height of the <color> box is similar to the height of the <color> boxes"
        // compares one box against several; every other relation names exactly one of each.
        var singleFirst = check.Relation != "height-similar";
        if (a.Count != 1 || singleFirst && b.Count != 1 || b.Count == 0)
            return $"{a.Count} {check.ColorA} and {b.Count} {check.ColorB} shapes below the instructions";
        var (first, second) = (a[0], b[0]);
        switch (check.Relation)
        {
            case "larger":
                if ((long)first.Width * first.Height <= (long)second.Width * second.Height)
                    return $"{check.ColorA} {first.Width}x{first.Height} is not larger than {check.ColorB} {second.Width}x{second.Height}";
                return null;
            case "smaller":
                if ((long)first.Width * first.Height >= (long)second.Width * second.Height)
                    return $"{check.ColorA} {first.Width}x{first.Height} is not smaller than {check.ColorB} {second.Width}x{second.Height}";
                return null;
            case "right-of":
                if (first.Left < second.Right - 2 * EdgeTolerance)
                    return $"the {check.ColorA} box is not to the right of the {check.ColorB} box";
                if (Math.Min(first.Bottom, second.Bottom) - Math.Max(first.Top, second.Top) <= 0)
                    return "the boxes do not line up vertically";
                return null;
            case "not-touching":
                if (first.Intersects(second)) return "the boxes overlap";
                if (Math.Max(first.Top - second.Bottom, second.Top - first.Bottom) <= 0 &&
                    Math.Max(first.Left - second.Right, second.Left - first.Right) <= 0)
                    return "the boxes touch";
                return null;
            case "touching":
                if (Touching(first, second)) return null;
                return "the boxes have space between them";
            case "vertical-gap":
                return Math.Max(first.Top - second.Bottom, second.Top - first.Bottom) >= 1
                    ? null
                    : "the squares have no vertical gap";
            case "horizontal-gap":
                return Math.Max(first.Left - second.Right, second.Left - first.Right) >= 1
                    ? null
                    : "the squares have no horizontal gap";
            case "no-horizontal-gap":
                return Math.Abs(first.Left - second.Right) <= EdgeTolerance || Math.Abs(second.Left - first.Right) <= EdgeTolerance
                    ? null
                    : "the squares have a horizontal gap";
            case "half-height":
            {
                var outer = OfColor(pool, check.ColorC);
                if (outer.Count != 1)
                    return $"{outer.Count} {check.ColorC} shapes below the instructions";
                var want = outer[0].Height / 2.0;
                if (Math.Abs(first.Height - want) > 2 || Math.Abs(second.Height - want) > 2)
                    return $"heights {first.Height} and {second.Height} are not half of {outer[0].Height}";
                return null;
            }
            case "corner-lower-right":
            case "corner-upper-left":
            case "corner-upper-right":
            case "corner-lower-left":
            {
                if (bitmap is null) return "no render";
                if (!second.Contains(first) && !first.Contains(second))
                    return $"the {check.ColorA} box is not inside the {check.ColorB} box";
                var (wantRight, wantLeft, wantTop, wantBottom) = InnerEdges(second, bitmap, check.Relation);
                var off = new List<string>();
                if (check.Relation.Contains("right") && Math.Abs(first.Right - wantRight) > 2) off.Add($"right off by {first.Right - wantRight}");
                if (check.Relation.Contains("left") && Math.Abs(first.Left - wantLeft) > 2) off.Add($"left off by {wantLeft - first.Left}");
                if (check.Relation.Contains("bottom") && Math.Abs(first.Bottom - wantBottom) > 2) off.Add($"bottom off by {first.Bottom - wantBottom}");
                if (check.Relation.Contains("top") && Math.Abs(first.Top - wantTop) > 2) off.Add($"top off by {wantTop - first.Top}");
                return off.Count == 0 ? null : $"not in the stated corner: {string.Join(", ", off)}";
            }
            case "beneath":
                if (Math.Abs(first.Top - second.Bottom) > 2 * EdgeTolerance ||
                    Math.Min(first.Right, second.Right) - Math.Max(first.Left, second.Left) <
                    Math.Min(first.Width, second.Width) / 2.0)
                    return $"{check.ColorA} box at ({first.Left},{first.Top}) is not directly beneath the {check.ColorB} box at ({second.Left},{second.Top})";
                break;
            case "centered-right":
                if (!second.Contains(first))
                    return $"the {check.ColorA} square is not inside the {check.ColorB} box";
                if (Math.Abs((first.Top - second.Top) - (second.Bottom - first.Bottom)) > 2)
                    return $"not vertically centered: margins {first.Top - second.Top} and {second.Bottom - first.Bottom}";
                // "On the right inner edge" is the padding-box edge: through the outer
                // component's own band (a border ring's thickness) at the square's
                // mid-height, or flush against a filled box's edge.
                if (bitmap is null) return "no render";
                {
                    var pixels = bitmap.Pixels;
                    var width = bitmap.Width;
                    var midY = (first.Top + first.Bottom) / 2;
                    var band = 0;
                    for (var x = second.Right - 1; x >= second.Left; x--)
                    {
                        if (Distance(pixels[midY * width + x], second.Color) > 32) break;
                        band++;
                    }
                    var innerEdge = second.Right - band;
                    if (Math.Abs(first.Right - innerEdge) > 2)
                        return $"not on the right inner edge: {innerEdge - first.Right}px in (band {band}px)";
                }
                return null;
            case "height-similar":
            {
                var heights = a.Concat(b).Select(s => s.Height).Distinct().ToList();
                if (heights.Max() - heights.Min() > 2)
                    return $"heights differ: " + string.Join(", ", a.Concat(b).Select(s => s.Height).OrderBy(h => h).Distinct());
                return null;
            }
            case "height-band":
            {
                // The sentence's "it is acceptable to have the blue box height be shorter or
                // taller" clause relaxes the comparison to a band (the reviewed reading:
                // similar means within a factor of two of the reference boxes either way).
                var blue = a[0].Height;
                var reference = b[0].Height;
                if (blue < reference / 2f - EdgeTolerance || blue > reference * 2f + EdgeTolerance)
                    return $"the {check.ColorA} box's height ({blue}px) is outside the similar band around {check.ColorB} ({reference}px)";
                return null;
            }
            case "no-vertical-gap":
                var touching = Math.Abs(first.Bottom - second.Top) <= EdgeTolerance || Math.Abs(second.Bottom - first.Top) <= EdgeTolerance;
                if (!touching) return $"vertical gap between the squares: {Math.Max(first.Top - second.Bottom, second.Top - first.Bottom)}px";
                break;
            default:
                return $"unknown relation {check.Relation}";
        }
        if (check.LineColor is { } lineName)
        {
            var lines = shapes.Where(s => Matches(lineName, s.Color) && (s.Width > 3 * s.Height || s.Height > 3 * s.Width)).ToList();
            if (lines.Count == 0) return $"no {lineName} line below the instructions";
            foreach (var line in lines)
                if (line.Intersects(first) || line.Intersects(second))
                    return $"a box touches the {lineName} line";
        }
        return null;
    }

    private static List<Component> OfColor(IReadOnlyList<Component> shapes, string? name) =>
        name is null ? [] : shapes.Where(s => Matches(name, s.Color)).ToList();

    private static bool Touching(Component a, Component b) =>
        a.Intersects(b) || Math.Abs(a.Bottom - b.Top) <= EdgeTolerance || Math.Abs(b.Bottom - a.Top) <= EdgeTolerance ||
        Math.Abs(a.Right - b.Left) <= EdgeTolerance || Math.Abs(b.Right - a.Left) <= EdgeTolerance;

    /// <summary>The inner edges of a box, measured through its own border band. The band is
    /// scanned away from the stated corner (where the inner box would otherwise end the scan
    /// itself); a band covering half the extent means the box is filled, not hollow, and its
    /// own edge is then the inner edge.</summary>
    private static (int Right, int Left, int Top, int Bottom) InnerEdges(Component box, SKBitmap bitmap, string relation)
    {
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        int Band(int startX, int startY, int dx, int dy)
        {
            var band = 0;
            var x = startX;
            var y = startY;
            while (x >= 0 && x < width && y >= 0 && y < bitmap.Height &&
                   Distance(pixels[y * width + x], box.Color) <= 32)
            {
                band++;
                x += dx;
                y += dy;
            }
            return band;
        }
        var quarterH = Math.Max(1, box.Height / 4);
        var quarterW = Math.Max(1, box.Width / 4);
        // The stated corner's square sits at one end of each relevant edge; probe from the other.
        var yTop = relation.Contains("bottom") ? box.Top + quarterH : box.Bottom - quarterH - 1;
        var yBottom = yTop;
        var xLeft = relation.Contains("right") ? box.Left + quarterW : box.Right - quarterW - 1;
        var xRight = xLeft;
        var rightBand = Band(box.Right - 1, yTop, -1, 0);
        var leftBand = Band(box.Left, yTop, 1, 0);
        var bottomBand = Band(xLeft, box.Bottom - 1, 0, -1);
        var topBand = Band(xLeft, box.Top, 0, 1);
        var innerRight = rightBand >= box.Width / 2 ? box.Right : box.Right - rightBand;
        var innerLeft = leftBand >= box.Width / 2 ? box.Left : box.Left + leftBand;
        var innerBottom = bottomBand >= box.Height / 2 ? box.Bottom : box.Bottom - bottomBand;
        var innerTop = topBand >= box.Height / 2 ? box.Top : box.Top + topBand;
        return (innerRight, innerLeft, innerTop, innerBottom);
    }

    /// <summary>The region between consecutive boxes (by vertical order, over their
    /// horizontal overlap) is painted in the stated color.</summary>
    private static string? SpaceBetween(VisualCheck check, IReadOnlyList<Component> shapes, SKBitmap bitmap)
    {
        if (shapes.Count < 2) return $"{shapes.Count} top-level shapes below the instructions";
        if (shapes.Any(s => !s.Rectangular)) return "a shape below the instructions is not rectangular";
        var ordered = shapes.OrderBy(s => s.Top).ToList();
        var want = Named[check.Color!];
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        for (var k = 0; k < ordered.Count - 1; k++)
        {
            var (above, below) = (ordered[k], ordered[k + 1]);
            var gapTop = above.Bottom;
            var gapBottom = below.Top;
            if (gapBottom <= gapTop) continue;
            var overlapLeft = Math.Max(above.Left, below.Left);
            var overlapRight = Math.Min(above.Right, below.Right);
            if (overlapRight <= overlapLeft) return $"boxes {k} and {k + 1} do not overlap horizontally";
            long checkedPixels = 0, matching = 0;
            for (var y = gapTop; y < gapBottom; y++)
            for (var x = overlapLeft; x < overlapRight; x++)
            {
                checkedPixels++;
                if (Distance(pixels[y * width + x], want) <= 24) matching++;
            }
            if (checkedPixels == 0 || matching < checkedPixels * 9 / 10)
                return $"the space between boxes {k} and {k + 1} is not {check.Color}";
        }
        return null;
    }

    private static string? StackThree(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 3) return $"{shapes.Count} top-level shapes below the instructions";
        if (shapes.Any(s => !s.Rectangular)) return "a shape below the instructions is not rectangular";
        var ordered = shapes.OrderBy(s => s.Top).ToList();
        for (var k = 0; k < 2; k++)
            if (ordered[k + 1].Top < ordered[k].Bottom - EdgeTolerance)
                return $"rectangle {k + 1} overlaps rectangle {k}";
        if (ordered.Max(s => s.Width) - ordered.Min(s => s.Width) > EdgeTolerance)
            return "rectangle widths differ: " + string.Join(", ", ordered.Select(s => s.Width));
        if (check.Even)
        {
            var gap0 = ordered[1].Top - ordered[0].Bottom;
            var gap1 = ordered[2].Top - ordered[1].Bottom;
            if (Math.Abs(gap0 - gap1) > 2 * EdgeTolerance) return $"the gaps differ: {gap0}px and {gap1}px";
        }
        return null;
    }

    private static string? TwoSize(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 2) return $"{shapes.Count} top-level shapes below the instructions";
        var areaA = (long)shapes[0].Width * shapes[0].Height;
        var areaB = (long)shapes[1].Width * shapes[1].Height;
        var (big, small) = areaA >= areaB ? (areaA, areaB) : (areaB, areaA);
        return small * 3 / 2 > big ? $"both boxes are about the same size ({areaA} vs {areaB} px)" : null;
    }

    /// <summary>A line pair with stated styles, colors and arrangement: each stated color
    /// forms one line (all its segments aligned in one row or column); the solid line is a
    /// single component, a dashed/dotted line is a row of dash/dot shaped segments; the
    /// second line sits to the right of / below the first per the arrangement.</summary>
    private static string? LinePair(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        var first = LineCluster(shapes.Where(s => check.FirstColor is null || Matches(check.FirstColor, s.Color)).ToList(),
            check.FirstShape, check.FirstColor is null && check.SecondColor is null);
        if (first.Failure is not null) return $"first line: {first.Failure}";
        var second = LineCluster(shapes.Where(s => check.SecondColor is null || Matches(check.SecondColor, s.Color)).ToList(),
            check.SecondShape, false);
        if (second.Failure is not null) return $"second line: {second.Failure}";
        if (check.Arrangement == "right-of" && !(second.Box.Left >= first.Box.Right - EdgeTolerance))
            return $"the second line is not to the right of the first ({first.Box.Right} vs {second.Box.Left})";
        if (check.Arrangement == "below" && !(second.Box.Top >= first.Box.Bottom - EdgeTolerance))
            return $"the second line is not below the first ({first.Box.Bottom} vs {second.Box.Top})";
        return null;
    }

    private sealed record Cluster(SKRectI Box, string? Failure);

    /// <summary>All components of one color must form exactly one straight line of the
    /// stated shape.</summary>
    private static Cluster LineCluster(List<Component> items, string? shape, bool splitRows)
    {
        if (items.Count == 0) return new(default, "no components in the stated color");
        if (!splitRows)
        {
            int top = items.Min(s => s.Top), bottom = items.Max(s => s.Bottom);
            int left = items.Min(s => s.Left), right = items.Max(s => s.Right);
            var horizontal = items.All(s => Math.Abs(s.Top - top) <= EdgeTolerance && Math.Abs(s.Bottom - bottom) <= EdgeTolerance);
            var vertical = items.All(s => Math.Abs(s.Left - left) <= EdgeTolerance && Math.Abs(s.Right - right) <= EdgeTolerance);
            if (!horizontal && !vertical) return new(new SKRectI(left, top, right, bottom), "the segments do not form one straight line");
            var failure = SideStyle(new VisualCheck("border-ring", shape), items, alongHorizontal: horizontal);
            return failure is null
                ? new(new SKRectI(left, top, right, bottom), null)
                : new(new SKRectI(left, top, right, bottom), failure);
        }
        // Two lines of one color: cluster into aligned rows (or columns) and require two,
        // each shaped per the stated style.
        foreach (var horizontal in new[] { true, false })
        {
            var key = horizontal ? (Func<Component, int>)(s => s.Top) : s => s.Left;
            var ordered = items.OrderBy(key).ToList();
            var groups = new List<List<Component>> { new() { ordered[0] } };
            foreach (var s in ordered.Skip(1))
            {
                var g = groups[^1];
                if (Math.Abs(key(s) - key(g[^1])) <= 2 * EdgeTolerance) g.Add(s);
                else groups.Add([s]);
            }
            if (groups.Count != 2) continue;
            var failures = groups.Select(g => SideStyle(new VisualCheck("border-ring", shape), g,
                alongHorizontal: horizontal)).ToList();
            if (failures.All(f => f is null)) return new(default, null);
            return new(default, failures.FirstOrDefault(f => f is not null));
        }
        return new(default, "the segments do not form two straight lines");
    }

    /// <summary>A small marker bullet sits to the left of the (stated-color) box, vertically
    /// overlapping it.</summary>
    private static string? MarkerBullet(VisualCheck check, IReadOnlyList<Component> shapes)
    {
        var boxes = shapes.Where(s => s.Rectangular && Math.Min(s.Width, s.Height) >= 14 &&
            (check.Color is null || Matches(check.Color, s.Color))).ToList();
        if (boxes.Count != 1) return $"{boxes.Count} candidate boxes below the instructions";
        var box = boxes[0];
        var bullets = shapes.Where(s => !ReferenceEquals(s, box) &&
            Math.Max(s.Width, s.Height) <= 24 && s.Right <= box.Left + EdgeTolerance &&
            s.Top < box.Bottom && s.Bottom > box.Top).ToList();
        if (check.BulletColor is { } bulletColor && bullets.Any(b => !Matches(bulletColor, b.Color)))
            return $"the bullet is not {bulletColor}";
        return bullets.Count == 1
            ? null
            : $"{bullets.Count} marker bullets to the left of the box";
    }

    /// <summary>One small round dot: a single component as wide as it is tall whose corners
    /// are empty (only the circle's inscribed area is inked).</summary>
    private static string? RoundDot(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 1) return $"{shapes.Count} top-level shapes below the instructions";
        var dot = shapes[0];
        if (Math.Abs(dot.Width - dot.Height) > 2 * EdgeTolerance)
            return $"the shape is {dot.Width}x{dot.Height}, not round";
        if (dot.Width > 30) return $"the shape is {dot.Width}px across, not a dot";
        if (dot.Rectangular) return "the shape is a filled square, not a round dot";
        return null;
    }

    /// <summary>A double line: two thin parallel segments of the same length with a gap
    /// between them.</summary>
    private static string? DoubleLine(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 2) return $"{shapes.Count} top-level shapes below the instructions";
        var (a, b) = (shapes[0], shapes[1]);
        if (Math.Abs(a.Width - b.Width) > 2 * EdgeTolerance || Math.Abs(a.Height - b.Height) > 2 * EdgeTolerance)
            return $"the two lines differ in length: {a.Width}x{a.Height} vs {b.Width}x{b.Height}";
        var stacked = a.Bottom <= b.Top || b.Bottom <= a.Top;
        var sideBySide = a.Right <= b.Left || b.Right <= a.Left;
        if (!stacked && !sideBySide) return "the two lines overlap";
        if (Math.Min(a.Width, a.Height) > 12 || Math.Min(b.Width, b.Height) > 12)
            return $"the lines are too thick to be a double line ({a.Width}x{a.Height}, {b.Width}x{b.Height})";
        return null;
    }

    /// <summary>One large non-rectangular shape: a box that has been slanted.</summary>
    private static string? SlantedBox(IReadOnlyList<Component> shapes)
    {
        if (shapes.Count != 1) return $"{shapes.Count} top-level shapes below the instructions";
        var shape = shapes[0];
        if (shape.Rectangular) return "the shape is a straight rectangle, not slanted";
        if ((long)shape.Width * shape.Height < 1500) return $"the shape is only {shape.Width}x{shape.Height}";
        return null;
    }

    /// <summary>The <c>#center</c> element's painted border ring must be similar to the
    /// <c>#table1</c> sample ring — the suite's own reference render of the winning style:
    /// same readable style word when the rings read as one of solid/dashed/dotted/double/
    /// none, otherwise the same structure (tone count, sub-lines, runs), and always the
    /// same thickness and color. The center cell's own text names its declared style, which
    /// may lose the conflict, so the text is not the oracle — the sample is.</summary>
    private static WptRunner.RunResult BorderSample(VisualCheck check, SKBitmap bitmap, LayoutNode root, string path)
    {
        var center = FindById(root, "center");
        if (center is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no #center element in the layout tree", 0, 0);
        var assertion = Describe(check);

        var centerBorder = Math.Max(center.Box.Border.MaxEdge(), 1f);
        var centerBox = center.Box.BorderBox;
        var centerCrop = SKRectI.Round(new SKRect(
            centerBox.Left - centerBorder - 2, centerBox.Top - centerBorder - 2,
            centerBox.Right + centerBorder + 2, centerBox.Bottom + centerBorder + 2));
        var centerRing = RingSignature(bitmap, centerCrop, center.Box.PaddingBox, centerBorder);
        if (!centerRing.Readable)
            return new(WptRunner.Cat.Unsupported, $"Visual check: {centerRing.Note}", 0, 0);

        // The "has no border" variant states the whole condition: the center cell's own
        // band must carry no ink at all.
        if (check.Variant == "none")
            return centerRing.Style == "none"
                ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
                : new(WptRunner.Cat.Fail, $"{assertion}: the center box's border paints ({centerRing.Style}, {centerRing.Color})", 1, 1,
                    [new(assertion, 1, "the center cell's border band has ink")], 0);

        var sample = FindById(root, "table1");
        if (sample is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no #table1 sample to compare against", 0, 0);
        var sampleCell = FirstLeafCell(sample);
        if (sampleCell is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: the sample table has no readable cell", 0, 0);

        var sampleBorder = Math.Max(sampleCell.Box.Border.MaxEdge(), 1f);
        var sampleBox = sampleCell.Box.BorderBox;
        var sampleCrop = SKRectI.Round(new SKRect(
            sampleBox.Left - sampleBorder - 2, sampleBox.Top - sampleBorder - 2,
            sampleBox.Right + sampleBorder + 2, sampleBox.Bottom + sampleBorder + 2));
        var sampleRing = RingSignature(bitmap, sampleCrop, sampleCell.Box.PaddingBox, sampleBorder);
        if (!sampleRing.Readable)
            return new(WptRunner.Cat.Unsupported, $"Visual check: the sample ring is not readable: {sampleRing.Note}", 0, 0);

        if (centerRing.Style != sampleRing.Style)
            return new(WptRunner.Cat.Fail, $"{assertion}: the center ring reads {Show(centerRing)}, the sample reads {Show(sampleRing)}", 1, 1,
                [new(assertion, 1, $"center {Show(centerRing)} vs sample {Show(sampleRing)}")], 0);
        if (Math.Abs(sampleRing.Thickness - centerRing.Thickness) > 1.5)
            return new(WptRunner.Cat.Fail, $"{assertion}: ring thickness {centerRing.Thickness}px vs sample {sampleRing.Thickness}px", 1, 1,
                [new(assertion, 1, "center and sample rings differ in thickness")], 0);
        if (centerRing.Count > 0 && sampleRing.Count > 0 && centerRing.ToneColors.Count > 0 &&
            sampleRing.ToneColors.Count > 0 && !TonesMatch(centerRing.ToneColors, sampleRing.ToneColors))
            return new(WptRunner.Cat.Fail, $"{assertion}: ring colors {ShowTones(centerRing.ToneColors)} vs sample {ShowTones(sampleRing.ToneColors)}", 1, 1,
                [new(assertion, 1, "center and sample rings differ in color")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);

        static string Show(Ring r) => r.Style is null ? "an unclassified shaded band" : r.Style;
        static string ShowTones(System.Collections.Generic.List<SKColor> tones) =>
            string.Join("/", tones.Select(t => $"#{t.Red:X2}{t.Green:X2}{t.Blue:X2}"));

        // Every dominant tone of one ring sits within 48 of a dominant tone of the other —
        // shaded borders carry a light and a dark tone whose dominant can flip between
        // renders, so sets match more honestly than single dominants.
        static bool TonesMatch(System.Collections.Generic.List<SKColor> a, System.Collections.Generic.List<SKColor> b) =>
            a.All(ta => b.Any(tb => Distance(ta, tb) <= 48)) && b.All(tb => a.Any(ta => Distance(ta, tb) <= 48));
    }

    /// <summary>How one border ring reads from the render. <see cref="Style"/> is the
    /// readable style word (solid/double/dashed/dotted, or none for no ink) and is null when
    /// the band is structured but not classifiable (the shaded styles); the structure fields
    /// still describe it. <see cref="Readable"/> is false only when the render cannot decide
    /// at all (content clipped at the crop edge, an unscannable band).</summary>
    private sealed record Ring(string? Style, float Thickness, SKColor Color, List<SKColor> ToneColors, int Groups, int Runs,
        int Count, bool Readable = true, string? Note = null);

    /// <summary>Reads the border ring around one box by scanline: the ring ink is whatever
    /// paints between the padding box and one declared border width outside the border box
    /// (with collapsed borders, the shared edge paints half inside and half outside the
    /// border box). Each side's band rows, run structure along the band midline and
    /// sub-lines across it decide solid / double / dashed / dotted / none.</summary>
    private static Ring RingSignature(SKBitmap bitmap, SKRectI crop, SKRect paddingBox, float declaredBorder)
    {
        // Full-width boxes' rings legitimately touch the viewport edges (an outline spans
        // the whole page width); reading stops 2px short so edge ink does not read as a
        // clipped ring. A genuinely half-off-viewport ring still fails structurally.
        crop.Intersect(new SKRectI(1, 1, bitmap.Width - 2, bitmap.Height - 2));
        if (crop.Width < 4 || crop.Height < 4) return new(null, 0, default, [], 0, 0, 0, false, "the border region is outside the viewport");
        var components = Components(bitmap, crop, out var clipped);
        if (clipped) return new(null, 0, default, [], 0, 0, 0, false, "content reaches the viewport edge inside the border region");
        var padding = SKRectI.Round(paddingBox);
        var outer = SKRectI.Round(new SKRect(
            padding.Left - declaredBorder - 1, padding.Top - declaredBorder - 1,
            padding.Right + declaredBorder + 1, padding.Bottom + declaredBorder + 1));
        var ring = components.Where(c => !(c.Left >= padding.Left && c.Right <= padding.Right &&
                                          c.Top >= padding.Top && c.Bottom <= padding.Bottom) &&
                                         c.Right > outer.Left && c.Left < outer.Right &&
                                         c.Bottom > outer.Top && c.Top < outer.Bottom).ToList();
        if (ring.Count == 0) return new("none", 0, default, [], 0, 0, 0);
        // The ring's own extent: the components clamped to the band. A raw component bbox
        // lies here when the ring's ink connects to surrounding structure — a collapsed
        // table's same-color borders all touch, so the #center ring's component spans the
        // whole grid — and that oversized bbox both misread the truncation test below and
        // skewed the side scan spans away from the ring's own bands.
        int left = ring.Min(c => Math.Max(c.Left, outer.Left)), right = ring.Max(c => Math.Min(c.Right, outer.Right));
        int top = ring.Min(c => Math.Max(c.Top, outer.Top)), bottom = ring.Max(c => Math.Min(c.Bottom, outer.Bottom));
        if (right - left < 8 || bottom - top < 8) return new(null, 0, default, [], 0, 0, ring.Count, false, "the ring is too small to scan");
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        // The page background around the ring — computed over the whole crop, because the
        // ring components' own bounding boxes are mostly ring ink.
        var background = CropBackground(bitmap, crop);
        bool Inked(int x, int y) => Distance(pixels[y * width + x], background) > InkThreshold;
        var scanDepth = Math.Min((int)declaredBorder * 2 + 6, Math.Min(bottom - top, right - left) / 2);

        string? style = null;
        float thickness = 0;
        var color = ring[0].Color;
        int groups = 0, runs = 0;
        var sideReads = new List<(string Name, string? Style, float Thickness, bool Truncated)>();
        foreach (var (name, horizontal, span) in new (string, bool, (int From, int To, int Band, int Depth))[]
        {
            ("top", true, (left, right, top, scanDepth)),
            ("bottom", true, (left, right, bottom - scanDepth, scanDepth)),
            ("left", false, (top, bottom, left, scanDepth)),
            ("right", false, (top, bottom, right - scanDepth, scanDepth)),
        })
        {
            var read = ReadSideScan(bitmap, background, horizontal, span);
            if (read.Unreadable) return new(null, 0, default, [], 0, 0, ring.Count, false, $"the {name} side's border band is not scannable");
            // A band that reaches the crop boundary is cut off by the viewport (full-width
            // boxes' outlines do) — its style word is unreliable and is excluded. The bounding
            // box compared against the crop is the RING's own extent — the components clamped
            // to the ring band below — not a raw component bbox: a collapsed table's same-color
            // borders all touch, so the center ring's components form one connected component
            // spanning the whole grid whose bbox exceeds the crop even though the ring's ink
            // sits well inside it (border-conflict-style-001), which excluded every side from
            // the style vote and read the ring "unclassified". Rings genuinely cut by the
            // viewport are reported by the `clipped` check above.
            var truncated = name switch
            {
                "top" => top <= crop.Top + 1,
                "bottom" => bottom >= crop.Bottom - 1,
                "left" => left <= crop.Left + 1,
                _ => right >= crop.Right - 1,
            };
            sideReads.Add((name, read.Style, read.Thickness, truncated));
        }
        if (Environment.GetEnvironmentVariable("LITE_RING_DEBUG") is not null)
            File.AppendAllText(Path.Combine(Lite.Conformance.Harness.ConformancePaths.EnsureArtifacts(),
                $"ring-debug-{Path.GetFileNameWithoutExtension(Environment.GetEnvironmentVariable("LITE_RING_DEBUG")!)}.txt"),
                "sides: " + string.Join(", ", sideReads.Select(r => $"{r.Name}={r.Style ?? "null"}/{r.Thickness:F0}{(r.Truncated ? " TRUNC" : "")}")) + "\n");
        foreach (var read in sideReads)
        {
            if (read.Truncated) continue;
            thickness = Math.Max(thickness, read.Thickness);
            if (style is null) style = read.Style;
            else if (style != read.Style)
                return new(null, 0, default, [], 0, 0, ring.Count, false, "the sides read different border styles");
        }
        // Distinct ink tones with a meaningful share: solid and double bands are one color,
        // the shaded styles paint a light and a dark tone.
        var toneCounts = new Dictionary<uint, long>();
        foreach (var c in ring)
            for (var y = Math.Max(c.Top, outer.Top); y < Math.Min(c.Bottom, outer.Bottom); y++)
            for (var x = Math.Max(c.Left, outer.Left); x < Math.Min(c.Right, outer.Right); x++)
            {
                var p = pixels[y * width + x];
                if (Distance(p, background) > InkThreshold)
                    toneCounts[(uint)p] = toneCounts.GetValueOrDefault((uint)p) + 1;
            }
        var total = toneCounts.Values.Sum();
        var toneColors = toneCounts.Where(kv => kv.Value >= total / 5)
            .OrderByDescending(kv => kv.Value).Select(kv => new SKColor((uint)kv.Key)).ToList();
        return new(style, thickness, color, toneColors, groups, runs, ring.Count);
    }

    /// <summary>How one side's border band reads by scanline: band rows (sub-lines), runs
    /// along the outer sub-line's midline, and the style those two structures spell.</summary>
    private static (string? Style, float Thickness, int Groups, int Runs, bool Unreadable) ReadSideScan(
        SKBitmap bitmap, SKColor background, bool horizontal, (int From, int To, int Band, int Depth) span)
    {
        var (from, to, bandStart, depth) = span;
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        if (depth < 2) return (null, 0, 0, 0, true);
        // Ink at offset d from the band's start, at along-coordinate p.
        bool InkedAt(int p, int d)
        {
            var (x, y) = horizontal ? (p, bandStart + d) : (bandStart + d, p);
            return x >= 0 && x < width && y >= 0 && y < bitmap.Height &&
                   Distance(pixels[y * width + x], background) > InkThreshold;
        }
        // Band rows: rows inked across at least 40% of the side's extent — a dotted band
        // hovers at 50%, while stray text below the box stays well under it.
        var bandRows = new List<int>();
        for (var d = 0; d < depth; d++)
        {
            long inked = 0;
            for (var p = from; p < to; p++)
                if (InkedAt(p, d)) inked++;
            if (inked >= (to - from) * 2 / 5) bandRows.Add(d);
        }
        if (bandRows.Count == 0) return ("none", 0, 0, 0, false);
        // Groups of contiguous band rows: one group is a single sub-line, two separated
        // groups are the two lines of a double border.
        var sideGroups = new List<(int Start, int End)>();
        var start = bandRows[0];
        var prev = bandRows[0];
        foreach (var d in bandRows.Skip(1))
        {
            if (d == prev + 1) { prev = d; continue; }
            sideGroups.Add((start, prev));
            start = prev = d;
        }
        sideGroups.Add((start, prev));
        if (sideGroups.Count > 2) return (null, 0, 0, 0, true);
        var thicknessPx = (float)(sideGroups[^1].End - sideGroups[0].Start + 1);
        // Runs along the middle row of the first group (the midline of the outer sub-line).
        var mid = (sideGroups[0].Start + sideGroups[0].End) / 2;
        var sideRuns = new List<(int Start, int End)>();
        int runStart = -1;
        for (var p = from; p < to; p++)
        {
            var inked = InkedAt(p, mid);
            if (inked && runStart < 0) runStart = p;
            if (!inked && runStart >= 0) { sideRuns.Add((runStart, p - 1)); runStart = -1; }
        }
        if (runStart >= 0) sideRuns.Add((runStart, to - 1));
        if (sideRuns.Count == 0) return (null, 0, 0, 0, true);
        var extent = sideRuns[^1].End - sideRuns[0].Start + 1;
        if (sideRuns.Count == 1)
        {
            if (sideRuns[0].End - sideRuns[0].Start + 1 < extent * 85 / 100) return (null, 0, 0, 0, true);
            return (sideGroups.Count == 2 ? "double" : "solid", thicknessPx, sideGroups.Count, 1, false);
        }
        if (sideRuns.Count < 3) return (null, 0, sideGroups.Count, sideRuns.Count, false);
        var interior = sideRuns.Skip(1).Take(sideRuns.Count - 2).ToList();
        if (interior.Count == 0) return (null, 0, sideGroups.Count, sideRuns.Count, false);
        var dashLike = interior.All(r => r.End - r.Start + 1 >= 1.5 * thicknessPx);
        var dotLike = interior.All(r => r.End - r.Start + 1 <= 1.5 * thicknessPx + EdgeTolerance);
        if (dashLike) return ("dashed", thicknessPx, sideGroups.Count, sideRuns.Count, false);
        if (dotLike) return ("dotted", thicknessPx, sideGroups.Count, sideRuns.Count, false);
        return (null, thicknessPx, sideGroups.Count, sideRuns.Count, false);
    }

    private static float MaxEdge(this EdgeSizes edges) => Math.Max(edges.Top, Math.Max(edges.Right, Math.Max(edges.Bottom, edges.Left)));

    private static LayoutNode? FirstLeafCell(LayoutNode table)
    {
        LayoutNode? best = null;
        void Walk(LayoutNode node)
        {
            if (best is not null) return;
            var display = node.TryResolveStyle("display", out var d) ? d : node.Style?.GetPropertyValueSafe("display");
            if (display is "table-cell") { best = node; return; }
            foreach (var child in node.Children) Walk(child);
        }
        Walk(table);
        return best;
    }

    private static LayoutNode? FindById(LayoutNode root, string id)
    {
        if (string.Equals(root.Id, id, StringComparison.Ordinal)) return root;
        foreach (var child in root.Children)
            if (FindById(child, id) is { } found) return found;
        return null;
    }

    /// <summary>The first element below <paramref name="top"/> whose text mentions the
    /// filler text; its ink is what the text checks read.</summary>
    private static LayoutNode? FindFiller(LayoutNode root, int top) => FindNodeByText(root, top, "filler text");

    /// <summary>The first element below <paramref name="top"/> whose text contains (or,
    /// with <paramref name="exact"/>, equals) <paramref name="needle"/>.</summary>
    private static LayoutNode? FindNodeByText(LayoutNode root, int top, string needle, bool exact = false)
    {
        LayoutNode? best = null;
        void Walk(LayoutNode node)
        {
            if (best is not null) return;
            if (!node.TagName.StartsWith('#') && node.Box.BorderBox.Top >= top)
            {
                var text = Normalize(Text(node));
                if (exact ? text == needle : text.Contains(needle, StringComparison.Ordinal))
                {
                    best = node;
                    return;
                }
            }
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return best;
    }

    /// <summary>The ink components inside the element's border box (inflated by
    /// <paramref name="inflate"/> px), i.e. the text and any decoration lines.</summary>
    private static List<Component> ElementInk(SKBitmap bitmap, LayoutNode node, int inflate, out SKRectI box)
    {
        var border = node.Box.BorderBox;
        box = SKRectI.Round(new SKRect(border.Left - inflate, border.Top - inflate, border.Right + inflate, border.Bottom + inflate));
        box.Intersect(new SKRectI(0, 0, bitmap.Width, bitmap.Height));
        var region = box;
        return Components(bitmap, box, out _).Where(c =>
            c.Right > region.Left && c.Left < region.Right && c.Bottom > region.Top && c.Top < region.Bottom).ToList();
    }

    /// <summary>Ink over the union of several elements' border boxes (the text-run read:
    /// a word split across pseudo elements paints in each pseudo's own box).</summary>
    private static List<Component> ElementInk(SKBitmap bitmap, IReadOnlyList<LayoutNode> nodes, int inflate, out SKRectI box)
    {
        box = default;
        var first = true;
        foreach (var n in nodes)
        {
            var border = n.Box.BorderBox;
            var piece = SKRectI.Round(new SKRect(border.Left - inflate, border.Top - inflate,
                                                 border.Right + inflate, border.Bottom + inflate));
            box = first ? piece : SKRectI.Union(box, piece);
            first = false;
        }
        box.Intersect(new SKRectI(0, 0, bitmap.Width, bitmap.Height));
        var region = box;
        return Components(bitmap, box, out _).Where(c =>
            c.Right > region.Left && c.Left < region.Right && c.Bottom > region.Top && c.Top < region.Bottom).ToList();
    }

    private static WptRunner.RunResult TextColor(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string sentence)
    {
        // "this line should be <color>" states the condition on the instruction paragraph
        // itself (some suites repeat it over several lines — every one is checked);
        // "the following lines should all be green" covers every text element after it;
        // otherwise the filler-text element below the instructions is the test.
        List<LayoutNode> targets;
        if (check.Scope == "following")
        {
            targets = TextElementsBelow(root, top);
            if (targets.Count == 0)
                return new(WptRunner.Cat.Unsupported, "Visual check: no text elements below the instructions", 0, 0);
        }
        else if (check.Anchor == "instruction")
        {
            targets = InstructionNodes(root, sentence);
            if (targets.Count == 0)
                return new(WptRunner.Cat.Unsupported, "Visual check: no element to colour-check below the instructions", 0, 0);
        }
        else
        {
            var node = check.Needle is { } needle ? FindNodeByText(root, top, needle) : FindFiller(root, top);
            targets = node is null ? [] : [node];
            if (targets.Count == 0)
                return new(WptRunner.Cat.Unsupported, "Visual check: no element to colour-check below the instructions", 0, 0);
        }
        foreach (var node in targets)
        {
            if (TextColorOf(check, bitmap, node) is { } failure)
                return failure;
        }
        var describe = Describe(check) + (targets.Count > 1 ? $" ({targets.Count} elements)" : "");
        return new(WptRunner.Cat.Pass, describe, 1, 0, [new(describe, 0, null)], 0);
    }

    /// <summary>"Below, the left 'Green Text' is green and the right 'Black Text' is black"
    /// (and the upper/lower variant): each named text element carries its own stated ink
    /// color. <c>Ordered</c> pins repeated needles to their occurrence (the upper/lower
    /// "Filler Text" pair reads the first and second elements with that text).</summary>
    private static WptRunner.RunResult TextColorPairs(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top)
    {
        var needles = check.Needles ?? [];
        var colors = check.Colors ?? [];
        if (needles.Count == 0 || needles.Count != colors.Count)
            return new(WptRunner.Cat.Unsupported, "Visual check: text-color-pairs needs equal needle/color lists", 0, 0);
        var assertion = Describe(check);
        for (var i = 0; i < needles.Count; i++)
        {
            LayoutNode? node;
            if (check.Ordered)
            {
                node = FindNodeByOccurrence(root, top, needles[i], i);
                if (node is null)
                    return new(WptRunner.Cat.Fail, $"{assertion}: only {i} element(s) render '{needles[i]}'", 1, 1,
                        [new(assertion, 1, "missing occurrence")], 0);
            }
            else
            {
                node = FindNodeByText(root, top, needles[i]);
                if (node is null)
                    return new(WptRunner.Cat.Fail, $"{assertion}: no element renders '{needles[i]}'", 1, 1,
                        [new(assertion, 1, "text not in the layout tree")], 0);
            }
            var perCheck = check with { Color = colors[i], Needle = needles[i] };
            if (TextColorOf(perCheck, bitmap, node) is { } failure)
                return failure;
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The (index+1)-th text element whose normalized text contains the needle.</summary>
    private static LayoutNode? FindNodeByOccurrence(LayoutNode root, int top, string needle, int index)
    {
        var hits = new List<LayoutNode>();
        void Walk(LayoutNode node)
        {
            if (!node.TagName.StartsWith('#') && node.Box.BorderBox.Top >= top &&
                Normalize(Text(node)).Contains(needle, StringComparison.Ordinal))
                hits.Add(node);
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return index < hits.Count ? hits[index] : null;
    }

    private static WptRunner.RunResult? TextColorOf(VisualCheck check, SKBitmap bitmap, LayoutNode node)
    {
        var ink = ElementInk(bitmap, node, 1, out var box);
        // "This line should be green" is stated about the whole line: white-on-green lines
        // state their background, ordinary coloured text states its ink — either layer may
        // carry the named colour.
        if (ink.Count == 0 && check.Anchor != "instruction")
            return new(WptRunner.Cat.Fail, $"{Describe(check)}: the text painted no ink", 1, 1,
                [new(Describe(check), 1, "no ink")], 0);
        var counts = new Dictionary<uint, long>();
        var boxCounts = new Dictionary<uint, long>();
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        var background = ink.Count > 0 ? BackgroundOf(bitmap, ink) : CropBackground(bitmap, box);
        foreach (var c in ink)
            for (var y = c.Top; y < c.Bottom; y++)
            for (var x = c.Left; x < c.Right; x++)
            {
                var p = pixels[y * width + x];
                if (Distance(p, background) > InkThreshold)
                    counts[(uint)p] = counts.GetValueOrDefault((uint)p) + 1;
            }
        for (var y = box.Top; y < box.Bottom; y++)
        for (var x = box.Left; x < box.Right; x++)
        {
            var p = pixels[y * width + x];
            boxCounts[(uint)p] = boxCounts.GetValueOrDefault((uint)p) + 1;
        }
        if (counts.Count == 0 && check.Anchor != "instruction")
            return new(WptRunner.Cat.Fail, $"{Describe(check)}: the filler text painted no ink", 1, 1,
                [new(Describe(check), 1, "no ink")], 0);
        bool DominantMatches(Dictionary<uint, long> histogram) =>
            histogram.Count > 0 && Matches(check.Color!, new SKColor(histogram.MaxBy(kv => kv.Value).Key));
        if (DominantMatches(counts) || DominantMatches(boxCounts)) return null;
        var dominant = counts.Count > 0 ? new SKColor(counts.MaxBy(kv => kv.Value).Key) : background;
        return new(WptRunner.Cat.Fail, $"{Describe(check)}: ink is {dominant}", 1, 1,
            [new(Describe(check), 1, $"dominant ink {dominant}, not {check.Color}")], 0);
    }

    private static SKColor BackgroundOf(SKBitmap bitmap, List<Component> region)
    {
        var counts = new Dictionary<uint, long>();
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        foreach (var c in region)
            for (var y = c.Top; y < c.Bottom; y++)
            for (var x = c.Left; x < c.Right; x++)
                counts[(uint)pixels[y * width + x]] = counts.GetValueOrDefault((uint)pixels[y * width + x]) + 1;
        return counts.Count == 0 ? SKColors.White : new SKColor(counts.MaxBy(kv => kv.Value).Key);
    }

    private static SKColor CropBackground(SKBitmap bitmap, SKRectI region)
    {
        var counts = new Dictionary<uint, long>();
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        for (var y = region.Top; y < region.Bottom; y++)
        for (var x = region.Left; x < region.Right; x++)
            counts[(uint)pixels[y * width + x]] = counts.GetValueOrDefault((uint)pixels[y * width + x]) + 1;
        return counts.Count == 0 ? SKColors.White : new SKColor(counts.MaxBy(kv => kv.Value).Key);
    }

    /// <summary>A near solid ink row within 5px below the text's own ink — the underline
    /// when it merges with the glyphs' bottom rows instead of painting as its own band.</summary>
    private static bool RowNearlyInkBelow(SKBitmap bitmap, List<Component> ink, int textLeft, int textRight, int textBottom)
    {
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        var background = BackgroundOf(bitmap, ink);
        for (var y = textBottom - 1; y <= textBottom + 5; y++)
        {
            if (y < 0 || y >= bitmap.Height) continue;
            long inked = 0, total = 0;
            for (var x = textLeft; x < textRight; x++)
            {
                total++;
                if (Distance(pixels[y * width + x], background) > InkThreshold) inked++;
            }
            if (total > 0 && inked >= total * 3 / 5) return true;
        }
        return false;
    }

    /// <summary>The filler text's decoration lines read from the render: an over-line band
    /// just above the ink, an under-line band just below it, and a through-line as a
    /// mid-height row of the text inked nearly solid (glyph gaps filled by the line).</summary>
    private static WptRunner.RunResult TextDecoration(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var filler = FindFiller(root, top);
        if (filler is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no filler-text element below the instructions", 0, 0);
        var ink = ElementInk(bitmap, filler, 6, out var box);
        var text = ink.Where(c => c.Height > 5).ToList();
        if (text.Count == 0)
            return new(WptRunner.Cat.Unsupported, "Visual check: the filler text painted no readable ink", 0, 0);
        int textTop = text.Min(c => c.Top), textBottom = text.Max(c => c.Bottom);
        int textLeft = text.Min(c => c.Left), textRight = text.Max(c => c.Right);
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        // The page background behind the text — the region's dominant colour, NOT the glyph
        // components' own: serif strokes fragment into sliver components whose tight boxes
        // are stroke-dominated, which would answer black and read every white pixel as ink.
        var background = CropBackground(bitmap, box);
        // The decoration lines read by row scan: a near-solid row within a few pixels of the
        // glyph band's top/bottom edge. Band components alone misread at small font sizes,
        // where the line merges with the glyphs' antialiasing instead of painting its own shape.
        long RowInked(int y)
        {
            if (y < 0 || y >= bitmap.Height) return 0;
            long inked = 0;
            for (var x = textLeft; x < textRight; x++)
                if (Distance(pixels[y * width + x], background) > InkThreshold) inked++;
            return inked;
        }
        var spanPx = textRight - textLeft;
        bool RowNearlyInk(int y) => RowInked(y) * 5 >= spanPx * 3;
        var over = Enumerable.Range(textTop - 6, 8).Any(RowNearlyInk);
        var under = Enumerable.Range(textBottom - 1, 7).Any(RowNearlyInk);
        // A through-line fills the glyph gaps: the best mid-height row approaches solid.
        var through = Enumerable.Range(textTop, Math.Max(1, textBottom - textTop))
            .Select(RowInked).Max() * 20 >= spanPx * 17;
        var assertion = Describe(check);
        if (check.Under is false)
            return !under
                ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
                : new(WptRunner.Cat.Fail, $"{assertion}: a line under the text is painted", 1, 1,
                    [new(assertion, 1, "an under-line band is present")], 0);
        if (check.Through is false && check.Over is not true && check.Under is not true)
            return !through
                ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
                : new(WptRunner.Cat.Fail, $"{assertion}: a line through the text is painted", 1, 1,
                    [new(assertion, 1, "the mid-height row reads as a through-line")], 0);
        var missing = new List<string>();
        if (check.Over == true && !over) missing.Add("over");
        if (check.Under == true && !under) missing.Add("under");
        if (check.Through == true && !through) missing.Add("through");
        if (missing.Count > 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no {string.Join(", ", missing)} line is visible", 1, 1,
                [new(assertion, 1, $"missing {string.Join(", ", missing)}")], 0);
        if (check.Span is { } span && !SpanHolds(span, check, ink, textTop, textBottom, textLeft, textRight, filler, bitmap, background))
            return new(WptRunner.Cat.Fail, $"{assertion}: the decoration line does not {(
                span == "text" ? "stop at the text" : "cover the spaces around the text")}", 1, 1,
                [new(assertion, 1, $"the line's extent is wrong for span '{span}'")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The decoration line's extent, read from the rows that carry it: "text" —
    /// the line's own rows hold no ink beyond the glyph span (it may not run over a border);
    /// "beyond" — the line also covers the surrounding space.</summary>
    private static bool SpanHolds(string span, VisualCheck check, List<Component> ink,
        int textTop, int textBottom, int textLeft, int textRight, LayoutNode filler, SKBitmap bitmap, SKColor background)
    {
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        int LineEdge(int from, int to, bool fromRight)
        {
            int? edge = null;
            for (var y = from; y < to; y++)
            {
                if (y < 0 || y >= bitmap.Height) continue;
                var x = fromRight ? textRight - 1 : textLeft;
                while (x != (fromRight ? textLeft - 1 : textRight))
                {
                    if (x >= 0 && x < width && Distance(pixels[y * width + x], background) > InkThreshold)
                    {
                        edge = fromRight ? Math.Min(edge ?? x, x) : Math.Max(edge ?? x, x);
                        break;
                    }
                    x += fromRight ? -1 : 1;
                }
            }
            return edge ?? (fromRight ? textRight : textLeft);
        }
        // The line's rows: over — above the glyphs; under — below them; through — the middle.
        var (rowFrom, rowTo) = check.Over == true && check.Under is not true
            ? (textTop - 6, textTop + 2)
            : check.Under == true ? (textBottom - 1, textBottom + 6)
            : ((textTop + textBottom) / 2, (textTop + textBottom) / 2 + 1);
        var lineLeft = LineEdge(rowFrom, rowTo, fromRight: false);
        var lineRight = LineEdge(rowFrom, rowTo, fromRight: true);
        if (span == "text")
            return lineLeft >= textLeft - 3 && lineRight <= textRight + 3;
        return lineLeft <= textLeft - 2 || lineRight >= textRight + 2;
    }

    private static WptRunner.RunResult AlignRight(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var filler = FindFiller(root, top);
        if (filler is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no filler-text element below the instructions", 0, 0);
        // The container is an ancestor materially wider than the text.
        var container = filler.Parent;
        while (container is { } parent && parent.Box.BorderBox.Width < filler.Box.BorderBox.Width * 1.5 && parent.Parent is not null)
            container = parent.Parent;
        if (container is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no container box around the filler text", 0, 0);
        var ink = ElementInk(bitmap, filler, 1, out _);
        if (ink.Count == 0)
            return new(WptRunner.Cat.Fail, $"{Describe(check)}: the filler text painted no ink", 1, 1,
                [new(Describe(check), 1, "no ink")], 0);
        var assertion = Describe(check);
        if (check.Side == "left")
        {
            var inkLeft = ink.Min(c => c.Left);
            var contentLeft = container.Box.ContentBox.Left;
            return Math.Abs(inkLeft - contentLeft) <= 2
                ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
                : new(WptRunner.Cat.Fail, $"{assertion}: ink starts at {inkLeft}, container content edge is {contentLeft}", 1, 1,
                    [new(assertion, 1, $"ink left {inkLeft}, content left {contentLeft}")], 0);
        }
        var inkRight = ink.Max(c => c.Right);
        var contentRight = container.Box.ContentBox.Right;
        return Math.Abs(inkRight - contentRight) <= 2
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: ink ends at {inkRight}, container content edge is {contentRight}", 1, 1,
                [new(assertion, 1, $"ink right {inkRight}, content right {contentRight}")], 0);
    }

    /// <summary>The letter "x" is rendered below the instructions; the "box-above" variant
    /// also requires exactly one box sitting entirely above it, not touching it.</summary>
    private static WptRunner.RunResult LetterX(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var x = FindNodeByText(root, top, "x", exact: true);
        if (x is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no letter-x element below the instructions", 0, 0);
        var xTop = (int)MathF.Floor(x.Box.BorderBox.Top);
        var ink = ElementInk(bitmap, x, 1, out var xBox);
        var assertion = Describe(check);
        if (ink.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: the letter x painted no ink", 1, 1,
                [new(assertion, 1, "no ink in the x's box")], 0);
        if (check.Variant != "box-above")
            return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
        var components = Components(bitmap, top, out var clipped);
        if (clipped)
            return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var above = TopLevel(components).Where(s => s.Bottom <= xTop + 1 &&
            !s.Intersects(new Component(xBox.Left, xBox.Top, xBox.Right, xBox.Bottom, true, default))).ToList();
        return above.Count == 1 && (long)above[0].Width * above[0].Height >= 400
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: {above.Count} boxes sit above the letter x", 1, 1,
                [new(assertion, 1, $"{above.Count} boxes above the x")], 0);
    }

    /// <summary>Classifies one horizontal band's pattern from the runs along its densest
    /// row: dots have runs no longer than 1.5× their gaps, dashes have runs at least that
    /// long, a single unbroken run is solid. Returns null when the band is unclassifiable
    /// (fewer than three runs of mixed character).</summary>
    private static string? ClassifyBand(SKBitmap bitmap, SKColor background, int from, int to, int bandTop, int depth)
    {
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        bool Inked(int x, int y) => x >= 0 && x < width && y >= 0 && y < bitmap.Height &&
            Distance(pixels[y * width + x], background) > InkThreshold;
        string? best = null;
        for (var y = bandTop; y < bandTop + depth; y++)
        {
            var runs = new List<(int Start, int End)>();
            int runStart = -1;
            for (var x = from; x < to; x++)
            {
                if (Inked(x, y) && runStart < 0) runStart = x;
                if (!Inked(x, y) && runStart >= 0) { runs.Add((runStart, x - 1)); runStart = -1; }
            }
            if (runStart >= 0) runs.Add((runStart, to - 1));
            if (runs.Count == 1) { best ??= "solid"; continue; }
            if (runs.Count < 3) continue;
            var lengths = runs.Select(r => r.End - r.Start + 1).OrderBy(l => l).ToList();
            // Skip the shortest runs: the first dot can merge with the neighbouring text's
            // first glyph, which would otherwise drag the minimum gap to nothing.
            var interior = lengths.Skip(Math.Max(1, lengths.Count / 4)).ToList();
            var gaps = new List<int>();
            for (var k = 0; k < runs.Count - 1; k++) gaps.Add(runs[k + 1].Start - runs[k].End - 1);
            gaps.Sort();
            var medianGap = Math.Max(1, gaps.Count > 0 ? gaps[gaps.Count / 2] : 1);
            if (interior.All(l => l <= 1.5 * medianGap + 2)) return "dotted";
            if (interior.All(l => l >= 1.5 * medianGap)) return "dashed";
            best ??= null;
        }
        return best;
    }

    /// <summary>The stated dashed/dotted outline is painted around each named text element
    /// ('sample text', and 'filler text' where the sentence names it as a second outlined
    /// element). The "is overlapped by the outline" variant outlines only the 'Sample Text' —
    /// the filler text is what the outline overlaps — so after the sample's ring reads the
    /// stated style, the outline's lower band must reach into the filler text's own ink band.</summary>
    private static WptRunner.RunResult OutlineText(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var checkedAny = false;
        foreach (var needle in new[] { "sample text", "filler text" })
        {
            var node = FindNodeByText(root, top, needle);
            if (node is null) continue;
            checkedAny = true;
            var box = SKRectI.Round(node.Box.BorderBox);
            if (check.Variant == "overlap" && needle != "sample text")
            {
                // The overlap clause: the outline's lower band and the filler text's own
                // glyphs share ink rows (the outline-width extends past the border box into
                // the following element's text).
                var sample = FindNodeByText(root, top, "sample text");
                if (sample is null)
                    return new(WptRunner.Cat.Unsupported, "Visual check: no sample-text element for the overlap clause", 0, 0);
                var sampleBox = SKRectI.Round(sample.Box.BorderBox);
                var fillerBox = SKRectI.Round(node.Box.BorderBox);
                var background = CropBackground(bitmap, SKRectI.Round(new SKRect(sampleBox.Left, sampleBox.Bottom, sampleBox.Right, sampleBox.Bottom + 34)));
                // The outline's lower band: the last row below the sample text with the dot
                // pattern's ink share (its sparse dots sit near a third of the row; the next
                // element's own glyphs stay near an eighth). The band must reach a few pixels
                // into the filler text's box — its glyphs begin right at the top.
                var bandBottom = -1;
                for (var d = 0; d < 34; d++)
                {
                    long inked = 0;
                    var y = sampleBox.Bottom + d;
                    if (y >= bitmap.Height) break;
                    for (var x = sampleBox.Left; x < sampleBox.Right; x++)
                        if (Distance(bitmap.Pixels[y * bitmap.Width + x], background) > InkThreshold) inked++;
                    if (inked >= (sampleBox.Right - sampleBox.Left) / 4) bandBottom = y;
                }
                if (bandBottom < fillerBox.Top + 4)
                    return new(WptRunner.Cat.Fail, $"{assertion}: the outline does not overlap the filler text (band ends {bandBottom}, filler box starts {fillerBox.Top})", 1, 1,
                        [new(assertion, 1, $"outline band ends {bandBottom}, filler box starts {fillerBox.Top}")], 0);
                continue;
            }
            // The engine's dotted/dashed rendering is sparse (dot runs well under half the
            // row), which the border-ring reader's band-row threshold cannot see; the band
            // classifier reads it. The band above and the band below the sample text must
            // both read the stated pattern — an outline goes around.
            var aboveBg = CropBackground(bitmap, SKRectI.Round(new SKRect(box.Left, box.Top - 26, box.Right, box.Top)));
            var above = ClassifyBand(bitmap, aboveBg, box.Left, box.Right, box.Top - 26, 26);
            if (above != check.Shape)
                return new(WptRunner.Cat.Fail, $"{assertion}: the outline above the text reads {above ?? "nothing"}, not {check.Shape}", 1, 1,
                    [new(assertion, 1, $"the band above reads {above ?? "nothing"}")], 0);
            var belowBg = CropBackground(bitmap, SKRectI.Round(new SKRect(box.Left, box.Bottom, box.Right, box.Bottom + 26)));
            var below = ClassifyBand(bitmap, belowBg, box.Left, box.Right, box.Bottom, 26);
            if (below != check.Shape)
                return new(WptRunner.Cat.Fail, $"{assertion}: the outline below the text reads {below ?? "nothing"}, not {check.Shape}", 1, 1,
                    [new(assertion, 1, $"the band below reads {below ?? "nothing"}")], 0);
        }
        return checkedAny
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Unsupported, "Visual check: none of the named text elements were found", 0, 0);
    }

    /// <summary>The bottom edge of the element whose text starts the stated sentence.</summary>
    internal static int? InstructionBottom(LayoutNode root, string sentence)
    {
        if (InstructionNode(root, sentence) is not { } best) return null;
        var bottom = best.Box.BorderBox.Bottom;
        // The suite's follow-up notes (<p class="instructionNote">) belong to the instructions.
        if (best.Parent is { } parent)
            foreach (var sibling in parent.Children.SkipWhile(c => !ReferenceEquals(c, best)).Skip(1))
            {
                if (sibling.TagName.StartsWith('#')) continue;
                if (!sibling.Attributes.GetValueOrDefault("class", "").Contains("instruction", StringComparison.OrdinalIgnoreCase)) break;
                bottom = Math.Max(bottom, sibling.Box.BorderBox.Bottom);
            }
        return (int)MathF.Ceiling(bottom);
    }

    /// <summary>The element whose text starts the stated sentence (the instruction
    /// paragraph, which some checks anchor to directly).</summary>
    internal static LayoutNode? InstructionNode(LayoutNode root, string sentence)
    {
        var key = Normalize(sentence);
        key = key[..Math.Min(key.Length, 40)];
        if (key.Length == 0) return null;
        LayoutNode? best = null;
        void Walk(LayoutNode node)
        {
            if (node.TagName.StartsWith('#')) return;
            if (Normalize(Text(node)).StartsWith(key, StringComparison.Ordinal)) best = node;
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return best;
    }

    /// <summary>Every element whose text starts the stated sentence — some suites repeat the
    /// same instruction line several times, and each repeat states the condition.</summary>
    private static List<LayoutNode> InstructionNodes(LayoutNode root, string sentence)
    {
        var key = Normalize(sentence);
        key = key[..Math.Min(key.Length, 40)];
        var found = new List<LayoutNode>();
        if (key.Length == 0) return found;
        void Walk(LayoutNode node)
        {
            if (!node.TagName.StartsWith('#') && Normalize(Text(node)).StartsWith(key, StringComparison.Ordinal))
                found.Add(node);
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return found;
    }

    /// <summary>Every element strictly below <paramref name="top"/> that carries text and is
    /// not an instruction note.</summary>
    private static List<LayoutNode> TextElementsBelow(LayoutNode root, int top)
    {
        var found = new List<LayoutNode>();
        void Walk(LayoutNode node)
        {
            if (!node.TagName.StartsWith('#') && node.Box.BorderBox.Top >= top &&
                Normalize(Text(node)).Length > 0 &&
                !node.Attributes.GetValueOrDefault("class", "").Contains("instruction", StringComparison.OrdinalIgnoreCase))
                found.Add(node);
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return found;
    }

    /// <summary>Every element whose text contains the needle, in document order.</summary>
    private static List<LayoutNode> FindAllNodesByText(LayoutNode root, int top, string needle)
    {
        var found = new List<LayoutNode>();
        void Walk(LayoutNode node)
        {
            if (!node.TagName.StartsWith('#') && node.Box.BorderBox.Top >= top &&
                Normalize(Text(node)).Contains(needle, StringComparison.Ordinal))
                found.Add(node);
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return found;
    }

    /// <summary>Horizontal ink bands at or below <paramref name="top"/>: contiguous row
    /// ranges that carry ink, with their combined ink components. Text lines, dashed lines
    /// and image rows all read as bands.</summary>
    internal static List<(int Top, int Bottom, List<Component> Members)> InkBands(SKBitmap bitmap, int top, out bool clipped)
    {
        var components = Components(bitmap, top, out clipped);
        return InkBandsOf(components);
    }

    internal static List<(int Top, int Bottom, List<Component> Members)> InkBandsOf(IReadOnlyList<Component> components)
    {
        var ordered = components.OrderBy(c => c.Top).ToList();
        var bands = new List<(int Top, int Bottom, List<Component> Members)>();
        foreach (var c in ordered)
        {
            if (bands.Count > 0 && c.Top < bands[^1].Bottom - EdgeTolerance)
                bands[^1] = (bands[^1].Top, Math.Max(bands[^1].Bottom, c.Bottom), bands[^1].Members.Concat([c]).ToList());
            else
                bands.Add((c.Top, c.Bottom, [c]));
        }
        return bands;
    }

    /// <summary>The first element strictly below the instructions that carries no text —
    /// the suite's empty painted test box (background/tiling tests).</summary>
    private static LayoutNode? FindEmptyBox(LayoutNode root, int top)
    {
        LayoutNode? best = null;
        void Walk(LayoutNode node)
        {
            if (best is not null) return;
            if (!node.TagName.StartsWith('#') && node.Box.BorderBox.Top >= top &&
                Normalize(Text(node)).Length == 0 && node.Box.BorderBox.Width > 40 && node.Box.BorderBox.Height > 20)
            {
                best = node;
                return;
            }
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return best;
    }

    private static string Text(LayoutNode node)
    {
        var text = new System.Text.StringBuilder(node.DisplayText);
        foreach (var child in node.Children) text.Append(' ').Append(Text(child));
        return text.ToString();
    }

    private static string Normalize(string text) =>
        string.Join(' ', text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries)).ToLowerInvariant();

    /// <summary>The "Filler Text" elements' first lines align — table cells' vertical-align
    /// and baseline checks. 'bottom' reads each element's FIRST ink band's bottom edge (the
    /// first baseline): a wrapped cell's later lines sit lower and would mask the alignment
    /// the sentence states. 'top' reads the element boxes' tops — the line box, not the ink
    /// (different font sizes leave different leading above the glyphs).</summary>
    private static WptRunner.RunResult TextBaseline(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var fillers = FindAllNodesByText(root, top, "filler text");
        if (fillers.Count < 2)
            return new(WptRunner.Cat.Unsupported, $"Visual check: only {fillers.Count} filler-text elements below the instructions", 0, 0);
        var edges = new List<int>();
        foreach (var filler in fillers)
        {
            if (check.Edge == "top")
            {
                edges.Add((int)MathF.Round(filler.Box.BorderBox.Top));
                continue;
            }
            var ink = ElementInk(bitmap, filler, 1, out _);
            if (ink.Count == 0)
                return new(WptRunner.Cat.Fail, $"{Describe(check)}: a filler text painted no ink", 1, 1,
                    [new(Describe(check), 1, "no ink")], 0);
            // The first band's bottom: the element's first baseline region.
            var bands = InkBandsOf(ink);
            edges.Add(bands[0].Bottom);
        }
        var spread = edges.Max() - edges.Min();
        return spread <= 2
            ? new(WptRunner.Cat.Pass, Describe(check), 1, 0, [new(Describe(check), 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{Describe(check)}: {check.Edge ?? "bottom"} edges span {spread}px", 1, 1,
                [new(Describe(check), 1, string.Join(", ", edges.OrderBy(e => e).Distinct()))], 0);
    }

    /// <summary>Every "Filler Text" element's ink sits in one horizontal band — the elements
    /// share a line.</summary>
    private static WptRunner.RunResult OneLine(SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var fillers = FindAllNodesByText(root, top, "filler text");
        if (fillers.Count < 2)
            return new(WptRunner.Cat.Unsupported, $"Visual check: only {fillers.Count} filler-text elements below the instructions", 0, 0);
        var tops = new List<int>();
        var bottoms = new List<int>();
        foreach (var filler in fillers)
        {
            var ink = ElementInk(bitmap, filler, 1, out _);
            if (ink.Count == 0)
                return new(WptRunner.Cat.Fail, "the filler text painted no ink", 1, 1, [new("one line", 1, "no ink")], 0);
            tops.Add(ink.Min(c => c.Top));
            bottoms.Add(ink.Max(c => c.Bottom));
        }
        var overlap = Math.Min(bottoms.Max(), bottoms.Min()) - Math.Max(tops.Max(), tops.Min());
        return overlap > 0
            ? new(WptRunner.Cat.Pass, Describe(new VisualCheck("one-line")), 1, 0, [new("one line", 0, null)], 0)
            : new(WptRunner.Cat.Fail, "the filler texts sit on different lines", 1, 1,
                [new("one line", 1, $"vertical overlap {overlap}px")], 0);
    }

    /// <summary>A small (square) bullet sits at the start of the first text line and the
    /// second line flows below it (not indented past the bullet).</summary>
    private static WptRunner.RunResult FirstLineMarker(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var bands = InkBands(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var textBands = bands.Where(b => b.Members.Max(m => m.Height) > 5).ToList();
        if (textBands.Count < 2)
            return new(WptRunner.Cat.Unsupported, $"Visual check: only {textBands.Count} text bands below the instructions", 0, 0);
        var first = textBands[0];
        var marker = first.Members.FirstOrDefault(m => Math.Max(m.Width, m.Height) is > 4 and <= 26 &&
            Math.Abs(m.Width - m.Height) <= 3 * EdgeTolerance &&
            (check.Color is null || Matches(check.Color, m.Color)));
        if (marker.Width == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no {(check.Color is null ? "" : check.Color + " ")}square bullet on the first line", 1, 1,
                [new(assertion, 1, "no bullet-sized square in the first line's band")], 0);
        if (marker.Left > first.Members.Min(m => m.Left) + 2 * EdgeTolerance)
            return new(WptRunner.Cat.Fail, $"{assertion}: the bullet is not at the line's start", 1, 1,
                [new(assertion, 1, $"bullet at x {marker.Left}")], 0);
        // The second line's left edge: the leftmost ink in the rows between the first band's
        // bottom and the second band's bottom. Band members alone misread here — line 2's
        // first glyph can antialias up into the first band and merge with it, which would
        // report the line's second glyph instead of its start.
        var second = textBands[1];
        var secondLeft = second.Members.Max(m => m.Right);
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        var white = CropBackground(bitmap, new SKRectI(0, first.Bottom, width, Math.Min(second.Bottom + 1, bitmap.Height)));
        for (var y = first.Bottom; y < second.Bottom && y < bitmap.Height; y++)
        for (var x = 0; x < second.Members.Max(m => m.Right) && x < width; x++)
        {
            if (Distance(pixels[y * width + x], white) <= InkThreshold) continue;
            secondLeft = Math.Min(secondLeft, x);
            break;
        }
        // Inside markers: line 2 realigns with the marker's own left edge (the content edge).
        // Outside markers hang left of the text, and line 2 realigns with the text start —
        // either way line 2 may not start past the first line's own content.
        var firstTextLeft = first.Members.Where(m => !ReferenceEquals(m, marker)).Min(m => m.Left);
        var line2Edge = Math.Max(marker.Right, firstTextLeft);
        if (secondLeft > line2Edge + 6)
        {
                return new(WptRunner.Cat.Fail, $"{assertion}: the second line does not flow below the bullet (starts at {secondLeft})", 1, 1,
                [new(assertion, 1, $"second line starts {secondLeft - line2Edge}px right of the first line's content")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>A marker bullet sits to the left of the stated line, vertically anywhere.</summary>
    private static WptRunner.RunResult LineMarker(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var line = shapes.FirstOrDefault(s => Math.Min(s.Width, s.Height) <= 30 &&
            Math.Max(s.Width, s.Height) >= 8 * Math.Max(2, Math.Min(s.Width, s.Height)) &&
            (check.Color is null || Matches(check.Color, s.Color)) &&
            (check.Shape is null || check.Shape is "solid"));
        if (line.Width == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no {(check.Color is null ? "" : check.Color + " ")}line below the instructions", 1, 1,
                [new(assertion, 1, "no line-shaped component")], 0);
        var bullets = shapes.Where(s => !ReferenceEquals(s, line) && Math.Max(s.Width, s.Height) <= 24 &&
            s.Right <= line.Left + EdgeTolerance && s.Top < line.Bottom && s.Bottom > line.Top).ToList();
        if (bullets.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no marker bullet to the left of the line", 1, 1,
                [new(assertion, 1, "no bullet beside the line")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>A bullet sits on the stated side of (or above) a square/bar.</summary>
    private static WptRunner.RunResult BulletBeside(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var box = shapes.FirstOrDefault(s => s.Rectangular && Math.Min(s.Width, s.Height) >= 20 &&
            (check.Color is null || Matches(check.Color, s.Color)));
        if (box.Width == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no square below the instructions", 1, 1,
                [new(assertion, 1, "no box")], 0);
        var bullets = shapes.Where(s => !ReferenceEquals(s, box) && Math.Max(s.Width, s.Height) <= 24).ToList();
        var found = check.Side switch
        {
            "left" => bullets.Where(s => s.Right <= box.Left + EdgeTolerance && s.Top < box.Bottom && s.Bottom > box.Top).ToList(),
            "right" => bullets.Where(s => s.Left >= box.Right - EdgeTolerance && s.Top < box.Bottom && s.Bottom > box.Top).ToList(),
            "above" => bullets.Where(s => s.Bottom <= box.Top + EdgeTolerance && s.Right > box.Left && s.Left < box.Right).ToList(),
            _ => [],
        };
        return found.Count >= 1
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: no bullet {check.Side} the square", 1, 1,
                [new(assertion, 1, $"{bullets.Count} bullet-sized shapes, none {check.Side}")], 0);
    }

    /// <summary>Two bars stacked: the stated top color sits directly on the stated bottom color.</summary>
    private static WptRunner.RunResult BarStack(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var topBars = shapes.Where(s => Matches(check.ColorA, s.Color)).ToList();
        var bottomBars = shapes.Where(s => Matches(check.ColorB, s.Color)).ToList();
        if (topBars.Count != 1 || bottomBars.Count != 1)
            return new(WptRunner.Cat.Fail, $"{assertion}: {topBars.Count} {check.ColorA} and {bottomBars.Count} {check.ColorB} bars", 1, 1,
                [new(assertion, 1, "wrong bar count")], 0);
        return Touching(topBars[0], bottomBars[0]) && topBars[0].Top < bottomBars[0].Top
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: the {check.ColorA} bar is not stacked on the {check.ColorB} bar", 1, 1,
                [new(assertion, 1, "bars not stacked")], 0);
    }

    /// <summary>The element rendering the stated text sits with a marker bullet on its left.</summary>
    private static WptRunner.RunResult TextMarker(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var node = FindNodeByText(root, top, check.Needle!, exact: true);
        if (node is null)
            return new(WptRunner.Cat.Fail, $"{assertion}: no element renders the text '{check.Needle}'", 1, 1,
                [new(assertion, 1, "text not in the layout tree")], 0);
        var ink = ElementInk(bitmap, node, 1, out var box);
        if (ink.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: the number painted no ink", 1, 1, [new(assertion, 1, "no ink")], 0);
        var components = Components(bitmap, top, out _);
        var bullets = components.Where(s => Math.Max(s.Width, s.Height) <= 24 &&
            s.Right <= box.Left + EdgeTolerance && s.Top < box.Bottom && s.Bottom > box.Top).ToList();
        return bullets.Count >= 1
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: no marker bullet to the left of the number", 1, 1,
                [new(assertion, 1, "no bullet")], 0);
    }

    /// <summary>The stated numbers are rendered as layout text (content-generated counters);
    /// each must paint ink, and ordered variants must stack top to bottom. Digits painted as
    /// list markers never reach the layout tree — those report unsupported.</summary>
    private static WptRunner.RunResult NumbersPresent(VisualCheck check, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var textNodes = TextElementsBelow(root, top);
        if (textNodes.Count == 0)
            return new(WptRunner.Cat.Unsupported, "Visual check: no text below the instructions (digits painted as list markers are not layout text)", 0, 0);
        int? lastY = null;
        var needles = new List<string>(check.Needles ?? []);
        foreach (var needle in needles)
        {
            var node = textNodes.FirstOrDefault(n => Normalize(Text(n)) == needle || Normalize(Text(n)) == $"{needle}." ||
                                                     Normalize(Text(n)).Contains(needle, StringComparison.Ordinal));
            if (node is null)
                return new(WptRunner.Cat.Fail, $"{assertion}: no element renders '{needle}'", 1, 1,
                    [new(assertion, 1, $"'{needle}' not in the layout tree")], 0);
            if (check.Ordered && lastY is { } prev && node.Box.BorderBox.Top < prev - EdgeTolerance)
                return new(WptRunner.Cat.Fail, $"{assertion}: '{needle}' is not below the previous number", 1, 1,
                    [new(assertion, 1, "numbers out of order")], 0);
            lastY = (int)node.Box.BorderBox.Top;
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The stated text renders (its element paints ink); an optional stated bullet
    /// must sit to its right. Generated content carries text in the layout tree, so this
    /// checks quotes and counters too; absence of the text is a fail.</summary>
    private static WptRunner.RunResult TextInk(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var node = FindNodeByText(root, top, check.Needle!);
        List<LayoutNode>? run = null;
        if (node is null)
        {
            // Generated content splits a word across :before/:after pseudo elements — the
            // quotes family paints "PASS" as open/close-quote pairs producing "PA" | "SS"
            // on two nodes, and the alphabet families split their string the same way — so
            // no single element renders the needle. A run of consecutive text elements on
            // one line whose concatenated text contains it is the same rendering.
            run = FindTextRunByText(root, top, check.Needle!);
            if (run is null)
                return new(WptRunner.Cat.Fail, $"{assertion}: no element renders '{check.Needle}'", 1, 1,
                    [new(assertion, 1, "text not in the layout tree")], 0);
        }
        var ink = run is null
            ? ElementInk(bitmap, node!, 1, out var box)
            : ElementInk(bitmap, run, 1, out box);
        if (ink.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: the words painted no ink", 1, 1, [new(assertion, 1, "no ink")], 0);
        if (check.Bullet == "right")
        {
            var components = Components(bitmap, top, out _);
            var bullets = components.Where(s => Math.Max(s.Width, s.Height) <= 24 &&
                s.Left >= box.Right - EdgeTolerance && s.Top < box.Bottom && s.Bottom > box.Top).ToList();
            if (bullets.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: no bullet to the right of the text", 1, 1,
                    [new(assertion, 1, "no bullet")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>A run of consecutive text elements whose concatenated text contains the
    /// needle (case-folded — the generator lowercases quoted needles while the tree carries
    /// authored case). Consecutive members must overlap vertically so cross-line
    /// concatenation cannot fabricate a match; document order is the paint order for the
    /// pseudo-element splits this read exists for. Null when no run renders the needle.</summary>
    private static List<LayoutNode>? FindTextRunByText(LayoutNode root, int top, string needle)
    {
        var texts = new List<LayoutNode>();
        void Walk(LayoutNode node)
        {
            // Generated content lives on pseudo-element nodes named "#pseudo-before"/"#pseudo-after"
            // — the '#' prefix otherwise marks text/fragment nodes, so admit the pseudo names.
            var pseudo = node.TagName.StartsWith("#pseudo", StringComparison.Ordinal);
            if ((!node.TagName.StartsWith('#') || pseudo) && node.Box.BorderBox.Top >= top &&
                Normalize(Text(node)).Length > 0)
                texts.Add(node);
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        for (var width = 2; width <= texts.Count; width++)
        {
            for (var start = 0; start + width <= texts.Count; start++)
            {
                var window = texts.GetRange(start, width);
                var joined = string.Concat(window.Select(n => Normalize(Text(n))));
                if (!joined.Contains(needle, StringComparison.OrdinalIgnoreCase)) continue;
                var sameLine = true;
                for (var k = 1; k < window.Count; k++)
                {
                    var a = window[k - 1].Box.BorderBox;
                    var b = window[k].Box.BorderBox;
                    if (b.Top >= a.Bottom || a.Top >= b.Bottom) { sameLine = false; break; }
                }
                if (sameLine) return window;
            }
        }
        return null;
    }

    /// <summary>The stated words render as glyphs (not one solid Ahem block) and a box of the
    /// stated color sits below them.</summary>
    private static WptRunner.RunResult WordsAndBox(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var node = FindNodeByText(root, top, check.Needle!);
        if (node is null)
            return new(WptRunner.Cat.Fail, $"{assertion}: no element renders '{check.Needle}'", 1, 1,
                [new(assertion, 1, "text not in the layout tree")], 0);
        var ink = ElementInk(bitmap, node, 1, out var box);
        if (ink.Count < 2)
            return new(WptRunner.Cat.Fail, $"{assertion}: the words render as {(ink.Count == 0 ? "no ink" : "one solid block")}, not glyphs", 1, 1,
                [new(assertion, 1, $"{ink.Count} ink component(s) in the words' box")], 0);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var boxes = TopLevel(components).Where(s => Math.Min(s.Width, s.Height) >= 20 &&
            Matches(check.Color!, s.Color) && !s.Contains(new Component(box.Left, box.Top, box.Right, box.Bottom, true, default)) &&
            s.Top >= box.Bottom - 2).ToList();
        return boxes.Count >= 1
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: no {check.Color} box below the words", 1, 1,
                [new(assertion, 1, "no stated box below")], 0);
    }

    /// <summary>The stated element's ink is horizontally centered in its container's content
    /// box (text-align: center).</summary>
    private static WptRunner.RunResult AlignCenter(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string sentence, string path)
    {
        var node = check.Anchor == "instruction" ? InstructionNode(root, sentence) : FindFiller(root, top);
        if (node is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no element to center-check below the instructions", 0, 0);
        var ink = ElementInk(bitmap, node, 1, out _);
        if (ink.Count == 0)
            return new(WptRunner.Cat.Fail, $"{Describe(check)}: the text painted no ink", 1, 1,
                [new(Describe(check), 1, "no ink")], 0);
        var container = node.Parent;
        while (container is { } parent && parent.Box.ContentBox.Width < node.Box.BorderBox.Width * 1.2 && parent.Parent is not null)
            container = parent.Parent;
        if (container is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no container around the text", 0, 0);
        var inkLeft = ink.Min(c => c.Left);
        var inkRight = ink.Max(c => c.Right);
        var contentLeft = container.Box.ContentBox.Left;
        var contentRight = container.Box.ContentBox.Right;
        var leftGap = inkLeft - contentLeft;
        var rightGap = contentRight - inkRight;
        var assertion = Describe(check);
        return Math.Abs(leftGap - rightGap) <= 2
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: gaps {leftGap}px and {rightGap}px", 1, 1,
                [new(assertion, 1, "not centered")], 0);
    }

    private static readonly Dictionary<int, string> _sentences = new();

    /// <summary>The stated-color vertical lines have space between them; an optional marker
    /// bullet sits left of the lines.</summary>
    private static WptRunner.RunResult LinesSpaced(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var a = shapes.Where(s => Matches(check.ColorA!, s.Color) && s.Height > 3 * s.Width).ToList();
        var b = shapes.Where(s => Matches(check.ColorB!, s.Color) && s.Height > 3 * s.Width).ToList();
        if (a.Count == 0 || b.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: missing lines ({a.Count} {check.ColorA}, {b.Count} {check.ColorB})", 1, 1,
                [new(assertion, 1, "a stated line color is missing")], 0);
        var gap = Spacing(a, b);
        if (gap <= 2 * EdgeTolerance)
            return new(WptRunner.Cat.Fail, $"{assertion}: no space between the {check.ColorA} and {check.ColorB} lines ({gap}px)", 1, 1,
                [new(assertion, 1, $"gap {gap}px")], 0);
        if (check.Marker)
        {
            var leftmost = a.Concat(b).Min(s => s.Left);
            var bullets = shapes.Where(s => Math.Max(s.Width, s.Height) <= 24 &&
                s.Right <= leftmost + EdgeTolerance).ToList();
            if (bullets.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: no marker bullet to the left of the lines", 1, 1,
                    [new(assertion, 1, "no bullet")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);

        static int Spacing(List<Component> a, List<Component> b)
        {
            // The nearest horizontal distance between any stated-colour pair: a margin that
            // failed to apply puts a pair flush together (gap 0); any overlap also reads 0.
            var best = int.MaxValue;
            foreach (var x in a)
            foreach (var y in b)
            {
                var gap = Math.Max(Math.Max(y.Left - x.Right, x.Left - y.Right), 0);
                if (gap < best) best = gap;
            }
            return best;
        }
    }

    /// <summary>The stated number of ink bands below the instructions render identically —
    /// band-by-band pixel comparison, so text lines in any font count.</summary>
    private static WptRunner.RunResult LinesSame(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var bands = InkBands(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var want = check.Count ?? 2;
        if (bands.Count != want)
            return new(WptRunner.Cat.Fail, $"{assertion}: {bands.Count} ink bands below the instructions", 1, 1,
                [new(assertion, 1, $"{bands.Count} bands, not {want}")], 0);
        var left = bands[0].Members.Min(m => m.Left);
        foreach (var band in bands.Skip(1))
        {
            var bandLeft = band.Members.Min(m => m.Left);
            if (Math.Abs(bandLeft - left) > 2 * EdgeTolerance)
                return new(WptRunner.Cat.Fail, $"{assertion}: a line starts at x {bandLeft}, the first at {left}", 1, 1,
                    [new(assertion, 1, "lines do not start at the same x")], 0);
            var diff = BandDiff(bands[0], band, bitmap, want: want);
            if (diff is { } failure)
                return new(WptRunner.Cat.Fail, $"{assertion}: {failure}", 1, 1, [new(assertion, 1, failure)], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>Pixel-compares two ink bands aligned at their left edges and tops.</summary>
    private static string? BandDiff((int Top, int Bottom, List<Component> Members) a,
        (int Top, int Bottom, List<Component> Members) b, SKBitmap bitmap, int want)
    {
        var aLeft = a.Members.Min(m => m.Left);
        var bLeft = b.Members.Min(m => m.Left);
        var height = Math.Min(a.Bottom - a.Top, b.Bottom - b.Top);
        var width = Math.Min(a.Members.Max(m => m.Right) - aLeft, b.Members.Max(m => m.Right) - bLeft);
        if (Math.Abs((a.Bottom - a.Top) - (b.Bottom - b.Top)) > 3 || Math.Abs(width - (a.Members.Max(m => m.Right) - aLeft)) > 3)
            return "the lines differ in size";
        var pixels = bitmap.Pixels;
        var bitmapWidth = bitmap.Width;
        for (var y = 0; y < height; y++)
        for (var x = 0; x < width; x++)
        {
            var pa = pixels[(a.Top + y) * bitmapWidth + aLeft + x];
            var pb = pixels[(b.Top + y) * bitmapWidth + bLeft + x];
            if (Distance(pa, pb) > PixelTolerance)
                return $"pixels differ at (+{x},+{y})";
        }
        return null;
    }

    /// <summary>The stated box's tiled image: the ink column/row profile is periodic, exactly
    /// one row of tiles when the sentence says so, and the stated edge tile is complete.</summary>
    private static WptRunner.RunResult ImageTiled(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var box = FindEmptyBox(root, top);
        if (box is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no empty test box below the instructions", 0, 0);
        var region = SKRectI.Round(box.Box.BorderBox);
        region.Inflate(-3, -3);
        if (region.Width < 16 || region.Height < 16)
            return new(WptRunner.Cat.Unsupported, "Visual check: the test box is too small to scan", 0, 0);
        var columns = Profile(bitmap, region, horizontal: true);
        if (columns.Max() == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: the box paints no image", 1, 1, [new(assertion, 1, "no ink")], 0);
        var period = BestPeriod(columns, 8, region.Width / 2);
        if (period is null)
            return new(WptRunner.Cat.Fail, $"{assertion}: the ink is not periodically tiled", 1, 1,
                [new(assertion, 1, "no tile period")], 0);
        var p = period.Value;
        if (check.Variant is "row-only" or "row-right")
        {
            var rows = Profile(bitmap, region, horizontal: false);
            var inkRows = rows.Select((v, i) => (v, i)).Where(t => t.v > 0).ToList();
            if (inkRows.Count == 0 || inkRows[^1].i - inkRows[0].i > Math.Max(p, 12) + 4)
                return new(WptRunner.Cat.Fail, $"{assertion}: tiles repeat down the box too", 1, 1,
                    [new(assertion, 1, "ink spans more than one tile row")], 0);
        }
        if (check.Variant is "row-right" or "grid-topright")
        {
            var right = WindowDiff(columns, region.Width - p, p, region.Width - 2 * p, p);
            if (right > 3)
                return new(WptRunner.Cat.Fail, $"{assertion}: the right tile is cut off (profile diff {right:F1})", 1, 1,
                    [new(assertion, 1, $"rightmost tile differs from the interior ({right:F1})")], 0);
        }
        if (check.Variant == "grid-bottom")
        {
            var rows = Profile(bitmap, region, horizontal: false);
            var rowPeriod = BestPeriod(rows, 8, region.Height / 2);
            if (rowPeriod is null)
                return new(WptRunner.Cat.Fail, $"{assertion}: the tiles do not repeat vertically", 1, 1,
                    [new(assertion, 1, "no vertical period")], 0);
            var rp = rowPeriod.Value;
            var bottom = WindowDiff(rows, region.Height - rp, rp, region.Height - 2 * rp, rp);
            if (bottom > 3)
                return new(WptRunner.Cat.Fail, $"{assertion}: the bottom tile row is cut off (profile diff {bottom:F1})", 1, 1,
                    [new(assertion, 1, $"bottom row differs ({bottom:F1})")], 0);
        }
        if (check.Variant == "grid-topright")
        {
            var rows = Profile(bitmap, region, horizontal: false);
            var topDiff = WindowDiff(rows, 0, p, p, p);
            if (topDiff > 3)
                return new(WptRunner.Cat.Fail, $"{assertion}: the top tile row is cut off (profile diff {topDiff:F1})", 1, 1,
                    [new(assertion, 1, $"top row differs ({topDiff:F1})")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>Ink pixel counts per column (horizontal) or row (vertical) of the region.</summary>
    private static int[] Profile(SKBitmap bitmap, SKRectI region, bool horizontal)
    {
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        var background = CropBackground(bitmap, region);
        var along = horizontal ? region.Width : region.Height;
        var across = horizontal ? region.Height : region.Width;
        var profile = new int[along];
        for (var i = 0; i < along; i++)
        for (var j = 0; j < across; j++)
        {
            var x = horizontal ? region.Left + i : region.Left + j;
            var y = horizontal ? region.Top + j : region.Top + i;
            if (Distance(pixels[y * width + x], background) > InkThreshold)
                profile[i]++;
        }
        return profile;
    }

    /// <summary>The strongest period in the profile: the d in [min, max] whose shifted
    /// profile best matches, requiring at least two periods' worth of ink.</summary>
    private static int? BestPeriod(int[] profile, int min, int max)
    {
        double best = double.MaxValue;
        int? bestD = null;
        var ink = profile.Count(v => v > 0);
        if (ink < 4) return null;
        for (var d = min; d <= max; d++)
        {
            long diff = 0;
            var n = 0;
            for (var x = 0; x + d < profile.Length; x++)
            {
                diff += Math.Abs(profile[x] - profile[x + d]);
                n++;
            }
            if (n == 0) continue;
            var mean = (double)diff / n;
            if (mean < best) { best = mean; bestD = d; }
        }
        if (bestD is not { } period) return null;
        if (period * 2 > profile.Length) return null;
        // A real period must actually repeat: compare two adjacent windows away from the edges.
        var windowDiff = WindowDiff(profile, period, period, 2 * period, period);
        return windowDiff <= 4 ? period : null;
    }

    /// <summary>Mean absolute difference of two profile windows.</summary>
    private static double WindowDiff(int[] profile, int aStart, int aLen, int bStart, int bLen)
    {
        if (aStart < 0 || bStart < 0 || aStart + aLen > profile.Length || bStart + bLen > profile.Length)
            return double.MaxValue;
        double diff = 0;
        for (var x = 0; x < aLen; x++)
            diff += Math.Abs(profile[aStart + x] - profile[bStart + x]);
        return diff / aLen;
    }

    /// <summary>Every thin bar on the left has a same-coloured box of the same height among
    /// the boxes (margin-collapse-with-clearance targets).</summary>
    private static WptRunner.RunResult BarsMatch(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var bars = components.Where(s => s.Width <= 14 && s.Height >= 20 && Named.ContainsValue(s.Color)).ToList();
        if (bars.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no coloured bars below the instructions", 1, 1,
                [new(assertion, 1, "no bars")], 0);
        foreach (var bar in bars)
        {
            var match = components.Where(s => !ReferenceEquals(s, bar) && s.Width > 14 && MatchesColor(s.Color, bar.Color) &&
                                              Math.Abs(s.Height - bar.Height) <= 2).ToList();
            if (match.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: the {bar.Color} bar ({bar.Width}x{bar.Height} at {bar.Left},{bar.Top}) has no matching box", 1, 1,
                    [new(assertion, 1, $"no same-colour {bar.Height}px box")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);

        static bool MatchesColor(SKColor a, SKColor b) => Distance(a, b) <= 24;
    }

    /// <summary>One solid bar on top of a rows-by-cols grid of boxes.</summary>
    private static WptRunner.RunResult BarGrid(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var want = check.Rows! * check.Cols! + 1;
        if (shapes.Count != want)
            return new(WptRunner.Cat.Fail, $"{assertion}: {shapes.Count} shapes below the instructions (want bar + {check.Rows}x{check.Cols})", 1, 1,
                [new(assertion, 1, "wrong shape count")], 0);
        var ordered = shapes.OrderBy(s => s.Top).ThenBy(s => s.Left).ToList();
        var bar = ordered[0];
        if (bar.Height > 3 * ordered[1].Height || bar.Width < ordered[1].Width * 2)
            return new(WptRunner.Cat.Fail, $"{assertion}: the first shape is not a wide bar", 1, 1,
                [new(assertion, 1, "no bar on top")], 0);
        var grid = ordered.Skip(1).ToList();
        for (var r = 0; r < check.Rows; r++)
        for (var c = 0; c < check.Cols; c++)
        {
            var cell = grid[r * check.Cols.Value + c];
            var reference = grid[0];
            if (Math.Abs(cell.Width - reference.Width) > 2 || Math.Abs(cell.Height - reference.Height) > 2)
                return new(WptRunner.Cat.Fail, $"{assertion}: the grid cells differ in size", 1, 1,
                    [new(assertion, 1, "uneven grid")], 0);
            if (c > 0 && Math.Abs(cell.Left - grid[r * check.Cols.Value + c - 1].Right) > 4)
                return new(WptRunner.Cat.Fail, $"{assertion}: the grid cells are not adjacent in row {r}", 1, 1,
                    [new(assertion, 1, "grid gap")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The stated-color box's ink reaches the bottom of the rendered viewport.</summary>
    private static WptRunner.RunResult ViewportBottom(VisualCheck check, SKBitmap bitmap)
    {
        var assertion = Describe(check);
        var height = bitmap.Height;
        var width = bitmap.Width;
        var pixels = bitmap.Pixels;
        // The box's ink is expected to touch the bottom edge — that is the stated condition,
        // so the scan reads the last rows directly instead of flagging them clipped.
        var inkAtBottom = 0;
        var colors = new Dictionary<uint, long>();
        for (var y = height - 3; y < height; y++)
        for (var x = 0; x < width; x++)
        {
            var p = pixels[y * width + x];
            if (p == 0 || (SKColor)p is { Red: 255, Green: 255, Blue: 255 }) continue;
            inkAtBottom++;
            colors[(uint)p] = colors.GetValueOrDefault((uint)p) + 1;
        }
        var dominant = colors.Count > 0 ? new SKColor(colors.MaxBy(kv => kv.Value).Key) : SKColors.White;
        return inkAtBottom > 50 && Matches(check.Color!, dominant)
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: the {check.Color} box does not reach the bottom of the viewport", 1, 1,
                [new(assertion, 1, $"bottom ink {inkAtBottom}px, dominant {dominant}")], 0);
    }

    /// <summary>The middle cell/row/column of a three-by-three table carries the stated
    /// border color (collapsed-border winners read from the render).</summary>
    private static WptRunner.RunResult CellBorder(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var table = FindTable(root, top);
        if (table is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no table below the instructions", 0, 0);
        var cells = TableCells(table);
        if (cells.Count < 9)
            return new(WptRunner.Cat.Unsupported, $"Visual check: the table has {cells.Count} cells, not nine", 0, 0);
        var targets = check.Target switch
        {
            "cell" => new List<LayoutNode> { cells[4] },
            "row" => new List<LayoutNode> { cells[3], cells[4], cells[5] },
            _ => new List<LayoutNode> { cells[1], cells[4], cells[7] },
        };
        foreach (var cell in targets)
        {
            var box = cell.Box.BorderBox;
            var crop = SKRectI.Round(new SKRect(box.Left - 10, box.Top - 10, box.Right + 10, box.Bottom + 10));
            var ring = RingSignature(bitmap, crop, box, 8);
            if (!ring.Readable)
                return new(WptRunner.Cat.Unsupported, $"Visual check: the cell's ring is not readable: {ring.Note}", 0, 0);
            if (ring.Style == "none")
                return new(WptRunner.Cat.Fail, $"{assertion}: the cell paints no border", 1, 1,
                    [new(assertion, 1, "no border")], 0);
            if (check.Color is { } want && !Matches(want, ring.Color) && ring.ToneColors.All(t => !Matches(want, t)))
                return new(WptRunner.Cat.Fail, $"{assertion}: the {check.Target}'s border reads #{ring.Color.Red:X2}{ring.Color.Green:X2}{ring.Color.Blue:X2}, not {want}", 1, 1,
                    [new(assertion, 1, $"border color #{ring.Color.Red:X2}{ring.Color.Green:X2}{ring.Color.Blue:X2}")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);

        static string ShowTone(SKColor c) => $"#{c.Red:X2}{c.Green:X2}{c.Blue:X2}";
    }

    private static LayoutNode? FindTable(LayoutNode root, int top)    {
        LayoutNode? best = null;
        void Walk(LayoutNode node)
        {
            if (best is not null) return;
            if (!node.TagName.StartsWith('#') && node.Box.BorderBox.Top >= top)
            {
                var display = node.TryResolveStyle("display", out var d) ? d : node.Style?.GetPropertyValueSafe("display");
                if (display is "table") { best = node; return; }
            }
            foreach (var child in node.Children) Walk(child);
        }
        Walk(root);
        return best;
    }

    private static List<LayoutNode> TableCells(LayoutNode table)
    {
        var cells = new List<LayoutNode>();
        void Walk(LayoutNode node)
        {
            var display = node.TryResolveStyle("display", out var d) ? d : node.Style?.GetPropertyValueSafe("display");
            if (display is "table-cell") { cells.Add(node); return; }
            foreach (var child in node.Children) Walk(child);
        }
        Walk(table);
        return cells;
    }

    /// <summary>A small square of the stated color sits at each corner of the stated box.</summary>
    private static WptRunner.RunResult Corners(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var pool = components;
        var box = pool.FirstOrDefault(s => s.Rectangular && Math.Min(s.Width, s.Height) >= 40 &&
            (check.BoxColor is null || Matches(check.BoxColor, s.Color)));
        if (box.Width == 0)
            box = pool.FirstOrDefault(s => !s.Rectangular && (long)s.Width * s.Height >= 10000 &&
                (check.BoxColor is null || Matches(check.BoxColor, s.Color)));
        var squares = pool.Where(s => Math.Max(s.Width, s.Height) <= 40 && Matches(check.Color!, s.Color)).ToList();
        if (box.Width == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no box below the instructions", 1, 1, [new(assertion, 1, "no box")], 0);
        if (squares.Count != 4)
            return new(WptRunner.Cat.Fail, $"{assertion}: {squares.Count} {check.Color} squares (want 4)", 1, 1,
                [new(assertion, 1, "wrong square count")], 0);
        var covered = new List<string>();
        foreach (var (name, x, y) in new[] { ("upper-left", box.Left, box.Top), ("upper-right", box.Right, box.Top),
                                            ("lower-left", box.Left, box.Bottom), ("lower-right", box.Right, box.Bottom) })
        {
            if (squares.Any(s => Math.Abs((s.Left + s.Right) / 2 - x) <= 12 && Math.Abs((s.Top + s.Bottom) / 2 - y) <= 12))
                covered.Add(name);
        }
        return covered.Count == 4
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: corners not covered: {string.Join(", ", new[] { "upper-left", "upper-right", "lower-left", "lower-right" }.Except(covered))}", 1, 1,
                [new(assertion, 1, $"{covered.Count}/4 corners")], 0);
    }

    /// <summary>Exactly the stated count of top-level rectangles below the instructions.</summary>
    private static WptRunner.RunResult BoxCount(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var rectangles = check.Color is { } color
            ? shapes.Where(s => s.Rectangular && Matches(color, s.Color)).ToList()
            : shapes.Where(s => s.Rectangular).ToList();
        var want = check.Count ?? 1;
        return rectangles.Count == want
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: {rectangles.Count} boxes below the instructions (want {want})", 1, 1,
                [new(assertion, 1, $"{rectangles.Count} boxes")], 0);
    }

    /// <summary>Two bars of colorA with a colorB bar of the same width between them.</summary>
    private static WptRunner.RunResult ThreeBars(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        var outer = shapes.Where(s => Matches(check.ColorA!, s.Color)).ToList();
        var middle = shapes.Where(s => Matches(check.ColorB!, s.Color)).ToList();
        if (outer.Count != 2 || middle.Count != 1)
            return new(WptRunner.Cat.Fail, $"{assertion}: {outer.Count} {check.ColorA} bars and {middle.Count} {check.ColorB} bar", 1, 1,
                [new(assertion, 1, "wrong bar counts")], 0);
        var widths = outer.Select(s => s.Width).Concat([middle[0].Width]).ToList();
        if (widths.Max() - widths.Min() > 2 * EdgeTolerance)
            return new(WptRunner.Cat.Fail, $"{assertion}: the bars' widths differ ({string.Join(", ", widths)})", 1, 1,
                [new(assertion, 1, "unequal bars")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The paragraph's first ink component is the stated colour and the rest of the
    /// paragraph's ink is not (::first-letter).</summary>
    private static WptRunner.RunResult FirstLetterColor(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string sentence, string path)
    {
        var assertion = Describe(check);
        // "Test passes if the letter 'F' below is green" states the condition about a Filler
        // Text element that follows the instructions; the "first letter of this paragraph"
        // family states it about the instruction paragraph itself, which carries no Filler
        // Text — so the filler anchor wins when one exists below the instructions.
        var node = FindFiller(root, top) ?? InstructionNode(root, sentence);
        if (node is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no paragraph below the instructions", 0, 0);
        var ink = ElementInk(bitmap, node, 1, out _);
        if (ink.Count < 2)
            return new(WptRunner.Cat.Fail, $"{assertion}: the paragraph painted {ink.Count} ink components", 1, 1,
                [new(assertion, 1, "not enough ink to separate a first letter")], 0);
        var ordered = ink.OrderBy(c => c.Top).ThenBy(c => c.Left).ToList();
        var firstLine = ordered.Where(c => c.Top < ordered[0].Bottom).ToList();
        var firstLetter = firstLine.MinBy(c => c.Left);
        if (!Matches(check.Color!, firstLetter.Color))
            return new(WptRunner.Cat.Fail, $"{assertion}: the first letter is {firstLetter.Color}", 1, 1,
                [new(assertion, 1, $"first letter {firstLetter.Color}")], 0);
        var rest = ink.Where(c => !ReferenceEquals(c, firstLetter)).ToList();
        if (rest.All(c => Matches(check.Color!, c.Color)))
            return new(WptRunner.Cat.Fail, $"{assertion}: the whole paragraph is {check.Color}", 1, 1,
                [new(assertion, 1, "the rest of the paragraph is also coloured")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The first text band's ink is the stated colour and the next band's is not.</summary>
    private static WptRunner.RunResult FirstLineColor(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var bands = InkBands(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        if (bands.Count < 2)
            return new(WptRunner.Cat.Unsupported, $"Visual check: only {bands.Count} bands below the instructions", 0, 0);
        var first = DominantOf(bands[0].Members, bitmap);
        var second = DominantOf(bands[1].Members, bitmap);
        if (!Matches(check.Color!, first))
            return new(WptRunner.Cat.Fail, $"{assertion}: the first line is {first}", 1, 1,
                [new(assertion, 1, $"first line {first}")], 0);
        if (Matches(check.Color!, second))
            return new(WptRunner.Cat.Fail, $"{assertion}: the other lines are {second} too", 1, 1,
                [new(assertion, 1, "second line also coloured")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    private static SKColor DominantOf(List<Component> members, SKBitmap bitmap)
    {
        // The members are already ink components: the largest one's own colour is the band's.
        return members.MaxBy(c => (long)c.Width * c.Height) is { } biggest ? biggest.Color : SKColors.White;
    }

    /// <summary>All but the last text band share both edges, and the last shares the left —
    /// text-align: justify.</summary>
    private static WptRunner.RunResult Justify(SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(new VisualCheck("justify"));
        var bands = InkBands(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        if (bands.Count < 2)
            return new(WptRunner.Cat.Unsupported, $"Visual check: only {bands.Count} text bands below the instructions", 0, 0);
        var lefts = bands.Select(b => b.Members.Min(m => m.Left)).ToList();
        var rights = bands.Select(b => b.Members.Max(m => m.Right)).ToList();
        for (var k = 0; k < bands.Count - 1; k++)
        {
            if (Math.Abs(lefts[k] - lefts[0]) > 2 || Math.Abs(rights[k] - rights[0]) > 2)
                return new(WptRunner.Cat.Fail, $"{assertion}: line {k} does not line up on both edges (left {lefts[k]}, right {rights[k]})", 1, 1,
                    [new(assertion, 1, "line not justified")], 0);
        }
        // The last line of a justified paragraph never extends past the justified lines' edge.
        if (Math.Abs(lefts[^1] - lefts[0]) > 2 || rights[^1] > rights[0] + 2)
            return new(WptRunner.Cat.Fail, $"{assertion}: the last line does not sit inside the justified edges (left {lefts[^1]}, right {rights[^1]})", 1, 1,
                [new(assertion, 1, "last line not left-aligned inside the block")], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>A thin line of the stated color sits directly above/below/left/right of the
    /// instruction paragraph, or of every occurrence of the stated word.</summary>
    private static WptRunner.RunResult TextBand(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string sentence, string path)
    {
        var assertion = Describe(check);
        List<LayoutNode> targets;
        if (check.Needle is { } needle)
        {
            targets = FindAllNodesByText(root, top, needle);
            if (targets.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: no occurrence of '{needle}' below the instructions", 1, 1,
                    [new(assertion, 1, "needle not found")], 0);
        }
        else
        {
            var node = InstructionNode(root, sentence);
            if (node is null)
                return new(WptRunner.Cat.Unsupported, "Visual check: no paragraph below the instructions", 0, 0);
            targets = [node];
        }
        foreach (var target in targets)
        {
            var ink = ElementInk(bitmap, target, 10, out var box);
            var text = ink.Where(c => c.Height > 5).ToList();
            if (text.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: the target painted no readable ink", 1, 1,
                    [new(assertion, 1, "no ink")], 0);
            int textTop = text.Min(c => c.Top), textBottom = text.Max(c => c.Bottom);
            int textLeft = text.Min(c => c.Left), textRight = text.Max(c => c.Right);
            bool IsBand(Component c) => c.Height <= 6 && c.Width >= (textRight - textLeft) / 3;
            bool IsColumn(Component c) => c.Width <= 6 && c.Height >= (textBottom - textTop) / 3;
            var bands = ink.Where(c => check.Side is "above" or "below" ? IsBand(c) : IsColumn(c)).Where(c =>
                check.Side == "above" ? c.Bottom > textTop - 10 && c.Bottom <= textTop + 2 :
                check.Side == "below" ? c.Top >= textBottom - 2 && c.Top < textBottom + 10 :
                check.Side == "left" ? c.Right > textLeft - 10 && c.Right <= textLeft + 2 :
                c.Left >= textRight - 2 && c.Left < textRight + 10).ToList();
            if (check.Count is { } want && bands.Count < want)
                return new(WptRunner.Cat.Fail, $"{assertion}: {bands.Count} {check.Color} line(s) {check.Side} the text (want {want})", 1, 1,
                    [new(assertion, 1, $"{bands.Count}/{want} bands")], 0);
            if (check.Count is null && bands.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: no {check.Color} line {check.Side} the text", 1, 1,
                    [new(assertion, 1, "no band")], 0);
            if (check.Color is { } color && bands.Any(b => !Matches(color, b.Color)))
                return new(WptRunner.Cat.Fail, $"{assertion}: a line beside the text is not {color}", 1, 1,
                    [new(assertion, 1, "band color")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>The stated (rightmost/leftmost) ink of the line is the stated colour.</summary>
    private static WptRunner.RunResult EdgeLetter(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        List<Component> ink;
        if (check.Needle is { } needle)
        {
            var node = FindNodeByText(root, top, needle);
            if (node is null)
                return new(WptRunner.Cat.Fail, $"{assertion}: no element renders '{needle}'", 1, 1,
                    [new(assertion, 1, "needle not found")], 0);
            ink = ElementInk(bitmap, node, 1, out _);
        }
        else
        {
            var bands = InkBands(bitmap, top, out var clipped);
            if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
            if (bands.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: no ink below the instructions", 1, 1,
                    [new(assertion, 1, "no ink")], 0);
            ink = bands[0].Members;
        }
        if (ink.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: the text painted no ink", 1, 1, [new(assertion, 1, "no ink")], 0);
        var edge = check.Side == "leftmost" ? ink.MinBy(c => c.Left) : ink.MaxBy(c => c.Right);
        return Matches(check.Color!, edge.Color)
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: the {check.Side} ink is {edge.Color}", 1, 1,
                [new(assertion, 1, $"edge ink {edge.Color}")], 0);
    }

    /// <summary>Three overlapping boxes paint bottom-to-top in the stated colour order: each
    /// overlap region shows the higher box's colour.</summary>
    private static WptRunner.RunResult StackOrder(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var colors = check.Colors!;
        var boxes = new List<Component>();
        foreach (var name in colors)
        {
            var ofColor = components.Where(s => Matches(name, s.Color)).ToList();
            if (ofColor.Count == 0)
                return new(WptRunner.Cat.Fail, $"{assertion}: no {name} box below the instructions", 1, 1,
                    [new(assertion, 1, $"{name} missing")], 0);
            boxes.Add(ofColor.OrderBy(s => -(long)s.Width * s.Height).First());
        }
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        for (var lower = 0; lower < boxes.Count - 1; lower++)
        {
            var topBox = boxes[lower + 1];
            var iLeft = Math.Max(boxes[lower].Left, topBox.Left);
            var iRight = Math.Min(boxes[lower].Right, topBox.Right);
            var iTop = Math.Max(boxes[lower].Top, topBox.Top);
            var iBottom = Math.Min(boxes[lower].Bottom, topBox.Bottom);
            if (iRight - iLeft <= 2 || iBottom - iTop <= 2)
                return new(WptRunner.Cat.Fail, $"{assertion}: the {colors[lower]} and {colors[lower + 1]} boxes do not overlap", 1, 1,
                    [new(assertion, 1, "no overlap")], 0);
            // Where the boxes overlap, the lower box's colour must be gone — the higher box
            // (or any even higher one) paints there. The overlap centre can be covered by a
            // third box, so the whole region is counted, not sampled.
            long lowerPixels = 0, total = 0;
            for (var y = iTop; y < iBottom; y++)
            for (var x = iLeft; x < iRight; x++)
            {
                total++;
                if (Distance(new SKColor((uint)pixels[y * width + x]), boxes[lower].Color) <= 32)
                    lowerPixels++;
            }
            if (lowerPixels > total / 50)
                return new(WptRunner.Cat.Fail, $"{assertion}: the {colors[lower]} box paints over the {colors[lower + 1]} box ({lowerPixels * 100 / total}% of the overlap)", 1, 1,
                    [new(assertion, 1, "wrong paint order")], 0);
        }
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
    }

    /// <summary>No border paints around the stated text: the ring region reads "none".</summary>
    private static WptRunner.RunResult NoRing(VisualCheck check, SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var node = check.Needle is { } needle ? FindNodeByText(root, top, needle) : TextElementsBelow(root, top).FirstOrDefault();
        if (node is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no text element below the instructions", 0, 0);
        var box = node.Box.BorderBox;
        var crop = SKRectI.Round(new SKRect(box.Left - 8, box.Top - 8, box.Right + 8, box.Bottom + 8));
        var ring = RingSignature(bitmap, crop, box, 6);
        if (!ring.Readable)
            return new(WptRunner.Cat.Unsupported, $"Visual check: the ring region is not readable: {ring.Note}", 0, 0);
        return ring.Style == "none"
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: a border paints around the text ({ring.Style ?? "unclassified"})", 1, 1,
                [new(assertion, 1, "ring ink present")], 0);
    }

    /// <summary>The filler text paints below (or above) its sibling box.</summary>
    private static WptRunner.RunResult TextBelowBox(VisualCheck check, LayoutNode root, int top, string path)
    {
        var assertion = Describe(check);
        var filler = FindFiller(root, top);
        if (filler is null || filler.Parent is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no filler-text element below the instructions", 0, 0);
        var siblings = filler.Parent.Children.Where(c => !c.TagName.StartsWith('#')).ToList();
        var index = siblings.IndexOf(filler);
        var box = check.Side == "below" ? siblings.ElementAtOrDefault(index - 1) : siblings.ElementAtOrDefault(index + 1);
        if (box is null)
            return new(WptRunner.Cat.Unsupported, "Visual check: no sibling box beside the filler text", 0, 0);
        var ok = check.Side == "below"
            ? filler.Box.BorderBox.Top >= box.Box.BorderBox.Bottom - EdgeTolerance
            : filler.Box.BorderBox.Bottom <= box.Box.BorderBox.Top + EdgeTolerance;
        return ok
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: the filler text does not sit {check.Side} the box", 1, 1,
                [new(assertion, 1, $"filler top {filler.Box.BorderBox.Top}, box bottom {box.Box.BorderBox.Bottom}")], 0);
    }

    /// <summary>Two filler-text lines render identically and the bottom one carries a marker
    /// bullet on its left.</summary>
    private static WptRunner.RunResult TextMarkerMatch(SKBitmap bitmap, LayoutNode root, int top, string path)
    {
        var assertion = Describe(new VisualCheck("text-marker-match"));
        var fillers = FindAllNodesByText(root, top, "filler text");
        if (fillers.Count < 2)
            return new(WptRunner.Cat.Unsupported, $"Visual check: only {fillers.Count} filler-text elements", 0, 0);
        var firstInk = ElementInk(bitmap, fillers[0], 1, out var firstBox);
        var secondInk = ElementInk(bitmap, fillers[^1], 1, out var secondBox);
        if (firstInk.Count == 0 || secondInk.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: a filler text painted no ink", 1, 1,
                [new(assertion, 1, "no ink")], 0);
        if (firstInk.Count != secondInk.Count ||
            firstInk.Zip(secondInk, (a, b) => Math.Abs(a.Left - b.Left) <= 2 && Math.Abs(a.Width - b.Width) <= 2).Any(ok => !ok))
            return new(WptRunner.Cat.Fail, $"{assertion}: the lines do not match styles", 1, 1,
                [new(assertion, 1, $"{firstInk.Count} vs {secondInk.Count} ink components")], 0);
        var components = Components(bitmap, top, out _);
        var bullets = components.Where(s => Math.Max(s.Width, s.Height) <= 24 &&
            s.Right <= secondBox.Left + EdgeTolerance && s.Top < secondBox.Bottom && s.Bottom > secondBox.Top).ToList();
        return bullets.Count >= 1
            ? new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0)
            : new(WptRunner.Cat.Fail, $"{assertion}: no marker bullet beside the bottom line", 1, 1,
                [new(assertion, 1, "no bullet")], 0);
    }

    /// <summary>The box's four sides read the stated per-side style and colour — or, in
    /// "distinct" mode, every side reads different from the others.</summary>
    private static WptRunner.RunResult BorderSides(VisualCheck check, SKBitmap bitmap, int top, string path)
    {
        var assertion = Describe(check);
        var components = Components(bitmap, top, out var clipped);
        if (clipped) return new(WptRunner.Cat.Unsupported, "Visual check: content reaches the viewport edge", 0, 0);
        var shapes = TopLevel(components);
        if (shapes.Count == 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: no ink below the instructions", 1, 1, [new(assertion, 1, "no ink")], 0);
        int left = shapes.Min(s => s.Left), right = shapes.Max(s => s.Right);
        int topEdge = shapes.Min(s => s.Top), bottomEdge = shapes.Max(s => s.Bottom);
        // One ring only: every component lies on the perimeter of the union box.
        foreach (var s in shapes)
        {
            var onVertical = Math.Abs(s.Left - left) <= 2 * EdgeTolerance || Math.Abs(s.Right - right) <= 2 * EdgeTolerance;
            var onHorizontal = Math.Abs(s.Top - topEdge) <= 2 * EdgeTolerance || Math.Abs(s.Bottom - bottomEdge) <= 2 * EdgeTolerance;
            if (!onVertical && !onHorizontal)
                return new(WptRunner.Cat.Unsupported, $"Visual check: extra ink at ({s.Left},{s.Top}) is not on the box perimeter", 0, 0);
        }
        var crop = SKRectI.Round(new SKRect(left - 4, topEdge - 4, right + 4, bottomEdge + 4));
        var background = CropBackground(bitmap, crop);
        var reads = new Dictionary<string, (string? Style, SKColor Color)>();
        foreach (var (name, horizontal, span) in new (string, bool, (int From, int To, int Band, int Depth))[]
        {
            ("top", true, (left, right, topEdge, 24)),
            ("bottom", true, (left, right, bottomEdge - 24, 24)),
            ("left", false, (topEdge, bottomEdge, left, 24)),
            ("right", false, (topEdge, bottomEdge, right - 24, 24)),
        })
        {
            var read = ReadSideScan(bitmap, background, horizontal, span);
            if (read.Unreadable)
                return new(WptRunner.Cat.Unsupported, $"Visual check: the {name} side's band is not scannable", 0, 0);
            var color = SideColor(bitmap, background, horizontal, span);
            reads[name] = (read.Style, color);
        }
        if (check.Mode == "distinct")
        {
            var tuples = reads.Select(kv => $"{kv.Value.Style}/{kv.Value.Color}").ToList();
            if (reads.Values.Any(r => r.Style is null or "none"))
                return new(WptRunner.Cat.Fail, $"{assertion}: a side has no readable border style", 1, 1,
                    [new(assertion, 1, string.Join(", ", tuples))], 0);
            if (tuples.Distinct().Count() < 4)
                return new(WptRunner.Cat.Fail, $"{assertion}: the sides do not all read different ({string.Join(", ", tuples)})", 1, 1,
                    [new(assertion, 1, string.Join(", ", tuples))], 0);
            return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);
        }
        var failures = new List<string>();
        foreach (var (side, want) in check.Sides!)
        {
            var (style, color) = reads[side];
            if (want.Style is { } wantStyle && style != wantStyle)
                failures.Add($"{side} reads {style ?? "unclassified"}, not {wantStyle}");
            if (want.Color is { } wantColor && !Matches(wantColor, color))
                failures.Add($"{side} reads {Show(color)}, not {wantColor}");
        }
        if (failures.Count > 0)
            return new(WptRunner.Cat.Fail, $"{assertion}: {string.Join("; ", failures)}", 1, 1,
                [new(assertion, 1, string.Join("; ", failures))], 0);
        return new(WptRunner.Cat.Pass, assertion, 1, 0, [new(assertion, 0, null)], 0);

        static string Show(SKColor c) => $"#{c.Red:X2}{c.Green:X2}{c.Blue:X2}";
    }

    /// <summary>The dominant ink colour within one side's border band.</summary>
    private static SKColor SideColor(SKBitmap bitmap, SKColor background, bool horizontal, (int From, int To, int Band, int Depth) span)
    {
        var (from, to, bandStart, depth) = span;
        var pixels = bitmap.Pixels;
        var width = bitmap.Width;
        var counts = new Dictionary<uint, long>();
        for (var d = 0; d < depth; d++)
        for (var p = from; p < to; p++)
        {
            var (x, y) = horizontal ? (p, bandStart + d) : (bandStart + d, p);
            if (x < 0 || x >= bitmap.Width || y < 0 || y >= bitmap.Height) continue;
            var pixel = pixels[y * width + x];
            if (Distance(pixel, background) > InkThreshold)
                counts[(uint)pixel] = counts.GetValueOrDefault((uint)pixel) + 1;
        }
        return counts.Count == 0 ? background : new SKColor(counts.MaxBy(kv => kv.Value).Key);
    }


    internal static List<Component> Components(SKBitmap bitmap, SKRectI region, out bool clipped)
    {
        region.Intersect(new SKRectI(0, 0, bitmap.Width, bitmap.Height));
        int width = bitmap.Width, height = bitmap.Height;
        var pixels = bitmap.Pixels;
        var counts = new Dictionary<uint, int>();
        for (var y = region.Top; y < region.Bottom; y++)
        for (var x = region.Left; x < region.Right; x++)
            counts[(uint)pixels[y * width + x]] = counts.GetValueOrDefault((uint)pixels[y * width + x]) + 1;
        var background = counts.Count == 0 ? SKColors.White : (SKColor)counts.MaxBy(kv => kv.Value).Key;
        bool Ink(int i) => Distance(pixels[i], background) > InkThreshold;

        clipped = false;
        var seen = new bool[pixels.Length];
        var components = new List<Component>();
        var stack = new Stack<int>();
        for (var start = region.Top * width + region.Left; start < region.Bottom * width; start++)
        {
            var sx = start % width;
            if (sx < region.Left || sx >= region.Right) continue;
            if (seen[start] || !Ink(start)) continue;
            int left = int.MaxValue, right = -1, minY = int.MaxValue, maxY = -1;
            var members = new List<int>();
            seen[start] = true;
            stack.Push(start);
            while (stack.TryPop(out var i))
            {
                members.Add(i);
                int x = i % width, y = i / width;
                left = Math.Min(left, x); right = Math.Max(right, x); minY = Math.Min(minY, y); maxY = Math.Max(maxY, y);
                foreach (var (dx, dy) in Neighbours)
                {
                    int nx = x + dx, ny = y + dy;
                    if (nx < region.Left || nx >= region.Right || ny < region.Top || ny >= region.Bottom) continue;
                    var n = ny * width + nx;
                    if (!seen[n] && Ink(n) && Distance(pixels[n], pixels[i]) <= JoinThreshold) { seen[n] = true; stack.Push(n); }
                }
            }
            if (right == left || maxY == minY) continue;
            if (right == width - 1 || maxY == height - 1) clipped = true;
            var member = new HashSet<int>(members);
            components.Add(new(left, minY, right + 1, maxY + 1,
                PerimeterInked(member, width, left, minY, right, maxY), Dominant(pixels, members)));
        }
        return components;
    }

    /// <summary>Connected components of ink at or below <paramref name="top"/>.</summary>
    internal static List<Component> Components(SKBitmap bitmap, int top, out bool clipped) =>
        Components(bitmap, new SKRectI(0, top, bitmap.Width, bitmap.Height), out clipped);

    private static readonly (int, int)[] Neighbours = [(1, 0), (-1, 0), (0, 1), (0, -1)];

    private static int Distance(SKColor a, SKColor b) =>
        Math.Max(Math.Abs(a.Red - b.Red), Math.Max(Math.Abs(a.Green - b.Green), Math.Abs(a.Blue - b.Blue)));

    internal static List<Component> TopLevel(List<Component> components) =>
        components.Where(c => !components.Any(o => o.Contains(c))).OrderBy(c => c.Top).ThenBy(c => c.Left).ToList();

    /// <summary>Every bbox edge pixel is ink, except the four corners (antialiased corners
    /// blend both edges' partial coverage and can fall below the ink threshold).</summary>
    private static bool PerimeterInked(HashSet<int> member, int width, int left, int top, int right, int bottom)
    {
        if (right - left < 1 || bottom - top < 1) return false;
        for (var x = left + 1; x < right; x++)
            if (!member.Contains(top * width + x) || !member.Contains(bottom * width + x)) return false;
        for (var y = top + 1; y < bottom; y++)
            if (!member.Contains(y * width + left) || !member.Contains(y * width + right)) return false;
        return true;
    }

    private static SKColor Dominant(SKColor[] pixels, List<int> members)
    {
        var counts = new Dictionary<uint, int>();
        foreach (var i in members) counts[(uint)pixels[i]] = counts.GetValueOrDefault((uint)pixels[i]) + 1;
        var key = counts.MaxBy(kv => kv.Value).Key;
        var color = (SKColor)key;
        return new SKColor(color.Red, color.Green, color.Blue);
    }
}
